window.LEMMA_CONTENT_BACKUP = {"format":"lemma-blocks","version":5,"courses":[{"id":"kurz-algebraicke-zaklady-a-uprava-vyrazov","title":"Algebraické základy a úprava výrazov","lessons":[{"id":"zakladne-matematicke-pojmy-hierarchia","title":"Základné matematické pojmy: od rovnice k činiteľu","blocks":[{"p":"Ako rozoznáme rovnicu, výraz, člen a činiteľ v jednom zložitom zápise?"},{"h2":"Al-Chvárizmí a zrod slova algebra"},{"p":"Muhammad al-Chvárizmí napísal okolo roku 820 knihu o systematickom riešení rovníc. Slovo al-džabr z jej názvu dalo vzniknúť slovu algebra. Rovnice zapisoval slovami, nie dnešnými symbolmi, no jasne rozlišoval typy úloh a prípustné kroky ich riešenia. Na stole by vtedy neležal hotový vzorec, iba údaje a otázka, ktorú bolo treba rozhodnúť. Užitočný nápad vzniká vtedy, keď sa neurčité slová nahradia meraním: zmeníš jednu hodnotu, sleduješ následok a porovnáš ho s ďalším prípadom."},{"h2":"1. Rovnica"},{"p":["Matematický zápis budeme čítať ",{"b":"od najvyššej úrovne k najnižšej"},". Ako hlavný príklad použijeme jednu rovnicu:"]},{"math":"\\frac{2(x-3)(x+1)}{x+2}+3x^2-5x+1=7x-4"},{"p":[{"b":"Rovnica:"}," Celý zápis má tvar ",{"math":"L(x)=P(x)"},", teda ",{"b":"výraz = výraz"},". Preto je to ",{"b":"rovnica"},". \n",{"b":"Výraz:"}," Ľavá strana je ",{"b":"výraz "},{"math":"L(x)=\\frac{2(x-3)(x+1)}{x+2}+3x^2-5x+1"}," a pravá strana je ",{"b":"výraz "},{"math":"P(x)=7x-4"},". \n",{"b":"Neznáma: "},"je ",{"math":"x"},"; riešením alebo ",{"b":"koreňom "},"rovnice je každá prípustná hodnota, pri ktorej sa obe strany rovnajú."]},{"p":[{"b":"Podmienky:"}," sú pravidlá, ktoré určujú, ktoré hodnoty sú povolené a ktoré nie.\n",{"b":"Definičný obor:"}," je množina všetkých hodnôt, ktoré môže mať neznáma, aby mal výraz alebo funkcia zmysel.\n",{"b":"Základný obor:"}," je \nU\n=\nR čiže množina všetých reálnych čísel. Pri zlomkoch, odmocninách a ďalších obmedzeniach sa navyše zapisuje podmienka \nP\n.\n",{"math":"\\begin{array}{|l|c|c|c|} \\text{Delenie nulou} & \\displaystyle\\frac{5}{x-3} & x-3\\neq0\\Rightarrow x\\neq3 & D=\\mathbb{R}\\setminus\\{3\\} \\\\ \\hline \\text{Párna odmocnina} & \\sqrt{2x-6} & 2x-6\\geq0\\Rightarrow x\\geq3 & D=\\{x\\in\\mathbb{R}\\mid x\\geq3\\} \\\\ \\hline \\text{Odmocnina v menovateli} & \\displaystyle\\frac{1}{\\sqrt{x-4}} & x-4>0\\Rightarrow x>4 & D=\\{x\\in\\mathbb{R}\\mid x>4\\} \\\\ \\hline \\text{Logaritmus} & \\log(x+2) & x+2>0\\Rightarrow x>-2 & D=\\{x\\in\\mathbb{R}\\mid x>-2\\} \\\\ \\hline \\text{Logaritmus so základom} & \\log_a(x) & x>0,\\ a>0,\\ a\\neq1 & D=\\{x\\in\\mathbb{R}\\mid x>0\\} \\\\ \\hline \\text{Tangens} & \\displaystyle\\tan(x)=\\frac{\\sin(x)}{\\cos(x)} & \\displaystyle x\\neq\\frac{\\pi}{2}+k\\pi & \\displaystyle D=\\mathbb{R}\\setminus \\left\\{\\frac{\\pi}{2}+k\\pi\\mid k\\in\\mathbb{Z}\\right\\} \\\\ \\hline \\text{Kotangens} & \\displaystyle\\cot(x)=\\frac{\\cos(x)}{\\sin(x)} & x\\neq k\\pi & \\displaystyle D=\\mathbb{R}\\setminus \\left\\{k\\pi\\mid k\\in\\mathbb{Z}\\right\\} \\\\ \\hline \\text{Arkus sínus} & \\arcsin(2x-1) & -1\\leq2x-1\\leq1 & D=\\{x\\in\\mathbb{R}\\mid0\\leq x\\leq1\\} \\\\ \\hline \\text{Arkus kosínus} & \\arccos(3x) & -1\\leq3x\\leq1 & \\displaystyle D= \\left\\{x\\in\\mathbb{R}\\mid-\\frac{1}{3}\\leq x\\leq\\frac{1}{3}\\right\\} \\\\ \\hline \\text{Racionálny exponent, párny menovateľ} & \\displaystyle(x-2)^{\\frac{1}{2}} & x-2\\geq0\\Rightarrow x\\geq2 & D=\\{x\\in\\mathbb{R}\\mid x\\geq2\\} \\\\ \\hline \\text{Racionálny exponent, nepárny menovateľ} & \\displaystyle(x-2)^{\\frac{1}{3}} & x\\in\\mathbb{R} & D=\\mathbb{R} \\\\ \\hline \\text{Záporný exponent} & \\displaystyle(x+1)^{-2} & x+1\\neq0\\Rightarrow x\\neq-1 & D=\\mathbb{R}\\setminus\\{-1\\} \\\\ \\hline \\end{array}"}]},{"h2":"2. Výrazy a ich členy"},{"p":"Výraz je matematický zápis bez hlavného znaku rovnosti. Členy sú časti oddelené sčítaním alebo odčítaním. Ľavý výraz môžeme hierarchicky rozložiť:"},{"math":"L(x)=\\underbrace{\\frac{2(x-3)(x+1)}{x+2}}_{\\text{1. člen}}+\\underbrace{3x^2}_{\\text{2. člen}}-\\underbrace{5x}_{\\text{3. člen}}+\\underbrace{1}_{\\text{4. člen}}"},{"p":["V člene ",{"math":"3x^2"}," je číslo ",{"math":"3"}," ",{"b":"koeficient"},", ",{"math":"x"}," je ",{"b":"premenná"},", ",{"math":"2"}," je ",{"b":"exponent"}," a ",{"math":"x^2"}," je mocnina. Číslo bez premennej, napríklad ",{"math":"1"},", je ",{"b":"konštantný alebo absolútny člen"},"."]},{"h2":"3. Súčin, činitele a zlomok"},{"p":["V čitateli ",{"math":"2(x-3)(x+1)"}," sú činitele ",{"math":"2"},", ",{"math":"(x-3)"}," a ",{"math":"(x+1)"},". Celý zápis ",{"math":"\\frac{2(x-3)(x+1)}{x+2}"}," je podiel: horná časť je ",{"b":"čitateľ"},", dolná časť ",{"math":"x+2"}," je ",{"b":"menovateľ"},". Menovateľ nesmie byť nula, preto platí podmienka ",{"math":"x\\ne-2"},"."]},{"h2":"4. Typ rovnice podľa tvaru"},{"p":["• ",{"b":"Lineárna:"}," po úprave ",{"math":"ax+b=0,\\ a\\ne0"},"."]},{"p":["• ",{"b":"Kvadratická:"}," ",{"math":"ax^2+bx+c=0,\\ a\\ne0"},"."]},{"p":["• ",{"b":"Kubická:"}," ",{"math":"ax^3+bx^2+cx+d=0,\\ a\\ne0"},"."]},{"p":["• ",{"b":"Polynomiálna:"}," ",{"math":"P(x)=0"},"."]},{"p":["• ",{"b":"Racionálna:"}," neznáma sa nachádza v menovateli, napríklad ",{"math":"\\frac{x+1}{x-2}=3"}," s podmienkou ",{"math":"x\\ne2"},"."]},{"p":["• ",{"b":"Iracionálna:"}," neznáma je pod odmocninou, napríklad ",{"math":"\\sqrt{x+1}=x"},"."]},{"p":["• ",{"b":"Exponenciálna:"}," neznáma je v exponente, napríklad ",{"math":"2^x=8"},"."]},{"p":["• ",{"b":"Logaritmická:"}," obsahuje logaritmus neznámeho výrazu, napríklad ",{"math":"\\log(x-1)=2"}," s ",{"math":"x>1"},"."]},{"p":["• ",{"b":"Trigonometrická:"}," obsahuje napríklad ",{"math":"\\sin x,\\cos x,\\tan x"},"."]},{"p":["• ",{"b":"S absolútnou hodnotou:"}," napríklad ",{"math":"|2x-1|=5"},"; obyčajne sa rieši rozdelením na prípady."]},{"p":["• ",{"b":"Lineárna nerovnica:"}," napríklad ",{"math":"2x-3>5"},"; namiesto rovnosti obsahuje znak nerovnosti."]},{"p":["• ",{"b":"Kvadratická nerovnica:"}," napríklad ",{"math":"x^2-5x+6\\le0"},"."]},{"p":"Aký typ rovnice je toto?"},{"math":"x^2+3x=x(x+2)"},{"p":["Na prvý pohľad sa to javí ako kvadratická rovnica ale v skutočnosti sa jedná o ",{"b":"lineárnu rovnicu"},".\nNiekedy sa na jednoducho nedá určiť, aký typ rovnice máme, pretože jej skutočný tvar môže byť skrytý za úpravami"]},{"h2":"Úlohy na precvičenie"},{"p":["1. V rovnici ",{"math":"4(x-2)+\\frac{x+1}{x-3}=9"}," pomenujte ľavú stranu, pravú stranu, členy, čitateľa, menovateľa a podmienku."]},{"p":["2. Určte typ rovnice: ",{"math":"5x-7=0"},", ",{"math":"x^2+4x+1=0"},", ",{"math":"\\frac1{x-2}=3"},", ",{"math":"\\sqrt{x}=x-2"},"."]},{"p":["3. Rozhodnite, či je zápis ",{"math":"3x^2-5x+2"}," výraz, rovnica alebo nerovnica."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. Ľavý výraz je ",{"math":"4(x-2)+\\frac{x+1}{x-3}"},", pravý výraz je ",{"math":"9"},"; v zlomku je čitateľ ",{"math":"x+1"},", menovateľ ",{"math":"x-3"}," a podmienka ",{"math":"x\\ne3"},"."]},{"p":"2. Postupne: lineárna, kvadratická, racionálna, iracionálna rovnica."},{"p":"3. Je to výraz, pretože neobsahuje znak rovnosti ani nerovnosti."},{"p":["V rozvinutom výraze sú členy časti spojené sčítaním alebo odčítaním na najvyššej úrovni zápisu. Činitele sú časti spojené násobením. Pri kubickej rovnici ",{"math":"ax^3+bx^2+cx+d=0"}," musí platiť ",{"math":"a\\ne0"},"."]},{"p":"Typ rovnice určujeme podľa matematicky upraveného vzťahu, ale zároveň evidujeme obmedzenia pôvodného zápisu. Rovnica so zlomkami sa po úprave môže zmeniť na lineárnu, no zakázané hodnoty z pôvodných menovateľov zostávajú zakázané."},{"test":"# Krátky test: Základné matematické pojmy: od rovnice k činiteľu\n\n[ABCD]\nČo predstavuje celý zápis „výraz = výraz“?\n* Rovnicu\n- Jeden člen\n- Jeden činiteľ\n- Menovateľ\n\n[ABCD]\nAko sa nazývajú časti súčinu?\n* Činitele\n- Členy\n- Korene\n- Intervaly\n\n[ABCD]\nKtorá podmienka platí pre menovateľ?\n* Nesmie sa rovnať nule\n- Musí byť kladný\n- Musí byť celé číslo\n- Musí sa rovnať čitateľu\n\n[ABCD]\nAký tvar má kvadratická rovnica?\n* ax² + bx + c = 0, a ≠ 0\n- ax + b = 0\n- a/x = 0\n- ax³ + b = 0"},{"h2":"Zapamätaj si"},{"p":"• Rovnica: Celok v tvare výraz = výraz; riešenie musí spĺňať rovnosť aj všetky definičné podmienky."},{"p":"• Výraz: Časť rovnice bez hlavného znaku rovnosti. Výraz sa skladá z členov a členy môžu obsahovať činitele."},{"p":"• Zlomok: Má čitateľa a menovateľa; menovateľ nesmie byť nulový."}]},{"id":"uprava-vyrazov-zakladne-pravidla","title":"Úprava výrazov: členy, znamienka a zátvorky","blocks":[{"p":"Ktoré členy môžeme spojiť bez toho, aby sme zmenili hodnotu výrazu?"},{"h2":"Viète zaviedol písmená do všeobecnej algebry"},{"p":"François Viète v 16. storočí systematicky používal písmená nielen pre neznáme, ale aj pre známe parametre. Vďaka tomu bolo možné zapisovať všeobecné pravidlá namiesto riešenia každého číselného príkladu osobitne. Úprava výrazov sa stala prácou so štruktúrou, nie iba s konkrétnymi číslami."},{"p":"Predstav si túto situáciu ako krátke vyšetrovanie. Máš tvrdenie, ktoré môže byť pravdivé aj klamlivé, a potrebuješ dôkaz. Jedno nastavenie grafu nestačí, pretože môže ísť o náhodu. Zmeníš parameter, odmeriaš výsledok a potom zámerne vyhľadáš hraničný prípad. Interaktívna úloha ti pridelí bod iba vtedy, keď podmienku naozaj splníš. Tým sa z pozorovania stane overiteľný matematický argument. Ktoré členy môžeme spojiť bez toho, aby sme zmenili hodnotu výrazu? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"p":["Úprava výrazu znamená nahradiť ho ekvivalentným, zvyčajne jednoduchším výrazom. Základom sú ",{"b":"poradie operácií"},", správne odstránenie zátvoriek a spájanie podobných členov."]},{"h2":"Poradie operácií"},{"p":"1. zátvorky,"},{"p":"2. mocniny a odmocniny,"},{"p":"3. násobenie a delenie,"},{"p":"4. sčítanie a odčítanie."},{"p":["Podobné členy majú rovnakú premennú časť s rovnakými exponentmi: ",{"math":"3x^2-5x^2=-2x^2"},". Výrazy ",{"math":"x"}," a ",{"math":"x^2"}," podobné nie sú."]},{"h2":"Príklad 1: spájanie podobných členov"},{"math":"\\begin{aligned}2x^2+3x-5-3x^2-x+2&=(2x^2-3x^2)+(3x-x)+(-5+2)\\\\&=-x^2+2x-3.\\end{aligned}"},{"h2":"Príklad 2: viac premenných"},{"math":"\\begin{aligned}7n+3m+2+3n^2+4&=3n^2+7n+3m+(2+4)\\\\&=3n^2+7n+3m+6.\\end{aligned}"},{"p":["Členy ",{"math":"7n"}," a ",{"math":"3m"}," nemožno spojiť, pretože majú inú premennú časť."]},{"h2":"Príklad 3: vnorené zátvorky"},{"p":"Zápis interpretujeme s uzavretou vonkajšou zátvorkou:"},{"math":"\\begin{aligned}2a-[b-(5a+2b-c)+(2a+b-3c)]&=2a-[b-5a-2b+c+2a+b-3c]\\\\&=2a-[-3a-2c]\\\\&=5a+2c.\\end{aligned}"},{"p":["Ak je pred zátvorkou mínus, znamienko sa zmení pri ",{"b":"každom"}," člene: ",{"math":"-(u-v+w)=-u+v-w"},"."]},{"h2":"Príklad 4: dlhší výraz"},{"math":"\\begin{aligned}&-R^2S+15RS^2-\\left(-5R^2S^2-R^2S-8RS+18RS^2\\right)\\\\&=-R^2S+15RS^2+5R^2S^2+R^2S+8RS-18RS^2\\\\&=5R^2S^2-3RS^2+8RS\\\\&=RS(5RS-3S+8).\\end{aligned}"},{"h2":"Bezpečný algoritmus pre vnorené zátvorky"},{"p":"1. Začnite najvnútornejšou zátvorkou."},{"p":"2. Pred odstránením zátvorky si označte znamienko alebo činiteľ pred ňou."},{"p":["3. Ak je pred zátvorkou mínus, zmeňte znamienko ",{"b":"každého"}," člena."]},{"p":"4. Podobné členy spájajte až po správnom odstránení zátvoriek."},{"p":"5. Výsledok zoraďte zostupne podľa stupňa; pri viacerých premenných zvoľte jedno konzistentné poradie."},{"math":"3x-\\left[2-\\left(x-3(2x-1)\\right)\\right]+2(1-x)"},{"math":"\\begin{aligned}\n3(2x-1)&=6x-3,\\\\\nx-(6x-3)&=-5x+3,\\\\\n2-(-5x+3)&=5x-1,\\\\\n3x-(5x-1)+2(1-x)&=3x-5x+1+2-2x\\\\\n&=-4x+3.\n\\end{aligned}"},{"h3":"Mínus a mocnina nie sú to isté"},{"math":"\\qquad (-x)^2=x^2"},{"h3":"Štandardný tvar výrazu"},{"p":"Pri jednej premennej zoraďujeme členy od najvyššieho exponentu po konštantu:"},{"math":"7-2x+x^4+3x^2=x^4+3x^2-2x+7"},{"p":"Toto zoradenie nemení hodnotu výrazu; iba zvyšuje prehľadnosť a uľahčuje určenie stupňa, vedúceho člena a porovnanie dvoch polynómov."},{"h2":"Úlohy na precvičenie"},{"p":["1. Upravte ",{"math":"8x^2-3x+4-5x^2+7x-9"},"."]},{"p":["2. Upravte ",{"math":"4a-[2a-(3a-b)+2b]"},"."]},{"p":["3. Vyberte spoločný činiteľ z ",{"math":"12x^3y-8x^2y^2"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. ",{"math":"3x^2+4x-5"},"."]},{"p":["2. ",{"math":"4a-[2a-3a+b+2b]=4a-[-a+3b]=5a-3b"},"."]},{"p":["3. ",{"math":"4x^2y(3x-2y)"},"."]},{"p":["Pred zátvorkou platí ",{"math":"-(a-b)=-a+b"},". Napríklad ",{"math":"-(2x-3)=-2x+3"},", nie ",{"math":"-2x-3"},". Pri dvoch záporných zátvorkách postupuj po jednej a až potom spájaj podobné členy."]},{"p":"Dva výrazy sú ekvivalentné na svojom spoločnom definičnom obore. Úprava nesmie potichu pridať hodnotu, pri ktorej pôvodný výraz neexistoval."},{"test":"# Krátky test: Úprava výrazov: členy, znamienka a zátvorky\n\n[ABCD]\nKtoré členy sú podobné?\n* 3x² a −5x²\n- 3x² a 3x\n- x a y\n- x² a xy\n\n[ABCD]\nČo sa stane so znamienkami po odstránení mínusu pred zátvorkou?\n* Zmenia sa pri všetkých členoch\n- Nezmenia sa\n- Zmení sa iba prvé\n- Zmenia sa iba pri konštantách\n\n[ABCD]\nAký je výsledok 2x + 5x?\n* 7x\n- 7x²\n- 10x\n- 7\n\n[ABCD]\nMožno spojiť 4a a 3b?\n* Nie, majú inú premennú časť\n- Áno, výsledok je 7ab\n- Áno, výsledok je 7a\n- Áno, výsledok je 12ab"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."],"role":"instruction"},{"h2":"Zapamätaj si"},{"p":"• Podobné členy: Majú rovnaké premenné aj exponenty; sčítavajú sa iba ich koeficienty."},{"p":"• Mínus pred zátvorkou: Zmení znamienko každého člena v zátvorke."},{"p":"• Kontrola: Po úprave možno dosadiť niekoľko hodnôt a porovnať pôvodný a výsledný výraz."}]},{"id":"narocne-upravy-suciny-a-zatvorky","title":"Náročné úpravy: súčiny a roznásobovanie","blocks":[{"p":"Ako roznásobiť viac zátvoriek bez straty znamienka alebo člena?"},{"h2":"Algoritmy putovali z Indie cez arabský svet do Európy"},{"p":"Mnohé písomné algoritmy násobenia a práce s číslami sa do stredovekej Európy dostali cez arabské matematické texty. Fibonacci ich popularizoval v knihe Liber Abaci z roku 1202. Dnešné roznásobovanie zátvoriek je symbolickou verziou tej istej distributívnej myšlienky."},{"p":"Historický krok bol dôležitý najmä preto, že premenil obraz na postup, ktorý sa dal zopakovať. Aj ty začneš bez hotového pravidla. Skús si vopred predstaviť výsledok, potom upravuj iba tie veličiny, ktoré sú v modeli voľné, a sleduj pomenované čísla alebo polohy. Úloha je nastavená tak, aby nestačilo trafiť jednu očividnú hodnotu; musíš skombinovať viac podmienok a skontrolovať, či výsledný obraz dáva zmysel. Ako roznásobiť viac zátvoriek bez straty znamienka alebo člena? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"graph":{"title":"Súčin dvoch lineárnych činiteľov","bounds":[-7,7,-10,12],"commands":["p=-2","q=3","f(x)=(x-p)*(x-q)","P=(p,0)","Q=(q,0)","sumRoots=p+q","productRoots=p*q"],"controls":[["p",-5,5,0.5,-2],["q",-5,5,0.5,3]],"tasks":[{"text":"Nastav korene tak, aby ich súčet bol 1 a súčin −6.","condition":"sumRoots>0.99 && sumRoots<1.01 && productRoots>-6.01 && productRoots<-5.99"},{"text":"Vytvor dvojnásobný koreň v bode x=2.","condition":"p>1.99 && p<2.01 && q>1.99 && q<2.01"}],"colors":{"f":[29,78,216],"P":[220,38,38],"Q":[22,163,74]},"toolbar":true}},{"p":[{"b":"Obor a podmienky:"}," Ak pri konkrétnom príklade nie je napísané inak, základný obor je ",{"math":"U=\\mathbb R"},". Pri zlomkoch, odmocninách a ďalších obmedzeniach sa navyše zapisuje podmienka ",{"math":"P"},"; riešenie musí patriť do oboru aj spĺňať všetky podmienky."]},{"p":["Pri násobení používame distributívny zákon ",{"math":"k(a+b)=ka+kb"},". Pri súčine viacerých jednočlenov násobíme koeficienty a exponenty rovnakých premenných sčítame."]},{"h2":"Príklad 5: súčin jednočlenov"},{"math":"\\begin{aligned}(-2ax)(-3ax)(-xY^2)&=(-2)(-3)(-1)\\,a^2x^3Y^2\\\\&=-6a^2x^3Y^2.\\end{aligned}"},{"h2":"Príklad 6: jednočlen krát dvojčlen"},{"math":"4xY(2x+3Y)=8x^2Y+12xY^2."},{"h2":"Príklad 7: dvojčlen krát dvojčlen"},{"math":"\\begin{aligned}(2xY+Y^2)(x^2-2xY)&=2x^3Y-4x^2Y^2+x^2Y^2-2xY^3\\\\&=2x^3Y-3x^2Y^2-2xY^3.\\end{aligned}"},{"h2":"Príklad 8: trojčlen krát trojčlen"},{"math":"(x^2+x+1)(x^2+x+2)=x^4+2x^3+4x^2+3x+2."},{"p":["Rýchla kontrola posledného príkladu: položme ",{"math":"t=x^2+x"},". Potom ",{"math":"(t+1)(t+2)=t^2+3t+2"},"; po spätnom dosadení dostaneme ten istý polynóm."]},{"h2":"Užitočné vzorce"},{"math":"\\begin{aligned}(a+b)^2&=a^2+2ab+b^2,\\\\(a-b)^2&=a^2-2ab+b^2,\\\\a^2-b^2&=(a-b)(a+b),\\\\a^3-b^3&=(a-b)(a^2+ab+b^2).\\end{aligned}"},{"h2":"Rozšírenie: násobenie troch a viacerých zátvoriek"},{"p":["Pri troch zátvorkách násobíme ",{"b":"postupne po dvojiciach"},". Násobenie je asociatívne, preto môžeme zvoliť výhodné zoskupenie:"]},{"math":"A\\cdot B\\cdot C=(A\\cdot B)\\cdot C=A\\cdot(B\\cdot C)"},{"p":[{"b":"Zanikne prvá zátvorka?"}," Po roznásobení prvých dvoch zátvoriek ich súčin nahradíme jedným polynómom. Keď ho však ešte násobíme treťou zátvorkou, nový polynóm musí zostať chápaný ako jeden celok. Preto je bezpečné zátvorku ponechať:"]},{"math":"(x-1)(x+2)(x-3)=\\underbrace{(x^2+x-2)}_{\\text{súčin prvých dvoch zátvoriek}}(x-3)"},{"p":["Samotný zápis ",{"math":"x^2+x-2"}," už vnútorné zátvorky nepotrebuje. Vonkajšia zátvorka však ukazuje, že ",{"b":"každý jeho člen"}," musíme vynásobiť každým členom tretej zátvorky."]},{"math":"\\begin{aligned}\n(x^2+x-2)(x-3)\n&=x^2\\cdot x+x^2(-3)+x\\cdot x+x(-3)-2x+6\\\\\n&=x^3-3x^2+x^2-3x-2x+6\\\\\n&=x^3-2x^2-5x+6.\n\\end{aligned}"},{"p":[{"b":"Podmienky:"}," ide o polynomiálny výraz, preto ",{"math":"U=\\mathbb R"}," a nevzniká žiadna dodatočná definičná podmienka."]},{"h3":"Výber výhodného poradia"},{"p":"Niekedy je rýchlejšie najskôr vynásobiť zátvorky, ktoré vytvoria známy vzorec:"},{"math":"\\begin{aligned}\n(x+1)(x-1)(x^2+1)\n&=(x^2-1)(x^2+1)\\\\\n&=x^4-1.\n\\end{aligned}"},{"p":"Tu sme dvakrát použili rozdiel štvorcov. Výsledok je rovnaký bez ohľadu na poradie, ale vhodné zoskupenie znižuje počet medzikrokov."},{"h3":"Zložitejší príklad s tromi rôznymi zátvorkami"},{"math":"\\begin{aligned}\n(2x-3)(x+4)(x^2-x+2)\n&=(2x^2+5x-12)(x^2-x+2)\\\\\n&=2x^4-2x^3+4x^2+5x^3-5x^2+10x\\\\\n&\\quad-12x^2+12x-24\\\\\n&=2x^4+3x^3-13x^2+22x-24.\n\\end{aligned}"},{"p":["V druhom kroku sme ",{"b":"každý z troch členov"}," polynómu ",{"math":"2x^2+5x-12"}," vynásobili ",{"b":"každým z troch členov"}," polynómu ",{"math":"x^2-x+2"},". Pomáha zapisovať medzivýsledky do samostatných riadkov."]},{"h3":"Všeobecný počet čiastkových súčinov"},{"p":["Ak majú tri zátvorky po dva členy, vznikne pred spojením podobných členov ",{"math":"2\\cdot2\\cdot2=8"}," čiastkových súčinov:"]},{"math":"\\begin{aligned}\n(a+b)(c+d)(e+f)\n={}&ace+acf+ade+adf\\\\\n&+bce+bcf+bde+bdf.\n\\end{aligned}"},{"h3":"Najčastejšie chyby"},{"p":["• ",{"b":"Zabudnutý člen:"}," tretia zátvorka musí násobiť celý predchádzajúci výsledok, nie iba jeho posledný člen."]},{"p":["• ",{"b":"Predčasné odstránenie zoskupenia:"}," zápis ",{"math":"(x^2+x-2)(x-3)"}," nemožno zmeniť na ",{"math":"x^2+x-2x-3"},"."]},{"p":["• ",{"b":"Nesprávne znamienka:"}," pri násobení záporného člena používame pravidlá znamienok pri každom čiastkovom súčine."]},{"p":["• ",{"b":"Nesprávne spájanie:"}," spojiť možno iba podobné členy, napríklad ",{"math":"3x^2-5x^2=-2x^2"},", nie ",{"math":"3x^2-5x"},"."]},{"p":["• ",{"b":"Kontrola stupňa:"}," súčin stupňov ",{"math":"1,1,2"}," má mať stupeň ",{"math":"1+1+2=4"},", ak sa vedúce členy nevynulujú."]},{"h3":"Rozšírené cvičenia"},{"p":["1. Roznásobte ",{"math":"(x-2)(x+1)(x+3)"},"."]},{"p":["2. Roznásobte ",{"math":"(2x+1)(x-2)(x^2+3)"},"."]},{"p":["3. Využite vzorce: ",{"math":"(a-b)(a+b)(a^2+b^2)"},"."]},{"p":["4. Nájdite chybu v úprave ",{"math":"(x+1)(x+2)(x+3)=(x^2+3x+2)x+3"},"."]},{"p":"Zobraziť výsledky rozšírených cvičení"},{"p":["1. ",{"math":"x^3+2x^2-5x-6"},"."]},{"p":["2. ",{"math":"2x^4-3x^3+4x^2-9x-6"},"."]},{"p":["3. ",{"math":"a^4-b^4"},"."]},{"p":["4. Po vynásobení prvých dvoch zátvoriek musí tretia zátvorka násobiť ",{"i":"celý"}," výsledok: ",{"math":"(x^2+3x+2)(x+3)"},", nie iba člen ",{"math":"x"},"."]},{"h2":"Úlohy na precvičenie"},{"p":["1. Vynásobte ",{"math":"(-3a^2b)(4ab^3)"},"."]},{"p":["2. Roznásobte ",{"math":"5x(2x^2-3x+4)"},"."]},{"p":["3. Roznásobte ",{"math":"(x-4)(2x+3)"},"."]},{"p":["4. Použite vzorec na ",{"math":"(3x-2)^2"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. ",{"math":"-12a^3b^4"},"."]},{"p":["2. ",{"math":"10x^3-15x^2+20x"},"."]},{"p":["3. ",{"math":"2x^2-5x-12"},"."]},{"p":["4. ",{"math":"9x^2-12x+4"},"."]},{"p":["Pri súčine polynómov stupňov ",{"math":"1"},", ",{"math":"1"}," a ",{"math":"2"}," očakávame najviac stupeň ",{"math":"4"},", ak sa vedúce členy nevyrušia. Po roznásobení preto skontroluj najvyšší stupeň."]},{"p":["Druhá kontrola je dosadenie jednoduchej hodnoty, napríklad ",{"math":"x=1"},", do pôvodného aj upraveného výrazu. Jedna zhodná hodnota nie je dôkaz identity, ale rýchlo odhalí množstvo chýb v znamienkach."]},{"test":"# Krátky test: Náročné úpravy: súčiny a roznásobovanie\n\n[ABCD]\nAký je výsledok x³ · x⁴?\n* x⁷\n- x¹²\n- 2x⁷\n- x\n\n[ABCD]\nČomu sa rovná (a−b)²?\n* a² − 2ab + b²\n- a² − b²\n- a² + 2ab + b²\n- a² − 2b²\n\n[ABCD]\nPri násobení dvoch dvojčlenov treba:\n* Vynásobiť každý člen prvého každým členom druhého\n- Násobiť iba prvé členy\n- Sčítať exponenty všetkých členov\n- Odstrániť stredné členy\n\n[ABCD]\nAký stupeň má súčin polynómu 2. a 3. stupňa?\n* 5\n- 6\n- 3\n- 2"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."],"role":"instruction"},{"h2":"Zapamätaj si"},{"p":"• Distributívny zákon: Každý člen jednej zátvorky násobíme každým členom druhej."},{"p":"• Mocniny: Pri násobení rovnakých základov exponenty sčítame."},{"p":"• Kontrola stupňa: Súčin polynómov stupňa m a n má pri nenulových vedúcich koeficientoch stupeň m+n."}]},{"id":"lomene-vyrazy-mocniny-a-odmocniny","title":"Lomené výrazy, mocniny a odmocniny","blocks":[{"p":"Ktoré hodnoty musíme vylúčiť ešte pred úpravou zlomku alebo odmocniny?"},{"h2":"Chuquet písal záporné exponenty skôr, než boli bežné"},{"p":"Nicolas Chuquet v rukopise z roku 1484 používal záporné aj nulové exponenty v čase, keď takýto zápis nebol štandardný. Jeho práca zostala dlho nevydaná, no ukazuje, že rozširovanie pravidiel mocnín bolo postupným historickým procesom. Každé rozšírenie vyžadovalo pozorne určiť, pre ktoré hodnoty pravidlá platia."},{"p":"Za touto témou je vždy rovnaká vedecká otázka: čo možno tvrdiť na základe merania a čo je iba dojem z obrázka? Odpoveď získame porovnaním viacerých stavov, nie zapamätaním definície. V nasledujúcom modeli preto dostaneš cieľ vyjadrený číslom, polohou alebo vzťahom. Posuvníky a voľné body sú tvoje nástroje; bod za úlohu získaš až po splnení podmienky zapísanej priamo v dátach grafu. Ktoré hodnoty musíme vylúčiť ešte pred úpravou zlomku alebo odmocniny? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"p":[{"b":"Najprv si tipni:"},"Nájdi kladné x, pri ktorom sa hodnoty ",{"math":"x^{2}"}," a 1/",{"math":"x^{2}"}," rovnajú. Zapíš si odhad skôr, než pohneš prvým ovládačom."],"role":"instruction"},{"graph":{"title":"Mocniny a záporný exponent","bounds":[-5,5,-1,10],"commands":["f(x)=x^2","g(x)=1/x^2","x0=Slider(0.2,3,0.05,1,150,false,true,false,false)","SetValue(x0,2)","A=(x0,f(x0))","B=(x0,g(x0))","diff=abs(f(x0)-g(x0))","fval=f(x0)","gval=g(x0)","fval=f(x0)","gval=g(x0)"],"tasks":[{"text":"Nájdi kladné x, pri ktorom sa hodnoty x² a 1/x² rovnajú.","condition":"diff<0.01 && x0>0"},{"text":"Nastav x tak, aby x² bolo približne šestnásťkrát väčšie než 1/x².","condition":"fval>15.5*gval && fval<16.5*gval"}],"colors":{"f":[29,78,216],"g":[220,38,38]},"toolbar":true}},{"p":[{"b":"Obor a podmienky:"}," Ak pri konkrétnom príklade nie je napísané inak, základný obor je ",{"math":"U=\\mathbb R"},". Pri zlomkoch, odmocninách a ďalších obmedzeniach sa navyše zapisuje podmienka ",{"math":"P"},"; riešenie musí patriť do oboru aj spĺňať všetky podmienky."]},{"p":["Pri lomených výrazoch sa kráti iba ",{"b":"spoločný činiteľ"}," čitateľa a menovateľa. Pôvodné definičné podmienky zostávajú platné aj po skrátení."]},{"h2":"Príklad 9"},{"math":"\\frac{-2xYz^2}{10x^2z}=-\\frac{Yz}{5x},\\qquad x\\ne0,\\ z\\ne0."},{"h2":"Príklad 10"},{"math":"\\begin{aligned}\\frac{-8x^6y^4z^7}{(2x^3)(4ub^4z^7)}\n&=\\frac{-8x^6y^4z^7}{8ux^3b^4z^7}\\\\\n&=-\\frac{x^3y^4}{ub^4}.\n\\end{aligned}"},{"p":["Podmienky pôvodného výrazu sú ",{"math":"x\\ne0,\\ u\\ne0,\\ b\\ne0,\\ z\\ne0"},"."]},{"h2":"Príklad 11: mocnina zlomku"},{"math":"\\begin{aligned}\\frac{(-2x^2Yz)^2}{\\left(\\frac{x^2}{y^2}\\right)^2}\n&=\\frac{4x^4Y^2z^2}{x^4/y^4}\\\\\n&=4x^4Y^2z^2\\cdot\\frac{y^4}{x^4}\\\\\n&=4y^4Y^2z^2,\n\\end{aligned}"},{"p":["pričom ",{"math":"x\\ne0"}," a ",{"math":"y\\ne0"},". Veľké ",{"math":"Y"}," a malé ",{"math":"y"}," označujú rozdielne premenné."]},{"h2":"Príklad 12: odmocniny ako mocniny"},{"math":"\\begin{aligned}\\frac{\\sqrt{x}\\sqrt[4]{y}}{\\sqrt{x^3}\\sqrt[5]{y}}\n&=x^{1/2-3/2}y^{1/4-1/5}\\\\\n&=x^{-1}y^{1/20}\n=\\frac{\\sqrt[20]{y}}{x}.\n\\end{aligned}"},{"p":["V reálnych číslach je pre pôvodný výraz potrebné ",{"math":"x>0,\\ y>0"},"."]},{"h2":"Príklad 13: vnorené odmocniny a záporné exponenty"},{"math":"\\begin{aligned}\n\\frac{\\sqrt{a^9\\sqrt{b^{-3}}}}{\\sqrt[5]{b^3\\sqrt{a^3}}}\n&=\\frac{a^{9/2}b^{-3/4}}{b^{3/5}a^{3/10}}\\\\\n&=a^{9/2-3/10}b^{-3/4-3/5}\\\\\n&=\\frac{a^{21/5}}{b^{27/20}},\n\\end{aligned}"},{"p":["Pre tento reálny zápis a nenulový menovateľ používame ",{"math":"a>0,\\ b>0"},"."]},{"h2":"Pravidlá mocnín"},{"math":"a^m a^n=a^{m+n},\\qquad \\frac{a^m}{a^n}=a^{m-n},\\qquad (a^m)^n=a^{mn},\\qquad a^{-n}=\\frac1{a^n}."},{"h2":"Podmienka zostáva platná aj po skrátení"},{"p":"Pri výraze"},{"math":"\\frac{x^2-4}{x-2}"},{"p":["najprv zapisujeme ",{"math":"U=\\mathbb R,\\ P:x\\ne2"},". Až potom rozložíme čitateľa:"]},{"math":"\\frac{(x-2)(x+2)}{x-2}=x+2,\\qquad x\\ne2"},{"p":["Výrazy sú rovnaké na pôvodnom definičnom obore, ale funkcia ",{"math":"y=x+2"}," je definovaná aj v bode ",{"math":"x=2"},". Pôvodný lomený výraz tam definovaný nie je. Na grafe preto vzniká „diera“ v bode ",{"math":"[2,4]"},"."]},{"h3":"Krátime činitele, nie členy"},{"math":"\\frac{x+2}{x}\\ne2,\\qquad \\frac{x+2}{x}=1+\\frac2x,\\quad x\\ne0"},{"p":["Člen ",{"math":"x"}," nemožno „vyškrtnúť“ zo súčtu ",{"math":"x+2"},". Krátenie je možné až po rozklade celého čitateľa a menovateľa na súčin."]},{"h3":"Spoločný menovateľ pri viacerých členoch"},{"math":"\\frac2{x-1}-\\frac3{x+2}=\\frac{2(x+2)-3(x-1)}{(x-1)(x+2)},\\qquad x\\ne1,-2"},{"p":["Znamienko mínus pred druhým zlomkom pôsobí na celý čitateľ ",{"math":"3(x-1)"},". Po roznásobení dostaneme čitateľ ",{"math":"2x+4-3x+3=7-x"},"."]},{"h3":"Podmienky pri zlomkových exponentoch"},{"p":["Pravidlá sčítania exponentov treba v reálnych číslach používať spolu s definičným oborom. Napríklad ",{"math":"\\sqrt{x^2}=|x|"},", nie všeobecne ",{"math":"x"},". Pri zápise ",{"math":"x^{1/2}"}," pracujeme pre reálne hodnoty s ",{"math":"x\\ge0"},"; ak je taký výraz v menovateli, potrebujeme ",{"math":"x>0"},"."]},{"h2":"Úlohy na precvičenie"},{"p":["1. Upravte ",{"math":"\\frac{18x^5y^3}{6x^2y}"}," a uveďte podmienky."]},{"p":["2. Upravte ",{"math":"\\frac{x^{3/2}}{x^{1/2}}"},"."]},{"p":["3. Zapíšte bez záporného exponentu ",{"math":"a^{-3}b^2"},"."]},{"p":["4. Upravte ",{"math":"\\sqrt[3]{x^6}"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. ",{"math":"3x^3y^2"},", pričom v pôvodnom výraze ",{"math":"x\\ne0,\\ y\\ne0"},"."]},{"p":["2. ",{"math":"x"},"; pri pôvodnom reálnom výraze s odmocninami je ",{"math":"x>0"},"."]},{"p":["3. ",{"math":"\\frac{b^2}{a^3}"},", ",{"math":"a\\ne0"},"."]},{"p":["4. Pre reálne ",{"math":"x"}," platí ",{"math":"\\sqrt[3]{x^6}=x^2"},"."]},{"p":["Krátime iba spoločné nenulové ",{"b":"činitele"},". Z výrazu ",{"math":"\\frac{x(x-2)}{x}"}," možno pre ",{"math":"x\\ne0"}," dostať ",{"math":"x-2"},", ale pôvodná podmienka ",{"math":"x\\ne0"}," zostáva."]},{"p":["V reálnych číslach platí ",{"math":"\\sqrt{x^2}=|x|"},". Pri zlomkových exponentoch treba sledovať paritu menovateľa: napríklad ",{"math":"x^{1/2}"}," vyžaduje ",{"math":"x\\ge0"},", kým reálna tretia odmocnina existuje aj pre záporné ",{"math":"x"},"."]},{"test":"# Krátky test: Lomené výrazy, mocniny a odmocniny\n\n[ABCD]\nČo možno v zlomku krátiť?\n* Spoločné nenulové činitele\n- Ľubovoľné členy\n- Iba exponenty\n- Súčty v zátvorkách\n\n[ABCD]\nČomu sa rovná a⁻³?\n* 1/a³\n- −a³\n- a/3\n- 3a\n\n[ABCD]\nČomu sa rovná x⁵/x²?\n* x³\n- x⁷\n- x²⋅⁵\n- 1/x³\n\n[ABCD]\nČo platí o pôvodných definičných podmienkach po skrátení?\n* Zostávajú platné\n- Vždy zaniknú\n- Nahradia sa podmienkou x>0\n- Platia iba pri polynómoch"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."],"role":"instruction"},{"h2":"Zapamätaj si"},{"p":"• Krátenie: Krátime činitele, nie členy spojené sčítaním alebo odčítaním."},{"p":"• Definičné podmienky: Určujú sa z pôvodného výrazu a po skrátení sa nestrácajú."},{"p":["• Zlomkové exponenty: Platí napríklad x^(",{"math":"1/n)=n-t"},"á odmocnina z x; pri párnom n treba rešpektovať reálny definičný obor."]}]},{"id":"mnoziny-podmienky-a-bezpecne-upravy-rovnic","title":"Množiny, podmienky a bezpečné úpravy rovníc","blocks":[{"p":"Ktoré úpravy zachovajú všetky riešenia a ktoré môžu vytvoriť cudzie?"},{"h2":"Prečo starí algebraici odmietali niektoré riešenia"},{"p":"Al-Chvárizmí pracoval najmä s kladnými veličinami, pretože rovnice interpretoval geometricky a prakticky. Záporné či nemožné hodnoty preto neboli automaticky prijateľnými riešeniami. Moderné definičné podmienky pokračujú v tej istej disciplíne: výsledok musí patriť do sveta, v ktorom bol problém položený."},{"p":"Na stole by vtedy neležal hotový vzorec, iba údaje a otázka, ktorú bolo treba rozhodnúť. Užitočný nápad vzniká vtedy, keď sa neurčité slová nahradia meraním: zmeníš jednu hodnotu, sleduješ následok a porovnáš ho s ďalším prípadom. Rovnaký postup použiješ v interaktívnom modeli. Cieľ nebude splnený približným dojmom, ale až konkrétnou hodnotou alebo vzťahom medzi objektmi. Ktoré úpravy zachovajú všetky riešenia a ktoré môžu vytvoriť cudzie? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"p":[{"b":"Najprv si tipni:"},"Nastav priamku a vodorovnú čiaru tak, aby sa pretli pri ",{"math":"x\\approx 2"}," a ",{"math":"y\\approx 1"},". Zapíš si odhad skôr, než pohneš prvým ovládačom."],"role":"instruction"},{"graph":{"title":"Počet riešení ako počet priesečníkov","bounds":[-8,8,-8,8],"commands":["a=1","b=-2","c=0","f(x)=a*x+b","g(x)=c","xCross=If(a!=0,(c-b)/a)","lineGap=abs(b-c)"],"controls":[["a",-3,3,0.25,1],["b",-5,5,0.25,-2],["c",-5,5,0.25,0]],"tasks":[{"text":"Nastav priamku a vodorovnú čiaru tak, aby sa pretli pri x≈2 a y≈1.","condition":"xCross>1.95 && xCross<2.05 && c>0.95 && c<1.05"},{"text":"Vytvor dve rôzne rovnobežné vodorovné priamky bez priesečníka.","condition":"a>-0.02 && a<0.02 && lineGap>0.2"}],"colors":{"f":[29,78,216],"g":[220,38,38]},"toolbar":true}},{"p":["Táto lekcia vysvetľuje pravidlá, ktoré treba použiť ",{"b":"pred riešením každej rovnice"},". Najprv určíme číselný obor a definičné podmienky, potom upravujeme obe strany ako celé výrazy a nakoniec skontrolujeme, či úpravy zachovali všetky riešenia."]},{"h2":"1. Číselné množiny a obor riešenia"},{"p":[{"b":"Obor riešenia"}," alebo základná množina sa označuje napríklad ",{"math":"U=\\mathbb R"},". Určuje, medzi akými číslami smieme hľadať riešenia."]},{"p":["• ",{"math":"\\mathbb N=\\{1,2,3,\\ldots\\}"}," – prirodzené čísla. Ak chceme zahrnúť nulu, v tomto kurze píšeme ",{"math":"\\mathbb N_0=\\{0,1,2,\\ldots\\}"},"."]},{"p":["• ",{"math":"\\mathbb Z=\\{\\ldots,-2,-1,0,1,2,\\ldots\\}"}," – celé čísla."]},{"p":["• ",{"math":"\\mathbb Q=\\left\\{\\frac pq;\\ p,q\\in\\mathbb Z,\\ q\\ne0\\right\\}"}," – racionálne čísla; majú konečný alebo periodický desatinný rozvoj."]},{"p":["• ",{"math":"\\mathbb R"}," – reálne čísla; zahŕňajú racionálne aj iracionálne čísla, napríklad ",{"math":"\\sqrt2,\\pi"},"."]},{"p":["• ",{"math":"\\mathbb C=\\{a+bi;\\ a,b\\in\\mathbb R,\\ i^2=-1\\}"}," – komplexné čísla."]},{"math":"\\mathbb N\\subset\\mathbb Z\\subset\\mathbb Q\\subset\\mathbb R\\subset\\mathbb C"},{"p":"Tá istá rovnica môže mať v rôznych oboroch iný počet riešení. Napríklad:"},{"math":"x^2=2"},{"p":["• v ",{"math":"\\mathbb N"}," a ",{"math":"\\mathbb Q"}," nemá riešenie,"]},{"p":["• v ",{"math":"\\mathbb R"}," má dve riešenia ",{"math":"x=\\pm\\sqrt2"},","]},{"p":["• v ",{"math":"\\mathbb C"}," má tie isté dve reálne riešenia, ktoré sú zároveň komplexnými číslami."]},{"h2":"2. Definičné podmienky"},{"p":["Podmienky označujeme písmenom ",{"math":"P"},". Zapisujeme ich ",{"b":"pred úpravou"},", pretože neskôr sa môže zakázaný menovateľ skrátiť alebo odmocnina zmiznúť. To však pôvodnú podmienku neruší."]},{"p":"Časť rovnice — Nutná podmienka — Príklad"},{"p":["menovateľ — nesmie byť nulový — ",{"math":"\\frac1{x-3}"}," ⇒ ",{"math":"P:x\\ne3"}]},{"p":["párna odmocnina — výraz pod odmocninou je nezáporný — ",{"math":"\\sqrt{2x-1}"}," ⇒ ",{"math":"P:x\\ge\\frac12"}]},{"p":["logaritmus — argument je kladný — ",{"math":"\\log(x+4)"}," ⇒ ",{"math":"P:x>-4"}]},{"p":["delenie pri úprave — deliteľ musí byť nenulový — delenie výrazom ",{"math":"x-2"}," vyžaduje ",{"math":"x\\ne2"}]},{"p":[{"b":"Príklad s viacerými podmienkami:"}]},{"math":"\\frac{\\sqrt{x-1}}{(x-3)(x+2)}=2"},{"p":[{"math":"U=\\mathbb R"},", ",{"math":"P:x\\ge1,\\ x\\ne3"},". Podmienka ",{"math":"x\\ne-2"}," je už automaticky splnená z ",{"math":"x\\ge1"},", no môžeme ju pri odvodzovaní uviesť."]},{"h2":"3. Ekvivalentné úpravy – riešenia sa nemenia"},{"p":["Znak ",{"math":"\\Longleftrightarrow"}," znamená, že dva zápisy majú za daných podmienok rovnakú množinu riešení. Bezpečné sú najmä tieto operácie:"]},{"p":"1. pripočítať alebo odčítať ten istý definovaný výraz na oboch stranách,"},{"p":["2. vynásobiť alebo vydeliť obe strany tým istým ",{"b":"známym nenulovým číslom"},","]},{"p":"3. roznásobiť zátvorky, vytknúť spoločný činiteľ alebo spojiť podobné členy,"},{"p":"4. zameniť strany rovnice."},{"math":"L(x)=P(x)\\Longleftrightarrow L(x)+A(x)=P(x)+A(x)"},{"math":"L(x)=P(x)\\Longleftrightarrow cL(x)=cP(x),\\qquad c\\ne0"},{"p":"Výraz „prenesieme člen na druhú stranu a zmeníme znamienko“ je iba skratka. V skutočnosti k obom stranám pripočítame opačný výraz:"},{"math":"3x+7=19\\Longleftrightarrow 3x+7-7=19-7\\Longleftrightarrow3x=12"},{"h2":"4. Operácia sa musí vykonať na celej strane"},{"p":["Ľavá aj pravá strana sú celé výrazy. Ak rovnicu násobíme číslom ",{"math":"12"},", používame zátvorky:"]},{"math":"\\frac{2x-1}{3}-\\frac{x+2}{4}=5-\\frac{x-1}{6}"},{"p":[{"b":"Obor a podmienky:"}," ",{"math":"U=\\mathbb R"},", menovatele sú nenulové konštanty, takže bez dodatočnej podmienky."]},{"math":"\\begin{aligned}\n12\\left(\\frac{2x-1}{3}-\\frac{x+2}{4}\\right)\n&=12\\left(5-\\frac{x-1}{6}\\right)\\\\\n4(2x-1)-3(x+2)&=60-2(x-1)\\\\\n8x-4-3x-6&=60-2x+2\\\\\n5x-10&=62-2x\\\\\n7x&=72\\\\\nx&=\\frac{72}{7}.\n\\end{aligned}"},{"p":[{"b":"Nesprávne:"}," vynásobiť číslom ",{"math":"12"}," iba prvý zlomok. Operácia sa musí dotknúť ",{"i":"každého člena na oboch stranách"},"."]},{"h2":"5. Úpravy, ktoré môžu pridať alebo odstrániť riešenia"},{"p":["Pri týchto krokoch používame skôr jednosmernú šípku ",{"math":"\\Longrightarrow"},", vytvárame ",{"b":"kandidátov"}," a na konci robíme skúšku v pôvodnej rovnici."]},{"h3":"Násobenie výrazom závislým od neznámej môže pridať riešenie"},{"math":"x=1\\Longrightarrow x^2=x"},{"p":["Nová rovnica má riešenia ",{"math":"x\\in\\{0,1\\}"},", ale pôvodná iba ",{"math":"x=1"},". Aby bolo násobenie ekvivalentné, museli by sme pridať podmienku ",{"math":"x\\ne0"},"."]},{"h3":"Delenie výrazom závislým od neznámej môže odstrániť riešenie"},{"math":"x(x-2)=0"},{"p":["Ak bez rozmyslu vydelíme rovnicu výrazom ",{"math":"x"},", dostaneme iba ",{"math":"x=2"}," a stratíme riešenie ",{"math":"x=0"},". Správne použijeme pravidlo nulového súčinu: ",{"math":"x=0\\ \\lor\\ x-2=0"},"."]},{"h3":"Umocnenie môže vytvoriť nepravé riešenie"},{"math":"x=-2\\Longrightarrow x^2=4"},{"p":["Rovnica ",{"math":"x^2=4"}," má aj ",{"math":"x=2"},", ktoré nepatrí pôvodnej rovnici. Preto po umocnení kontrolujeme všetkých kandidátov."]},{"h3":"Odmocnenie bez absolútnej hodnoty môže riešenie stratiť"},{"math":"x^2=9\\Longleftrightarrow |x|=3\\Longleftrightarrow x=\\pm3"},{"p":["Nesprávny krok ",{"math":"\\sqrt{x^2}=x"}," zabudne, že všeobecne platí ",{"math":"\\sqrt{x^2}=|x|"},"."]},{"h3":"Odstránenie menovateľov"},{"math":"\\frac{x+1}{x-2}=3"},{"p":[{"b":"Podmienky:"}," ",{"math":"U=\\mathbb R,\\ P:x\\ne2"},". Násobenie výrazom ",{"math":"x-2"}," je ekvivalentné iba na obore, kde ",{"math":"x-2\\ne0"},":"]},{"math":"\\frac{x+1}{x-2}=3\\Longleftrightarrow x+1=3(x-2)\\Longleftrightarrow x=\\frac72"},{"p":["Hodnota ",{"math":"\\frac72"}," podmienku spĺňa. Zakázaná hodnota ",{"math":"2"}," sa nesmie vrátiť ani vtedy, ak sa menovateľ počas výpočtu stratí."]},{"h2":"6. Správny štandardný postup úpravy rovnice"},{"p":["1. ",{"b":"Napíš obor:"}," napríklad ",{"math":"U=\\mathbb R"},"."]},{"p":["2. ",{"b":"Urči podmienky:"}," menovatele, odmocniny, logaritmy a plánované delenie."]},{"p":["3. ",{"b":"Uprav každú stranu:"}," zátvorky, mocniny, súčiny a podobné členy."]},{"p":["4. ",{"b":"Odstráň zlomky bezpečne:"}," násob najmenším spoločným násobkom menovateľov a zachovaj pôvodné podmienky."]},{"p":["5. ",{"b":"Presuň všetky členy na jednu stranu:"}," pri polynomiálnej rovnici získaj ",{"math":"P(x)=0"},"."]},{"p":["6. ",{"b":"Zoraď členy zostupne podľa exponentu:"}," napríklad ",{"math":"3x^4-2x^2+7x-1=0"},"."]},{"p":["7. ",{"b":"Vyrieš rovnicu vhodnou metódou."}]},{"p":["8. ",{"b":"Porovnaj kandidátov s podmienkami a urob skúšku v pôvodnej rovnici."}]},{"p":["9. ",{"b":"Zapíš množinu riešení:"}," napríklad ",{"math":"S=\\left\\{-1,2\\right\\}"},"."]},{"p":["Neznáma na ľavej strane nie je matematická povinnosť, ale užitočná konvencia. Zápisy ",{"math":"x=4"}," a ",{"math":"4=x"}," sú rovnocenné. Pri polynómoch je najprehľadnejší normálny tvar s nulou na pravej strane a najvyšším exponentom na začiatku."]},{"h3":"Komplikovaný príklad v správnom poradí"},{"math":"\\frac{2(x-1)}{3}-\\frac{x+5}{2}=\\frac{x-7}{6}"},{"p":[{"b":"Podmienky:"}," ",{"math":"U=\\mathbb R"},"; menovatele ",{"math":"2,3,6"}," sú nenulové konštanty."]},{"math":"\\begin{aligned}\n6\\left(\\frac{2(x-1)}3-\\frac{x+5}2\\right)&=6\\cdot\\frac{x-7}6\\\\\n4(x-1)-3(x+5)&=x-7\\\\\n4x-4-3x-15&=x-7\\\\\nx-19&=x-7\\\\\n-19&=-7.\n\\end{aligned}"},{"p":["Vznikol spor, preto ",{"math":"S=\\varnothing"},". Nie je správne „vydeliť rovnicu číslom ",{"math":"x"},"“ ani tvrdiť, že ",{"math":"x"}," sa rovná nejakej hodnote; neznáme sa úplne vyrušili."]},{"h2":"7. Ako určiť počet riešení"},{"p":"Počet riešení neurčujeme iba podľa vzhľadu pôvodného zápisu. Rovnicu najprv upravíme pri zachovaní podmienok."},{"h3":"Lineárna rovnica"},{"p":["Po úprave do tvaru ",{"math":"Ax=B"}," nastanú presne tri prípady:"]},{"p":["• ",{"math":"A\\ne0"}," ⇒ jedno riešenie ",{"math":"x=\\frac BA"},"."]},{"p":["• ",{"math":"A=0,\\ B=0"}," ⇒ pravdivý výrok ",{"math":"0=0"},", teda ",{"math":"S=U"},"."]},{"p":["• ",{"math":"A=0,\\ B\\ne0"}," ⇒ spor ",{"math":"0=B"},", teda ",{"math":"S=\\varnothing"},"."]},{"h3":"Polynomiálna rovnica"},{"p":["Polynóm stupňa ",{"math":"n"}," má najviac ",{"math":"n"}," rôznych reálnych koreňov. V komplexných číslach má presne ",{"math":"n"}," koreňov, ak počítame násobnosti. Stupeň teda dáva ",{"b":"hornú hranicu"},", nie automaticky počet reálnych riešení."]},{"p":["• ",{"math":"x^2-1=0"}," má v ",{"math":"\\mathbb R"}," dve riešenia."]},{"p":["• ",{"math":"x^2=0"}," má jedno rôzne riešenie, ale dvojnásobný koreň."]},{"p":["• ",{"math":"x^2+1=0"}," nemá v ",{"math":"\\mathbb R"}," riešenie, no v ",{"math":"\\mathbb C"}," má korene ",{"math":"\\pm i"},"."]},{"h3":"Racionálne a odmocninové rovnice"},{"p":"Po odstránení menovateľov alebo odmocnín získame iba kandidátov. Skutočný počet riešení poznáme až po:"},{"p":"1. vyriešení pomocnej rovnice,"},{"p":"2. vylúčení hodnôt porušujúcich podmienky,"},{"p":"3. skúške v pôvodnej rovnici."},{"h3":"Rovnice s parametrom"},{"p":"Parameter môže meniť počet riešení. V rovnici"},{"math":"(a-2)x=a-2"},{"p":["platí ",{"math":"U=\\mathbb R"}," pre neznámu ",{"math":"x"}," a parameter ",{"math":"a\\in\\mathbb R"},". Ak ",{"math":"a\\ne2"},", môžeme deliť ",{"math":"a-2"}," a dostaneme ",{"math":"x=1"},". Ak ",{"math":"a=2"},", rovnica sa zmení na ",{"math":"0=0"}," a riešením je každé ",{"math":"x\\in\\mathbb R"},"."]},{"h2":"Úlohy na precvičenie"},{"p":["1. Zapíšte obor a podmienky rovnice ",{"math":"\\frac{\\sqrt{x+2}}{x^2-9}=1"},"."]},{"p":["2. Vysvetlite, prečo z rovnice ",{"math":"(x-4)(x+1)=0"}," nemožno bez rozdelenia prípadov deliť výrazom ",{"math":"x-4"},"."]},{"p":["3. Vyriešte a určte počet riešení: ",{"math":"4(2x-1)-3x=5x-4"},"."]},{"p":["4. Vyriešte a určte počet riešení: ",{"math":"3(x-2)+7=3x+1"},"."]},{"p":["5. Vyriešte s podmienkou: ",{"math":"\\frac{x^2-4}{x-2}=0"},"."]},{"p":["6. Nájdite nepravé riešenie vzniknuté umocnením: ",{"math":"\\sqrt{x+6}=x"},"."]},{"p":["7. Pre parameter ",{"math":"a\\in\\mathbb R"}," určte počet riešení rovnice ",{"math":"(a-1)x=2"},"."]},{"p":["8. Upravte do normálneho tvaru so zostupnými exponentmi: ",{"math":"5-2x^3+x=4x^2-7"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. ",{"math":"U=\\mathbb R"},", odmocnina vyžaduje ",{"math":"x\\ge-2"},", menovateľ ",{"math":"x\\ne\\pm3"},". Spolu ",{"math":"P:x\\ge-2,\\ x\\ne3"},"; hodnota ",{"math":"-3"}," už neleží v ",{"math":"x\\ge-2"},"."]},{"p":["2. Delením výrazom ",{"math":"x-4"}," by sme zaviedli podmienku ",{"math":"x\\ne4"}," a stratili koreň ",{"math":"x=4"},". Správne: ",{"math":"x=4\\lor x=-1"},"."]},{"p":["3. Po roznásobení ",{"math":"8x-4-3x=5x-4"},", teda ",{"math":"5x-4=5x-4"},". Ide o identitu: ",{"math":"S=\\mathbb R"},"."]},{"p":["4. ",{"math":"3x-6+7=3x+1"}," vedie na ",{"math":"3x+1=3x+1"},". Opäť ",{"math":"S=\\mathbb R"},"."]},{"p":["5. ",{"math":"U=\\mathbb R,\\ P:x\\ne2"},". Rozklad ",{"math":"\\frac{(x-2)(x+2)}{x-2}=0"}," dá pri zachovaní podmienky ",{"math":"x+2=0"},", takže ",{"math":"S=\\{-2\\}"},"."]},{"p":["6. Podmienka pravej strany: ",{"math":"x\\ge0"},". Po umocnení ",{"math":"x+6=x^2"},", teda ",{"math":"(x-3)(x+2)=0"},". Kandidáti sú ",{"math":"3,-2"},", ale ",{"math":"-2"}," je nepravý. ",{"math":"S=\\{3\\}"},"."]},{"p":["7. Ak ",{"math":"a\\ne1"},", je jedno riešenie ",{"math":"x=\\frac2{a-1}"},". Ak ",{"math":"a=1"},", vznikne spor ",{"math":"0=2"},", teda žiadne riešenie."]},{"p":["8. ",{"math":"2x^3+4x^2-x-12=0"},"."]},{"p":"Úprava — Čo treba sledovať"},{"p":"pripočítanie rovnakého výrazu — ekvivalentná úprava"},{"p":"násobenie známym nenulovým číslom — ekvivalentná úprava"},{"p":"násobenie výrazom s neznámou — môže pridať riešenia, treba rozbor"},{"p":"umocnenie na párnu mocninu — iba dôsledkový krok, nutná skúška"},{"p":"Podmienky zapisuj ešte pred úpravami. Pri parametrickej rovnici rozdeľ riešenie podľa hodnôt parametra, pri ktorých by sa delilo nulou."},{"test":"# Krátky test: Množiny, podmienky a bezpečné úpravy rovníc\n\n[ABCD]\nKtorá úprava je vždy ekvivalentná?\n* Pripočítanie rovnakého definovaného výrazu k obom stranám\n- Vydelenie oboch strán výrazom x\n- Umocnenie oboch strán na druhú\n- Odmocnenie oboch strán bez absolútnej hodnoty\n\n[ABCD]\nPrečo môže delenie rovnice výrazom x stratiť riešenie?\n* Pretože prípad x=0 sa delením vylúči\n- Pretože sa zmení stupeň vždy na vyšší\n- Pretože x musí byť kladné\n- Pretože delenie nie je definované pre záporné x\n\n[ABCD]\nČo znamená zápis U=R, P: x≠2?\n* Hľadáme reálne riešenia okrem hodnoty 2\n- Hľadáme iba celé čísla\n- Číslo 2 je jediné riešenie\n- Rovnica nemá riešenie\n\n[ABCD]\nKoľko riešení má po úprave rovnica 0x=0 v obore R?\n* Nekonečne veľa\n- Žiadne\n- Práve jedno\n- Práve dve\n\n[ABCD]\nČo treba urobiť po umocnení rovnice?\n* Overiť kandidátov v pôvodnej rovnici\n- Automaticky prijať všetky korene\n- Vydeliť rovnicu nulou\n- Zmeniť obor na prirodzené čísla\n\n[ABCD]\nAk rovnica skončí tvarom 0=5, počet riešení je:\n* Žiadne riešenie\n- Jedno riešenie\n- Nekonečne veľa riešení\n- Päť riešení"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."],"role":"instruction"},{"h2":"Zapamätaj si"},{"p":"• Obor a podmienky: Najprv zapíš U a P; výsledok musí spĺňať oboje."},{"p":"• Ekvivalentná úprava: Zachováva presne rovnakú množinu riešení."},{"p":"• Riziková úprava: Násobenie alebo delenie výrazom s neznámou, umocnenie a odmocnenie môžu pridať alebo odobrať riešenia."}]},{"id":"linearne-rovnice-a-skuska","title":"Lineárne rovnice a skúška riešenia","blocks":[{"p":"Ako vyriešime lineárnu rovnicu a spoľahlivo overíme výsledok?"},{"h2":"Egyptské úlohy na „aha“"},{"p":"Rhindov matematický papyrus z približne roku 1650 pred n. l. obsahuje úlohy, v ktorých sa hľadá neznáme množstvo označované slovom „aha“. Pisári používali metódu falošnej polohy: vyskúšali vhodnú hodnotu a výsledok úmerne opravili. Išlo o predchodcu riešenia lineárnych rovníc."},{"p":"Predstav si túto situáciu ako krátke vyšetrovanie. Máš tvrdenie, ktoré môže byť pravdivé aj klamlivé, a potrebuješ dôkaz. Jedno nastavenie grafu nestačí, pretože môže ísť o náhodu. Zmeníš parameter, odmeriaš výsledok a potom zámerne vyhľadáš hraničný prípad. Interaktívna úloha ti pridelí bod iba vtedy, keď podmienku naozaj splníš. Tým sa z pozorovania stane overiteľný matematický argument. Ako vyriešime lineárnu rovnicu a spoľahlivo overíme výsledok? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"graph":{"title":"Riešenie ako priesečník priamok","bounds":[-6,8,-8,10],"commands":["a=2","b=-3","c=5","f(x)=a*x+b","g(x)=c","X=((c-b)/a,c)","xx=x(X)","xy=y(X)"],"controls":[["a",-4,4,0.25,2],["b",-6,6,0.25,-3],["c",-6,6,0.25,5]],"tasks":[{"text":"Nastav rovnice tak, aby ich priesečník bol približne (2, 1).","condition":"xx>1.95 && xx<2.05 && xy>0.95 && xy<1.05"},{"text":"Nastav priesečník približne na (−1, 4).","condition":"xx>-1.05 && xx<-0.95 && xy>3.95 && xy<4.05"}],"colors":{"f":[29,78,216],"g":[220,38,38],"X":[22,163,74]},"toolbar":true}},{"p":[{"b":"Obor a podmienky:"}," Ak pri konkrétnom príklade nie je napísané inak, základný obor je ",{"math":"U=\\mathbb R"},". Pri zlomkoch, odmocninách a ďalších obmedzeniach sa navyše zapisuje podmienka ",{"math":"P"},"; riešenie musí patriť do oboru aj spĺňať všetky podmienky."]},{"p":["Lineárna rovnica s jednou neznámou má po úprave tvar ",{"math":"ax+b=0"},", kde ",{"math":"a\\ne0"},". Ekvivalentné úpravy vykonávame na oboch stranách rovnako: pripočítame alebo odčítame rovnaký výraz, prípadne obe strany násobíme alebo delíme tým istým nenulovým číslom."]},{"h2":"Základný vzorec"},{"math":"ax+b=0\\quad\\Longrightarrow\\quad x=-\\frac ba."},{"h2":"Príklad so zátvorkami"},{"math":"\\begin{aligned}3(2x-1)-4&=2(x+5)\\\\6x-3-4&=2x+10\\\\4x&=17\\\\x&=\\frac{17}{4}.\\end{aligned}"},{"h2":"Rovnica so zlomkami"},{"math":"\\begin{aligned}\\frac{x-1}{3}+\\frac{x+2}{2}&=4\\\\\n2(x-1)+3(x+2)&=24\\\\\n5x+4&=24\\\\x&=4.\n\\end{aligned}"},{"p":"Celú rovnicu sme vynásobili najmenším spoločným násobkom menovateľov, číslom 6."},{"h2":"Počet riešení"},{"p":["• ",{"math":"a\\ne0"},": práve jedno riešenie."]},{"p":["• ",{"math":"a=0,\\ b=0"},": identita a nekonečne veľa riešení."]},{"p":["• ",{"math":"a=0,\\ b\\ne0"},": spor a žiadne riešenie."]},{"p":[{"b":"Skúška"}," znamená dosadiť vypočítanú hodnotu do pôvodnej rovnice. Pre ",{"math":"x=4"}," v zlomkovej rovnici dostaneme ",{"math":"1+3=4"},"."]},{"h2":"Ako presne získať počet riešení lineárnej rovnice"},{"p":["Všeobecnú rovnicu ",{"math":"a_1x+b_1=a_2x+b_2"}," upravíme tak, aby neznáme boli na jednej strane a konštanty na druhej:"]},{"math":"(a_1-a_2)x=b_2-b_1"},{"p":["Označme ",{"math":"A=a_1-a_2"}," a ",{"math":"B=b_2-b_1"},". Potom rozhodujeme podľa rovnice ",{"math":"Ax=B"},":"]},{"p":["• ",{"math":"A\\ne0"},": jedno riešenie ",{"math":"x=B/A"},"."]},{"p":["• ",{"math":"A=0,\\ B=0"},": výsledok ",{"math":"0=0"},", takže každé prípustné ",{"math":"x"}," je riešením."]},{"p":["• ",{"math":"A=0,\\ B\\ne0"},": výsledok ",{"math":"0=B"},", čo je spor; riešenie neexistuje."]},{"h3":"Tri príklady s rovnakým vzhľadom, ale rôznym počtom riešení"},{"p":[{"b":"1. Jedno riešenie."}," ",{"math":"U=\\mathbb R"},"."]},{"math":"3(x-2)+5=2x+7\\Longleftrightarrow3x-1=2x+7\\Longleftrightarrow x=8"},{"p":[{"b":"2. Nekonečne veľa riešení."}," ",{"math":"U=\\mathbb R"},"."]},{"math":"3(x-2)+5=3x-1\\Longleftrightarrow3x-1=3x-1\\Longleftrightarrow0=0"},{"p":[{"b":"3. Žiadne riešenie."}," ",{"math":"U=\\mathbb R"},"."]},{"math":"3(x-2)+5=3x+4\\Longleftrightarrow3x-1=3x+4\\Longleftrightarrow0=5"},{"h2":"Komplikovaná rovnica: bezpečné násobenie celej rovnice"},{"math":"\\frac{2x-1}{4}-\\left(\\frac{x+3}{6}-\\frac{x-2}{3}\\right)=\\frac{5-x}{8}"},{"p":[{"b":"Podmienky:"}," ",{"math":"U=\\mathbb R"},"; všetky menovatele sú nenulové konštanty. Najmenší spoločný násobok je ",{"math":"24"},". Číslom ",{"math":"24"}," násobíme ",{"b":"každý člen oboch strán"},":"]},{"math":"\\begin{aligned}\n24\\left[\\frac{2x-1}{4}-\\left(\\frac{x+3}{6}-\\frac{x-2}{3}\\right)\\right]\n&=24\\cdot\\frac{5-x}{8}\\\\\n6(2x-1)-4(x+3)+8(x-2)&=3(5-x)\\\\\n12x-6-4x-12+8x-16&=15-3x\\\\\n16x-34&=15-3x\\\\\n19x&=49\\\\\nx&=\\frac{49}{19}.\n\\end{aligned}"},{"p":["Vnorená zátvorka mala pred sebou mínus. Po vynásobení číslom ",{"math":"24"}," preto vzniklo ",{"math":"-4(x+3)+8(x-2)"},", nie ",{"math":"-4(x+3)-8(x-2)"},"."]},{"h3":"Praktická kontrolná schéma"},{"p":"1. Zakrúžkuj celú ľavú a celú pravú stranu."},{"p":"2. Ak násobíš číslom alebo výrazom, najprv napíš zátvorky okolo oboch strán."},{"p":"3. Pri každom riadku urob iba jeden typ operácie."},{"p":"4. Po vyrušení neznámej nehádam hodnotu; rozhodnem medzi identitou a sporom."},{"p":["5. Výsledok zapíšem ako množinu ",{"math":"S"}," a urobím skúšku."]},{"h2":"Úlohy na precvičenie"},{"p":["1. Vyriešte ",{"math":"5x-7=18"},"."]},{"p":["2. Vyriešte ",{"math":"4(2x-3)=3x+13"},"."]},{"p":["3. Rozhodnite o počte riešení: ",{"math":"2x+3=2x+3"}," a ",{"math":"2x+3=2x+5"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. ",{"math":"x=5"},"."]},{"p":["2. ",{"math":"8x-12=3x+13"},", teda ",{"math":"5x=25"}," a ",{"math":"x=5"},"."]},{"p":"3. Prvá rovnica je identita a má nekonečne veľa riešení; druhá je spor a nemá riešenie."},{"p":["Rovnica ",{"math":"ax+b=0"}," má pri ",{"math":"a\\ne0"}," riešenie ",{"math":"x=-b/a"},". Ak ",{"math":"a=0"},", dostaneme buď spor, alebo identitu."]},{"p":["Pri vyjadrovaní zo vzorca sleduj podmienky: z ",{"math":"v=s/t"}," dostaneme ",{"math":"t=s/v"}," iba pre ",{"math":"v\\ne0"},"; z ",{"math":"R=U/I"}," dostaneme ",{"math":"I=U/R"}," iba pre ",{"math":"R\\ne0"},". Skúšku rob v pôvodnej rovnici."]},{"test":"# Krátky test: Lineárne rovnice a skúška riešenia\n\n[ABCD]\nAký je tvar lineárnej rovnice?\n* ax + b = 0, a ≠ 0\n- ax² + b = 0\n- a/x + b = 0\n- ax³ + b = 0\n\n[ABCD]\nČo možno urobiť s oboma stranami rovnice?\n* Pripočítať k nim rovnaký výraz\n- Zmeniť iba ľavú stranu\n- Deliť jednu stranu nulou\n- Odstrániť ľubovoľný člen\n\n[ABCD]\nKoľko riešení má 0x=0?\n* Nekonečne veľa\n- Jedno\n- Žiadne\n- Presne dve\n\n[ABCD]\nNa čo slúži skúška?\n* Na overenie riešenia v pôvodnej rovnici\n- Na určenie stupňa polynómu\n- Na zmenu znamienka nerovnosti\n- Na výpočet determinantu"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."],"role":"instruction"},{"h2":"Zapamätaj si"},{"p":["• Lineárna rovnica: Po úprave má tvar ",{"math":"ax+b=0"},"."]},{"p":"• Ekvivalentná úprava: Zachová množinu riešení, ak ju správne vykonáme na oboch stranách."},{"p":"• Skúška: Dosadenie koreňa do pôvodnej rovnice overí správnosť."}]},{"id":"kvadraticke-rovnice-metody","title":"Kvadratické rovnice: štyri metódy riešenia","blocks":[{"p":"Ktorá metóda vyrieši danú kvadratickú rovnicu najkratšie?"},{"h2":"Babylončania dopĺňali na štvorec pred štyrmi tisícročiami"},{"p":"Starobabylonské tabuľky ukazujú postupy ekvivalentné dopĺňaniu na štvorec. Úlohy boli zapísané slovne a interpretované cez obsahy obdĺžnikov a štvorcov. Dnešný kvadratický vzorec je zhustením geometrickej metódy, ktorá je stará približne štyri tisíc rokov."},{"p":"Za touto témou je vždy rovnaká vedecká otázka: čo možno tvrdiť na základe merania a čo je iba dojem z obrázka? Odpoveď získame porovnaním viacerých stavov, nie zapamätaním definície. V nasledujúcom modeli preto dostaneš cieľ vyjadrený číslom, polohou alebo vzťahom. Posuvníky a voľné body sú tvoje nástroje; bod za úlohu získaš až po splnení podmienky zapísanej priamo v dátach grafu. Ktorá metóda vyrieši danú kvadratickú rovnicu najkratšie? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"p":[{"b":"Najprv si tipni:"},"Nastav parabolu otvorenú nahor s vrcholom (1, −4). Zapíš si odhad skôr, než pohneš prvým ovládačom."],"role":"instruction"},{"graph":{"title":"Tri tvary kvadratickej funkcie","bounds":[-6,8,-8,10],"commands":["a=1","p=2","q=-3","f(x)=a*(x-p)^2+q","V=(p,q)","vx=p","vy=q"],"controls":[["a",-3,3,0.25,1],["p",-4,4,0.25,2],["q",-5,5,0.25,-3]],"tasks":[{"text":"Nastav parabolu otvorenú nahor s vrcholom (1, −4).","condition":"a>0 && p>0.95 && p<1.05 && q>-4.05 && q<-3.95"},{"text":"Nastav parabolu otvorenú nadol, ktorá sa osi x dotýka v bode x=−2.","condition":"a<0 && p>-2.05 && p<-1.95 && q>-0.05 && q<0.05"}],"colors":{"f":[29,78,216],"V":[220,38,38]},"toolbar":true}},{"p":[{"b":"Obor a podmienky:"}," Ak pri konkrétnom príklade nie je napísané inak, základný obor je ",{"math":"U=\\mathbb R"},". Pri zlomkoch, odmocninách a ďalších obmedzeniach sa navyše zapisuje podmienka ",{"math":"P"},"; riešenie musí patriť do oboru aj spĺňať všetky podmienky."]},{"p":["Kvadratická rovnica má tvar ",{"math":"ax^2+bx+c=0"},", kde ",{"math":"a\\ne0"},". Má najviac dva rôzne reálne korene. Výber metódy závisí od tvaru rovnice."]},{"h2":"1. Rozklad na súčin"},{"math":"x^2-5x+6=(x-2)(x-3)=0."},{"p":["Podľa pravidla nulového súčinu je ",{"math":"x=2"}," alebo ",{"math":"x=3"},"."]},{"h2":"2. Odmocnenie"},{"math":"(x-4)^2=9\\quad\\Longrightarrow\\quad x-4=\\pm3\\quad\\Longrightarrow\\quad x=1\\ \\text{alebo}\\ 7."},{"p":["Pri odmocnení nesmieme zabudnúť na znamienko ",{"math":"\\pm"},"."]},{"h2":"3. Doplnenie na štvorec"},{"math":"\\begin{aligned}x^2-6x+5&=0\\\\\nx^2-6x+9-9+5&=0\\\\\n(x-3)^2&=4\\\\\nx&=1\\ \\text{alebo}\\ 5.\n\\end{aligned}"},{"h2":"4. Kvadratický vzorec"},{"math":"x_{1,2}=\\frac{-b\\pm\\sqrt{b^2-4ac}}{2a}."},{"h2":"Vrcholový a súčinový tvar"},{"p":["Kvadratickú funkciu môžeme zapisovať v tvare ",{"math":"f(x)=a(x-p)^2+q"},", kde vrchol je ",{"math":"V=(p,q)"},", alebo v súčinovom tvare ",{"math":"f(x)=a(x-x_1)(x-x_2)"},", ak má reálne korene."]},{"h2":"Najprv overte, či je rovnica skutočne kvadratická"},{"p":"Rovnicu upravíme do normálneho tvaru so zostupnými exponentmi:"},{"math":"ax^2+bx+c=0"},{"p":["Je kvadratická iba vtedy, keď ",{"math":"a\\ne0"},". Ak sa kvadratické členy vyrušia alebo parameter spôsobí ",{"math":"a=0"},", rovnica sa zmení na lineárnu, identitu alebo spor."]},{"p":[{"b":"Príklad:"}," ",{"math":"U=\\mathbb R"},"."]},{"math":"2(x^2-x)+3=x^2+(x-1)^2+4"},{"math":"\\begin{aligned}\n2x^2-2x+3&=x^2+x^2-2x+1+4\\\\\n2x^2-2x+3&=2x^2-2x+5\\\\\n3&=5.\n\\end{aligned}"},{"p":["Hoci pôvodná rovnica obsahovala ",{"math":"x^2"},", po úprave je spor a nemá riešenie. Typ rovnice preto definitívne určujeme až po zjednodušení."]},{"h2":"Nedeliť faktorom, ktorý môže byť nulový"},{"math":"(x-2)^2=x-2"},{"p":[{"b":"Podmienky:"}," ",{"math":"U=\\mathbb R"},". Ak vydelíme ",{"math":"x-2"},", stratíme možnosť ",{"math":"x=2"},". Správne presunieme všetko na jednu stranu:"]},{"math":"\\begin{aligned}\n(x-2)^2-(x-2)&=0\\\\\n(x-2)\\bigl((x-2)-1\\bigr)&=0\\\\\n(x-2)(x-3)&=0.\n\\end{aligned}"},{"p":["Preto ",{"math":"S=\\{2,3\\}"},"."]},{"h2":"Počet riešení pri parametri"},{"math":"(m-1)x^2-2x+1=0,\\qquad m\\in\\mathbb R"},{"p":[{"b":"Obor:"}," ",{"math":"x\\in\\mathbb R"},". Najprv oddelíme prípad, keď koeficient pri ",{"math":"x^2"}," zanikne."]},{"p":["• Ak ",{"math":"m=1"},", dostaneme lineárnu rovnicu ",{"math":"-2x+1=0"},", teda jedno riešenie ",{"math":"x=\\frac12"},"."]},{"p":["• Ak ",{"math":"m\\ne1"},", rovnica je kvadratická a ",{"math":"\\Delta=(-2)^2-4(m-1)=4(2-m)"},"."]},{"p":["• ",{"math":"m<2,\\ m\\ne1"},": ",{"math":"\\Delta>0"},", dve reálne riešenia."]},{"p":["• ",{"math":"m=2"},": ",{"math":"\\Delta=0"},", jeden dvojnásobný koreň."]},{"p":["• ",{"math":"m>2"},": ",{"math":"\\Delta<0"},", žiadny reálny koreň."]},{"p":["Tento príklad ukazuje, že pri parametroch sa musí pred použitím kvadratického vzorca skontrolovať podmienka ",{"math":"a\\ne0"},"."]},{"h3":"Kontrola výsledku"},{"p":["• Súčet koreňov má podľa Viètových vzťahov byť ",{"math":"-b/a"},"."]},{"p":["• Súčin koreňov má byť ",{"math":"c/a"},"."]},{"p":"• Každý koreň dosadíme do pôvodnej, nie iba do upravenej rovnice, najmä ak sme predtým umocňovali alebo odstraňovali menovatele."},{"h2":"Úlohy na precvičenie"},{"p":["1. Vyriešte rozkladom ",{"math":"x^2+x-6=0"},"."]},{"p":["2. Vyriešte odmocnením ",{"math":"(2x-1)^2=25"},"."]},{"p":["3. Doplnením na štvorec upravte ",{"math":"x^2+4x-5"}," do vrcholového tvaru."]},{"p":["4. Nájdite vrchol funkcie ",{"math":"f(x)=2(x+1)^2-8"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. ",{"math":"(x+3)(x-2)=0"},"; ",{"math":"x=-3,2"},"."]},{"p":["2. ",{"math":"2x-1=\\pm5"},"; ",{"math":"x=3"}," alebo ",{"math":"x=-2"},"."]},{"p":["3. ",{"math":"x^2+4x-5=(x+2)^2-9"},"."]},{"p":["4. ",{"math":"V=(-1,-8)"},"."]},{"p":"• Spoločný činiteľ alebo ľahko viditeľné korene: rozklad."},{"p":["• Tvar ",{"math":"(x-a)^2=b"},": odmocnenie."]},{"p":"• Potrebujeme vrcholový tvar: doplnenie na štvorec."},{"p":"• Všeobecný tvar: kvadratický vzorec."},{"p":"Nikdy nedeľ výrazom obsahujúcim neznámu bez osobitného preverenia prípadu, keď je tento výraz nulový. Takým delením možno stratiť riešenie."},{"test":"# Krátky test: Kvadratické rovnice: štyri metódy riešenia\n\n[ABCD]\nČo musí platiť pre koeficient a v kvadratickej rovnici?\n* a ≠ 0\n- a = 0\n- a > 1\n- a musí byť celé\n\n[ABCD]\nČo vyplýva z (x−2)(x+1)=0?\n* x=2 alebo x=−1\n- x=1 iba\n- x=−2 alebo 1\n- x=0\n\n[ABCD]\nAký je vrchol funkcie a(x−p)²+q?\n* [p,q]\n- [−p,q]\n- [a,q]\n- [p,a]\n\n[ABCD]\nNa čo nesmieme zabudnúť pri odmocnení A²=k?\n* Na znamienko ±\n- Na determinant\n- Na delenie nulou\n- Na zmenu všetkých koeficientov"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."],"role":"instruction"},{"h2":"Zapamätaj si"},{"p":["• Kvadratická rovnica: Má tvar ",{"math":"ax^{2}+bx+c=0"},", ",{"math":"a\\ne 0"},"."]},{"p":["• Nulový súčin: Ak ",{"math":"AB=0"},", potom ",{"math":"A=0"}," alebo ",{"math":"B=0"},"."]},{"p":"• Doplnenie na štvorec: Premení všeobecný tvar na vrcholový tvar."}]},{"id":"nelinearne-rovnice-a-podmienky","title":"Nelineárne rovnice a definičné podmienky","blocks":[{"p":"Prečo môže správne vyzerajúci výpočet vytvoriť neprípustné riešenie?"},{"h2":"Úvodná výzva"},{"p":[{"b":"Výzva:"},"Prečo môže správne vyzerajúci výpočet vytvoriť neprípustné riešenie?"],"role":"hook"},{"h2":"Odmocniny prinútili matematikov kontrolovať výsledky"},{"p":"Pri starých postupoch riešenia rovníc sa často objavili kandidáti, ktorí po spätnom dosadení nefungovali. Umocnenie totiž zabúda na znamienko: čísla a a -a majú rovnaký štvorec. Skúška v pôvodnej rovnici sa preto stala neoddeliteľnou súčasťou bezpečného riešenia."},{"p":"Historický krok bol dôležitý najmä preto, že premenil obraz na postup, ktorý sa dal zopakovať. Aj ty začneš bez hotového pravidla. Skús si vopred predstaviť výsledok, potom upravuj iba tie veličiny, ktoré sú v modeli voľné, a sleduj pomenované čísla alebo polohy. Úloha je nastavená tak, aby nestačilo trafiť jednu očividnú hodnotu; musíš skombinovať viac podmienok a skontrolovať, či výsledný obraz dáva zmysel. Prečo môže správne vyzerajúci výpočet vytvoriť neprípustné riešenie? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"p":[{"b":"Najprv si tipni:"},"Nastav priamku tak, aby sa odmocninovej krivky iba dotýkala. Zapíš si odhad skôr, než pohneš prvým ovládačom."],"role":"instruction"},{"graph":{"title":"Odmocninová rovnica ako priesečník","bounds":[-2,7,-3,5],"commands":["f(x)=sqrt(x+1)","p=Slider(-2,2,0.05,1,150,false,true,false,false)","SetValue(p,1)","g(x)=x-p","Delta=4*p+5"],"tasks":[{"text":"Nastav priamku tak, aby sa odmocninovej krivky iba dotýkala.","condition":"Delta>-0.03 && Delta<0.03"},{"text":"Nastav parameter tak, aby mala rovnica dva reálne priesečníky a p bolo kladné.","condition":"Delta>0.5 && p>0"}],"colors":{"f":[29,78,216],"g":[220,38,38]},"toolbar":true}},{"p":[{"b":"Obor a podmienky:"}," Ak pri konkrétnom príklade nie je napísané inak, základný obor je ",{"math":"U=\\mathbb R"},". Pri zlomkoch, odmocninách a ďalších obmedzeniach sa navyše zapisuje podmienka ",{"math":"P"},"; riešenie musí patriť do oboru aj spĺňať všetky podmienky."]},{"p":["Nelineárna rovnica obsahuje neznámu inak než iba v prvej mocnine: môže obsahovať ",{"math":"x^2"},", súčin premenných, neznámu v menovateli, odmocninu, absolútnu hodnotu, exponenciálnu alebo logaritmickú funkciu."]},{"h2":"Racionálna rovnica"},{"math":"\\begin{aligned}\\frac{x+1}{x-2}&=3,\\qquad x\\ne2,\\\\\nx+1&=3(x-2),\\\\\n7&=2x,\\\\\nx&=\\frac72.\n\\end{aligned}"},{"p":["Hodnota ",{"math":"\\frac72"}," spĺňa podmienku ",{"math":"x\\ne2"},"."]},{"h2":"Odmocninová rovnica"},{"math":"\\begin{aligned}\\sqrt{x+1}&=x-1,\\\\\nx&\\ge1,\\\\\nx+1&=(x-1)^2,\\\\\nx^2-3x&=0,\\\\\nx&\\in\\{0,3\\}.\n\\end{aligned}"},{"p":["Kandidát ",{"math":"x=0"}," nevyhovuje podmienke ani pôvodnej rovnici. Jediným riešením je ",{"math":"x=3"},". Umocnenie môže vytvoriť ",{"b":"nepravé riešenie"},"."]},{"h2":"Absolútna hodnota"},{"math":"|2x-3|=5\\quad\\Longleftrightarrow\\quad 2x-3=5\\ \\text{alebo}\\ 2x-3=-5."},{"p":["Riešenia sú ",{"math":"x=4"}," a ",{"math":"x=-1"},"."]},{"h2":"Substitúcia"},{"p":["V rovnici ",{"math":"x^4-5x^2+4=0"}," položme ",{"math":"t=x^2"},". Dostaneme ",{"math":"t^2-5t+4=0"},", teda ",{"math":"t=1"}," alebo ",{"math":"t=4"},". Preto ",{"math":"x=\\pm1,\\pm2"},"."]},{"h2":"Rozšírenie: kandidát nie je automaticky riešenie"},{"p":"Pri nelineárnych rovniciach často používame kroky, ktoré nie sú obojstranne ekvivalentné. Preto rozlišujeme:"},{"p":["• ",{"b":"kandidát"}," – hodnota získaná z upravenej rovnice,"]},{"p":["• ",{"b":"riešenie"}," – kandidát, ktorý patrí do oboru, spĺňa podmienky a po dosadení vyhovuje pôvodnej rovnici."]},{"p":"Operácia — Riziko — Ochrana"},{"p":"násobenie výrazom s neznámou — môže pridať nuly tohto výrazu — zapísať, že násobiteľ je nenulový, alebo vykonať skúšku"},{"p":"delenie výrazom s neznámou — môže odstrániť riešenie, kde je deliteľ nulový — rozdeliť výpočet na prípady"},{"p":"umocnenie párnou mocninou — môže pridať riešenia s opačným znamienkom — skúška v pôvodnej rovnici"},{"p":["odmocnenie — môže zabudnúť zápornú vetvu — použiť ",{"math":"\\sqrt{x^2}=|x|"}]},{"p":"krátenie spoločného činiteľa — môže skryť pôvodnú zakázanú hodnotu — podmienku ponechať až do konca"},{"h3":"Racionálna rovnica so skrytým zakázaným bodom"},{"math":"\\frac{x^2-1}{x-1}=0"},{"p":[{"b":"Podmienky:"}," ",{"math":"U=\\mathbb R,\\ P:x\\ne1"},"."]},{"math":"\\frac{(x-1)(x+1)}{x-1}=0\\Longleftrightarrow x+1=0,\\qquad x\\ne1"},{"p":["Dostaneme ",{"math":"x=-1"},". Hodnota ",{"math":"x=1"}," nie je riešením, hoci po skrátení ju v novom výraze už nevidíme."]},{"h3":"Odmocninová rovnica a nepravý koreň"},{"math":"\\sqrt{x+5}=x-1"},{"p":[{"b":"Podmienky:"}," pod odmocninou ",{"math":"x+5\\ge0"}," a pravá strana musí byť nezáporná, teda spolu ",{"math":"P:x\\ge1"},"."]},{"math":"\\begin{aligned}\n\\sqrt{x+5}=x-1&\\Longrightarrow x+5=(x-1)^2\\\\\n&\\Longrightarrow x^2-3x-4=0\\\\\n&\\Longrightarrow (x-4)(x+1)=0.\n\\end{aligned}"},{"p":["Kandidáti sú ",{"math":"x=4"}," a ",{"math":"x=-1"},". Druhý porušuje ",{"math":"x\\ge1"},". Skúška prvého: ",{"math":"\\sqrt9=3"},". Preto ",{"math":"S=\\{4\\}"},"."]},{"h3":"Rovnica s dvoma odmocninami"},{"math":"\\sqrt{x+1}+\\sqrt{x-2}=3"},{"p":[{"b":"Podmienky:"}," ",{"math":"U=\\mathbb R,\\ P:x\\ge2"},". Izolujeme jednu odmocninu a až potom umocníme:"]},{"math":"\\begin{aligned}\n\\sqrt{x+1}&=3-\\sqrt{x-2}\\\\\nx+1&=9-6\\sqrt{x-2}+x-2\\\\\n6\\sqrt{x-2}&=6\\\\\n\\sqrt{x-2}&=1\\\\\nx&=3.\n\\end{aligned}"},{"p":["Skúška: ",{"math":"\\sqrt4+\\sqrt1=2+1=3"},". Pri dvoch odmocninách môže byť potrebné umocňovať dvakrát; po každom umocnení rastie význam záverečnej skúšky."]},{"h3":"Bikvadratická rovnica a substitúcia"},{"math":"x^4-5x^2+4=0"},{"p":[{"b":"Podmienky:"}," ",{"math":"U=\\mathbb R"},". Položíme ",{"math":"t=x^2"},", preto pri reálnych riešeniach navyše ",{"math":"t\\ge0"},"."]},{"math":"\\begin{aligned}\nt^2-5t+4&=0\\\\\n(t-1)(t-4)&=0\\\\\nt&=1\\ \\lor\\ t=4\\\\\nx^2&=1\\ \\lor\\ x^2=4\\\\\nx&=\\pm1\\ \\lor\\ x=\\pm2.\n\\end{aligned}"},{"p":["Množina riešení je ",{"math":"S=\\{-2,-1,1,2\\}"},". Substitúcia nesmie zabudnúť na spätné dosadenie."]},{"h2":"Ako odhadnúť a potvrdiť počet riešení"},{"p":"1. Určte definičný obor a podmienky."},{"p":"2. Graficky odhadnite počet priesečníkov ľavej a pravej strany."},{"p":"3. Algebraicky získajte všetkých kandidátov."},{"p":"4. Vylúčte zakázané a nepravé korene."},{"p":["5. Počet prvkov výslednej množiny ",{"math":"S"}," je počet riešení."]},{"p":"Graf je užitočná kontrola, ale presné riešenie musí vychádzať z výpočtu alebo z dôkazu o počte priesečníkov."},{"h2":"Úlohy na precvičenie"},{"p":["1. Vyriešte ",{"math":"\\frac{2x}{x-1}=4"},"."]},{"p":["2. Vyriešte ",{"math":"|x+2|=7"},"."]},{"p":["3. Vyriešte ",{"math":"\\sqrt{2x+3}=x"}," a vykonajte skúšku."]},{"p":["4. Použite substitúciu v ",{"math":"x^4-13x^2+36=0"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. Podmienka ",{"math":"x\\ne1"},"; ",{"math":"2x=4x-4"},", takže ",{"math":"x=2"},"."]},{"p":["2. ",{"math":"x+2=7"}," alebo ",{"math":"x+2=-7"},"; ",{"math":"x=5,-9"},"."]},{"p":["3. Podmienka ",{"math":"x\\ge0"},". Po umocnení ",{"math":"x^2-2x-3=0"},", kandidáti ",{"math":"3,-1"},"; vyhovuje iba ",{"math":"x=3"},"."]},{"p":["4. ",{"math":"t=x^2"},": ",{"math":"t^2-13t+36=(t-4)(t-9)"},"; ",{"math":"x=\\pm2,\\pm3"},"."]},{"p":["Za nelineárnu považujeme rovnicu, ktorú po úprave nemožno zapísať v tvare ",{"math":"ax+b=0"},". Pri umocnení na párnu mocninu používame dôsledkovú šípku a na konci skúšku."]},{"p":["Príklad: ",{"math":"\\sqrt{x+1}=x-1"}," vyžaduje ",{"math":"x\\ge1"},". Po umocnení vznikne ",{"math":"x+1=(x-1)^2"},", teda kandidáti ",{"math":"x=0"}," a ",{"math":"x=3"},". Podmienku aj pôvodnú rovnicu spĺňa iba ",{"math":"x=3"},"."]},{"p":["Pri ",{"math":"|2x-3|=5"}," riešime dve vetvy: ",{"math":"2x-3=5"}," alebo ",{"math":"2x-3=-5"},"."]},{"test":"# Krátky test: Nelineárne rovnice a definičné podmienky\n\n[ABCD]\nPrečo robíme skúšku po umocnení rovnice?\n* Môžu vzniknúť nepravé riešenia\n- Zmení sa stupeň polynómu na nulu\n- Menovateľ musí byť kladný\n- Aby vznikol determinant\n\n[ABCD]\nAká podmienka platí pre 1/(x−2)?\n* x ≠ 2\n- x > 2\n- x = 2\n- x < 0\n\n[ABCD]\nAko riešime |A|=k pre k>0?\n* A=k alebo A=−k\n- Iba A=k\n- A²=k\n- A=0\n\n[ABCD]\nKtorá rovnica je nelineárna?\n* x² − 3x = 0\n- 2x+1=5\n- x−7=0\n- 3x=12"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."],"role":"instruction"},{"h2":"Zapamätaj si"},{"p":"• Nelineárna rovnica: Obsahuje mocniny vyššie než 1 alebo inú nelineárnu operáciu."},{"p":"• Podmienky: Určujeme ich pred úpravami, najmä pri zlomkoch a odmocninách."},{"p":"• Nepravý koreň: Môže vzniknúť napríklad umocnením; preto robíme skúšku."}]},{"id":"nerovnice-a-znamenkova-tabulka","title":"Nerovnice a znamienková tabuľka","blocks":[{"p":"Prečo sa pri násobení záporným číslom obráti znak nerovnosti?"},{"h2":"Znaky menší a väčší zaviedol Thomas Harriot"},{"p":[{"math":"Symboly < a"}," > sa objavili v posmrtne vydanej knihe Thomasa Harriota z roku 1631. Predtým sa nerovnosti zapisovali slovami. Dvojica jednoduchých značiek výrazne uľahčila prácu s intervalmi, odhadmi a porovnávaním výrazov."]},{"p":"Takýto problém sa nedal vyriešiť pomenovaním nového pojmu. Bolo potrebné nájsť veličinu, ktorú možno meniť, výsledok, ktorý možno odmerať, a hraničný prípad, na ktorom sa nesprávna predstava odhalí. Presne to urobíš aj teraz. Najprv si zvolíš odhad, potom budeš posúvať ovládače alebo body a graf uzná úlohu až vtedy, keď dosiahneš požadovaný matematický stav. Prečo sa pri násobení záporným číslom obráti znak nerovnosti? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"p":[{"b":"Najprv si tipni:"},"Nastav vodorovnú hranicu tak, aby priesečník s priamkou mal x-ovú súradnicu približne 1. Zapíš si odhad skôr, než pohneš prvým ovládačom."],"role":"instruction"},{"graph":{"title":"Lineárna nerovnica na grafe","bounds":[-5,7,-8,12],"commands":["f(x)=-3*x+6","k=Slider(-3,6,0.1,1,150,false,true,false,false)","SetValue(k,0)","g(x)=k","r=(6-k)/3","R=(r,k)"],"tasks":[{"text":"Nastav vodorovnú hranicu tak, aby priesečník s priamkou mal x-ovú súradnicu približne 1.","condition":"r>0.95 && r<1.05"},{"text":"Nastav hranicu tak, aby priesečník ležal približne v bode (2, 0).","condition":"r>1.95 && r<2.05 && k>-0.05 && k<0.05"}],"colors":{"f":[29,78,216],"R":[220,38,38]},"toolbar":true}},{"p":[{"b":"Obor a podmienky:"}," Ak pri konkrétnom príklade nie je napísané inak, základný obor je ",{"math":"U=\\mathbb R"},". Pri zlomkoch, odmocninách a ďalších obmedzeniach sa navyše zapisuje podmienka ",{"math":"P"},"; riešenie musí patriť do oboru aj spĺňať všetky podmienky."]},{"p":["Nerovnica používa znaky ",{"math":"<,\\ >,\\ \\le,\\ \\ge"},". Riešením zvyčajne nie je jedno číslo, ale množina alebo interval."]},{"h2":"Ekvivalentné úpravy"},{"p":["Pri pripočítaní rovnakého výrazu sa znak nemení. Pri násobení alebo delení ",{"b":"záporným"}," číslom sa znak obráti:"]},{"math":"a<b\\quad\\Longrightarrow\\quad -a>-b."},{"h2":"Lineárna nerovnica"},{"math":"\\begin{aligned}-3x+6&>0\\\\-3x&>-6\\\\x&<2.\\end{aligned}"},{"p":["Po delení číslom ",{"math":"-3"}," sme obrátili znak. Intervalový zápis je ",{"math":"(-\\infty,2)"},"."]},{"h2":"Súčinová nerovnica"},{"math":"(x-1)(x+4)\\le0."},{"p":["Kritické body sú ",{"math":"-4"}," a ",{"math":"1"},". Tie rozdelia os na intervaly. Súčinu vyhovuje stredný interval a pri neostrej nerovnosti zahrnieme aj nulové body:"]},{"math":"x\\in[-4,1]."},{"h2":"Znamienková tabuľka"},{"p":"V každom intervale stačí skúšobný bod. Znamienko sa môže meniť iba v nulovom bode činiteľa alebo v bode, kde výraz nie je definovaný."},{"h2":"Ktoré operácie menia smer nerovnosti"},{"p":"• Pripočítanie alebo odčítanie rovnakého výrazu smer nemení."},{"p":"• Násobenie alebo delenie kladným číslom smer nemení."},{"p":["• Násobenie alebo delenie záporným číslom smer ",{"b":"obráti"},"."]},{"p":"• Násobenie výrazom s neznámym znamienkom nemožno urobiť bez rozdelenia na prípady."},{"math":"a<b,\\ c<0\\quad\\Longrightarrow\\quad ac>bc"},{"h3":"Prečo nesmieme bezhlavo odstrániť menovateľ"},{"math":"\\frac{2-x}{x+1}\\ge0"},{"p":[{"b":"Podmienky:"}," ",{"math":"U=\\mathbb R,\\ P:x\\ne-1"},". Nemôžeme jednoducho násobiť výrazom ",{"math":"x+1"},", pretože pre ",{"math":"x<-1"}," je záporný a pre ",{"math":"x>-1"}," kladný. Namiesto toho použijeme kritické body ",{"math":"-1"}," a ",{"math":"2"}," a znamienkovú tabuľku."]},{"p":["Výsledok je ",{"math":"S=(-1,2]"},". Bod ",{"math":"-1"}," je vylúčený menovateľom, bod ",{"math":"2"}," je zahrnutý, pretože nerovnosť obsahuje znak ",{"math":"\\ge"},"."]},{"h3":"Dvojitá nerovnica"},{"math":"-3<2x+1\\le7"},{"p":"Operáciu vykonávame vo všetkých troch častiach:"},{"math":"\\begin{aligned}\n-3-1&<2x\\le7-1\\\\\n-4&<2x\\le6\\\\\n-2&<x\\le3.\n\\end{aligned}"},{"h2":"Úlohy na precvičenie"},{"p":["1. Vyriešte ",{"math":"5x-10\\le0"},"."]},{"p":["2. Vyriešte ",{"math":"-2x+7>3"},"."]},{"p":["3. Vyriešte ",{"math":"(x-5)(x+2)>0"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. ",{"math":"x\\le2"},", teda ",{"math":"(-\\infty,2]"},"."]},{"p":["2. ",{"math":"-2x>-4"},", po delení záporným číslom ",{"math":"x<2"},"."]},{"p":["3. Kritické body ",{"math":"-2,5"},"; súčin je kladný mimo nich: ",{"math":"(-\\infty,-2)\\cup(5,\\infty)"},"."]},{"p":["Pri prechode cez koreň nepárnej násobnosti sa znamienko súčinu mení; pri párnej násobnosti zostáva rovnaké. Napríklad ",{"math":"(x-1)^2(x+2)<0"}," je záporné iba pre ",{"math":"x<-2"},"."]},{"p":"Nerovnicu nemožno bez rozboru násobiť výrazom s neznámym znamienkom: pri zápornom násobiteľovi sa znak otočí, pri kladnom nie a pri nulovom môže vzniknúť strata informácie."},{"test":"# Krátky test: Nerovnice a znamienková tabuľka\n\n[ABCD]\nKedy sa obráti znak nerovnosti?\n* Pri násobení alebo delení záporným číslom\n- Pri každom sčítaní\n- Pri delení kladným číslom\n- Nikdy\n\n[ABCD]\nAký interval zapisuje x<2?\n* (−∞,2)\n- [−∞,2]\n- (2,∞)\n- [2,∞)\n\n[ABCD]\nMôže nulový bod patriť do riešenia pri ≤?\n* Áno\n- Nie nikdy\n- Iba ak je menovateľom\n- Iba pri lineárnej rovnici\n\n[ABCD]\nNa čo slúži skúšobný bod v znamienkovej tabuľke?\n* Určí znamienko výrazu v intervale\n- Vypočíta determinant\n- Určí stupeň polynómu\n- Nahradí definičný obor"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."]},{"h2":"Zapamätaj si"},{"p":"• Obrátenie znaku: Nastáva pri násobení alebo delení záporným číslom."},{"p":"• Kritické body: Nulové body činiteľov a vylúčené body menovateľa."},{"p":["• Neostrá nerovnosť: ",{"math":"Znaky \\le a"}," ≥ môžu zahrnúť nulové body výrazu."]}]},{"id":"kvadraticke-a-racionalne-nerovnice","title":"Kvadratické a racionálne nerovnice","blocks":[{"p":"Ako z nulových a zakázaných bodov zostavíme správne intervaly riešenia?"},{"h2":"Descartovo pravidlo znamienok"},{"p":"René Descartes v roku 1637 opísal pravidlo, ktoré spája zmeny znamienok koeficientov polynómu s možným počtom kladných koreňov. Nie je to tá istá metóda ako dnešná znamienková tabuľka, no ukazuje, ako dôležitým zdrojom informácie bolo znamienko ešte pred rozvojom moderných grafov."},{"p":"Na stole by vtedy neležal hotový vzorec, iba údaje a otázka, ktorú bolo treba rozhodnúť. Užitočný nápad vzniká vtedy, keď sa neurčité slová nahradia meraním: zmeníš jednu hodnotu, sleduješ následok a porovnáš ho s ďalším prípadom. Rovnaký postup použiješ v interaktívnom modeli. Cieľ nebude splnený približným dojmom, ale až konkrétnou hodnotou alebo vzťahom medzi objektmi. Ako z nulových a zakázaných bodov zostavíme správne intervaly riešenia? Po úspechu si výsledok obháj jednou vetou a porovnaj ho s pôvodným odhadom, nie iba so zeleným potvrdením."},{"p":[{"b":"Najprv si tipni:"},"Nastav parabolu tak, aby v strede medzi koreňmi mala hodnotu približne −0,5. Zapíš si odhad skôr, než pohneš prvým ovládačom."],"role":"instruction"},{"graph":{"title":"Kvadratická nerovnica a orientácia paraboly","bounds":[-2,7,-8,10],"commands":["a=1","f(x)=a*(x-2)*(x-3)","ymid=f(2.5)"],"controls":[["a",-3,3,0.25,1]],"tasks":[{"text":"Nastav parabolu tak, aby v strede medzi koreňmi mala hodnotu približne −0,5.","condition":"ymid>-0.52 && ymid<-0.48"},{"text":"Obráť parabolu tak, aby v strede medzi koreňmi mala hodnotu približne 0,5.","condition":"ymid>0.48 && ymid<0.52"}],"colors":{"f":[29,78,216]},"toolbar":true}},{"p":[{"b":"Obor a podmienky:"}," Ak pri konkrétnom príklade nie je napísané inak, základný obor je ",{"math":"U=\\mathbb R"},". Pri zlomkoch, odmocninách a ďalších obmedzeniach sa navyše zapisuje podmienka ",{"math":"P"},"; riešenie musí patriť do oboru aj spĺňať všetky podmienky."]},{"h2":"Kvadratická nerovnica"},{"p":"Najprv nájdeme korene kvadratického trojčlena a určíme orientáciu paraboly."},{"math":"x^2-5x+6\\le0\\quad\\Longleftrightarrow\\quad(x-2)(x-3)\\le0."},{"p":["Parabola je otvorená nahor, preto je výraz záporný medzi koreňmi. Výsledok je ",{"math":"x\\in[2,3]"},"."]},{"h2":"Všeobecné znamienka"},{"p":["Ak ",{"math":"a>0"}," a existujú dva korene ",{"math":"x_1<x_2"},", potom je kvadratický výraz kladný mimo koreňov a záporný medzi nimi. Pri ",{"math":"a<0"}," sú znamienka opačné."]},{"p":["Ak ",{"math":"\\Delta<0"},", kvadratický výraz nemení znamienko: má stále znamienko koeficientu ",{"math":"a"},"."]},{"h2":"Racionálna nerovnica"},{"math":"\\frac{2x-1}{x+3}\\ge0."},{"p":["Kritické body sú ",{"math":"x=\\frac12"}," z čitateľa a ",{"math":"x=-3"}," z menovateľa. Bod ",{"math":"-3"}," nikdy nesmie patriť do riešenia. Znamienková tabuľka dá:"]},{"math":"x\\in(-\\infty,-3)\\cup\\left[\\frac12,\\infty\\right)."},{"h2":"Dôležité pravidlo"},{"p":"Nerovnicu so zlomkom neriešime bezhlavým násobením menovateľom, ak nepoznáme jeho znamienko. Bezpečný postup je previesť všetko na jednu stranu, rozložiť čitateľa a menovateľa a zostaviť znamienkovú tabuľku."},{"graph":{"title":"Racionálna nerovnica","bounds":[-8,7,-8,8],"commands":["asym: x=-3","c=Slider(-6,6,0.1,1,150,false,true,false,false)","SetValue(c,1)","f(x)=(2*x-c)/(x+3)","N=(c/2,0)","gap=c/2+3"],"tasks":[{"text":"Nastav nulový bod presne 2 jednotky napravo od zvislej asymptoty.","condition":"gap>1.95 && gap<2.05"},{"text":"Nastav nulový bod do počiatku.","condition":"c>-0.02 && c<0.02"}],"colors":{"f":[29,78,216],"asym":[220,38,38],"N":[22,163,74]},"toolbar":true}},{"h2":"Racionálna nerovnica: nikdy nekrížovo nenásobte bez znalosti znamienka"},{"p":"Pri rovnici možno po zapísaní podmienok odstrániť nenulový menovateľ. Pri nerovnici však znamienko menovateľa rozhoduje, či sa znak obráti. Preto všetko prenesieme na jednu stranu, rozložíme čitateľ a menovateľ a použijeme znamienkovú tabuľku."},{"math":"\\frac{(x-1)(x+3)}{(x-2)^2}\\le0,\\qquad U=\\mathbb R,\\ P:x\\ne2"},{"p":["Menovateľ ",{"math":"(x-2)^2"}," je pre všetky dovolené hodnoty kladný, takže znamienko určuje čitateľ. Čitateľ je nekladný medzi koreňmi ",{"math":"-3"}," a ",{"math":"1"},". Bod ",{"math":"2"}," v tomto intervale neleží. Výsledok je ",{"math":"S=[-3,1]"},"."]},{"p":["Ak by zakázaný bod ležal v riešenom intervale, museli by sme interval rozdeliť. Napríklad z ",{"math":"[-3,4]"}," a podmienky ",{"math":"x\\ne2"}," vznikne ",{"math":"[-3,2)\\cup(2,4]"},"."]},{"h2":"Úlohy na precvičenie"},{"p":["1. Vyriešte ",{"math":"x^2+2x-3>0"},"."]},{"p":["2. Vyriešte ",{"math":"-x^2+4x-3\\ge0"},"."]},{"p":["3. Vyriešte ",{"math":"\\frac{x-2}{x+1}<0"},"."]},{"p":"Zobraziť výsledky a postupy"},{"p":["1. ",{"math":"(x+3)(x-1)>0"},"; ",{"math":"(-\\infty,-3)\\cup(1,\\infty)"},"."]},{"p":["2. Korene sú 1 a 3, parabola je nad osou medzi nimi: ",{"math":"[1,3]"},"."]},{"p":["3. Kritické body ",{"math":"-1,2"},"; záporný interval je ",{"math":"(-1,2)"},". Bod ",{"math":"-1"}," je vylúčený."]},{"p":"Nulové body čitateľa môžu patriť do riešenia pri neostrej nerovnosti. Nulové body menovateľa sú vždy zakázané. Pri párnej násobnosti sa znamienko pri kritickom bode nemusí zmeniť."},{"p":["Výsledok zapisuj intervalovo aj na číselnej osi. Pri kvadratickom výraze treba rozlíšiť prípady ",{"math":"\\Delta<0"},", ",{"math":"\\Delta=0"},", ",{"math":"\\Delta>0"}," a znamienko vedúceho koeficientu."]},{"test":"# Krátky test: Kvadratické a racionálne nerovnice\n\n[ABCD]\nKde je parabola s a>0 a dvoma koreňmi záporná?\n* Medzi koreňmi\n- Mimo koreňov\n- Iba v ľavom koreni\n- Nikde\n\n[ABCD]\nMôže bod, v ktorom je menovateľ nulový, patriť do riešenia?\n* Nie\n- Áno pri ≥\n- Áno pri ≤\n- Áno vždy\n\n[ABCD]\nČo urobíme najprv pri kvadratickej nerovnici?\n* Nájdeme korene a orientáciu paraboly\n- Vypočítame determinant matice\n- Zderivujeme výraz\n- Vždy vydelíme x\n\n[ABCD]\nAk Δ<0 a a>0, aké je znamienko trojčlena?\n* Všade kladné\n- Všade záporné\n- Strieda sa v nule\n- Nie je definované"},{"p":[{"b":"Vráť sa k prvému odhadu:"},"Zmenil sa po splnení bodovaných úloh? Uveď jednu konkrétnu hodnotu, polohu bodu alebo vlastnosť grafu, ktorá tvoje rozhodnutie podopiera."],"role":"instruction"},{"h2":"Zapamätaj si"},{"p":"• Kvadratická nerovnica: Riešenie čítame zo znamienka paraboly vzhľadom na os x."},{"p":"• Racionálna nerovnica: Nulové body čitateľa môžu byť zahrnuté; nulové body menovateľa nikdy."},{"p":["• ",{"math":"Diskriminant < 0"},": Kvadratický výraz má stále znamienko vedúceho koeficientu."]}]},{"id":"finalne-cvicenie-vsetky-priklady","title":"Finálne cvičenie","blocks":[{"math":"\\begin{aligned}\n\\text{1.}\\;&2x^2+3x-5-3x^2-x+2\\\\[4pt]\n\\text{2.}\\;&7n+3m+2+3n^2+4\\\\[4pt]\n\\text{3.}\\;&2a-\\left[b-(5a+2b-c)+(2a+b-3c)\\right]\\\\[4pt]\n\\text{4.}\\;&-R^2S+15RS^2-\\left(-5R^2S^2-R^2S-8RS+18RS^2\\right)\\\\[4pt]\n\\text{5.}\\;&(-2ax)(-3ax)(-xY^2)\\\\[4pt]\n\\text{6.}\\;&4xY(2x+3Y)\\\\[4pt]\n\\text{7.}\\;&(2xY+Y^2)(x^2-2xY)\\\\[4pt]\n\\text{8.}\\;&(x^2+x+1)(x^2+x+2)\\\\[4pt]\n\\text{9.}\\;&(2x-3)(x+4)(x^2-x+2)\\\\[4pt]\n\\text{10.}\\;&\\frac{-2xYz^2}{10x^2z}\\\\[4pt]\n\\text{11.}\\;&\\frac{-8x^6y^4z^7}{(2x^3)(4ub^4z^7)}\\\\[4pt]\n\\text{12.}\\;&\\frac{(-2x^2Yz)^2}{\\left(\\frac{x^2}{y^2}\\right)^2}\\\\[4pt]\n\\text{13.}\\;&\\frac{\\sqrt{x}\\sqrt[4]{y}}{\\sqrt{x^3}\\sqrt[5]{y}}\\\\[4pt]\n\\text{14.}\\;&\\frac{\\sqrt{a^9\\sqrt{b^{-3}}}}{\\sqrt[5]{b^3\\sqrt{a^3}}}\\\\[4pt]\n\\text{15.}\\;&\\frac{2(x-1)}3-\\frac{x+5}2=\\frac{x-7}6\\\\[4pt]\n\\text{16.}\\;&3(2x-1)-4=2(x+5)\\\\[4pt]\n\\text{17.}\\;&3(x-2)+5=2x+7\\\\[4pt]\n\\text{18.}\\;&3(x-2)+5=3x-1\\\\[4pt]\n\\text{19.}\\;&3(x-2)+5=3x+4\\\\[4pt]\n\\text{20.}\\;&4(x-2)+\\frac{x+1}{x-3}=9\\\\[4pt]\n\\text{21.}\\;&\n\\begin{gathered}\n5x-7=0,\\qquad x^2+4x+1=0,\\\\\n\\frac1{x-2}=3,\\qquad \\sqrt{x}=x-2\n\\end{gathered}\\\\[4pt]\n\\text{22.}\\;&3x^2-5x+2\\\\[4pt]\n\\text{23.}\\;&8x^2-3x+4-5x^2+7x-9\\\\[4pt]\n\\text{24.}\\;&4a-\\left[2a-(3a-b)+2b\\right]\\\\[4pt]\n\\text{25.}\\;&12x^3y-8x^2y^2\\\\[4pt]\n\\text{26.}\\;&(x-2)(x+1)(x+3)\\\\[4pt]\n\\text{27.}\\;&(2x+1)(x-2)(x^2+3)\\\\[4pt]\n\\text{28.}\\;&(a-b)(a+b)(a^2+b^2)\\\\[4pt]\n\\text{29.}\\;&(x+1)(x+2)(x+3)=(x^2+3x+2)x+3\\\\[4pt]\n\\text{30.}\\;&(-3a^2b)(4ab^3)\\\\[4pt]\n\\text{31.}\\;&5x(2x^2-3x+4)\\\\[4pt]\n\\text{32.}\\;&(x-4)(2x+3)\\\\[4pt]\n\\text{33.}\\;&(3x-2)^2\\\\[4pt]\n\\text{34.}\\;&\\frac{18x^5y^3}{6x^2y}\\\\[4pt]\n\\text{35.}\\;&\\frac{x^{3/2}}{x^{1/2}}\\\\[4pt]\n\\text{36.}\\;&a^{-3}b^2\\\\[4pt]\n\\text{37.}\\;&\\sqrt[3]{x^6}\\\\[4pt]\n\\text{38.}\\;&\\frac{\\sqrt{x+2}}{x^2-9}=1\\\\[4pt]\n\\text{39.}\\;&(x-4)(x+1)=0\\\\[4pt]\n\\text{40.}\\;&4(2x-1)-3x=5x-4\\\\[4pt]\n\\text{41.}\\;&3(x-2)+7=3x+1\\\\[4pt]\n\\text{42.}\\;&\\frac{x^2-4}{x-2}=0\\\\[4pt]\n\\text{43.}\\;&\\sqrt{x+6}=x\\\\[4pt]\n\\text{44.}\\;&(a-1)x=2,\\qquad a\\in\\mathbb R\\\\[4pt]\n\\text{45.}\\;&5-2x^3+x=4x^2-7\\\\[4pt]\n\\text{46.}\\;&5x-7=18\\\\[4pt]\n\\text{47.}\\;&4(2x-3)=3x+13\\\\[4pt]\n\\text{48.}\\;&2x+3=2x+3,\\qquad 2x+3=2x+5\\\\[4pt]\n\\text{49.}\\;&\\frac{2x}{x-1}=4\\\\[4pt]\n\\text{50.}\\;&|x+2|=7\\\\[4pt]\n\\text{51.}\\;&\\sqrt{2x+3}=x\\\\[4pt]\n\\text{52.}\\;&x^4-13x^2+36=0\\\\[4pt]\n\\text{53.}\\;&x^2+x-6=0\\\\[4pt]\n\\text{54.}\\;&(2x-1)^2=25\\\\[4pt]\n\\text{55.}\\;&x^2+4x-5\\\\[4pt]\n\\text{56.}\\;&f(x)=2(x+1)^2-8\\\\[4pt]\n\\text{57.}\\;&5x-10\\le0\\\\[4pt]\n\\text{58.}\\;&-2x+7>3\\\\[4pt]\n\\text{59.}\\;&(x-5)(x+2)>0\\\\[4pt]\n\\text{60.}\\;&x^2+2x-3>0\\\\[4pt]\n\\text{61.}\\;&-x^2+4x-3\\ge0\\\\[4pt]\n\\text{62.}\\;&\\frac{x-2}{x+1}<0\n\\end{aligned}"},{"math":"\\begin{aligned}\n\\text{1.}\\;&-x^2+2x-3\\\\[4pt]\n\\text{2.}\\;&3n^2+7n+3m+6\\\\[4pt]\n\\text{3.}\\;&5a+2c\\\\[4pt]\n\\text{4.}\\;&5R^2S^2-3RS^2+8RS=RS(5RS-3S+8)\\\\[4pt]\n\\text{5.}\\;&-6a^2x^3Y^2\\\\[4pt]\n\\text{6.}\\;&8x^2Y+12xY^2\\\\[4pt]\n\\text{7.}\\;&2x^3Y-3x^2Y^2-2xY^3\\\\[4pt]\n\\text{8.}\\;&x^4+2x^3+4x^2+3x+2\\\\[4pt]\n\\text{9.}\\;&2x^4+3x^3-13x^2+22x-24\\\\[4pt]\n\\text{10.}\\;&-\\frac{Yz}{5x},\\qquad x\\ne0,\\quad z\\ne0\\\\[4pt]\n\\text{11.}\\;&-\\frac{x^3y^4}{ub^4},\\qquad x\\ne0,\\quad u\\ne0,\\quad b\\ne0,\\quad z\\ne0\\\\[4pt]\n\\text{12.}\\;&4y^4Y^2z^2,\\qquad x\\ne0,\\quad y\\ne0\\\\[4pt]\n\\text{13.}\\;&\\frac{\\sqrt[20]{y}}{x},\\qquad x>0,\\quad y>0\\\\[4pt]\n\\text{14.}\\;&\\frac{a^{21/5}}{b^{27/20}},\\qquad a>0,\\quad b>0\\\\[4pt]\n\\text{15.}\\;&U=\\mathbb R,\\qquad S=\\varnothing\\\\[4pt]\n\\text{16.}\\;&U=\\mathbb R,\\qquad S=\\left\\{\\frac{17}{4}\\right\\}\\\\[4pt]\n\\text{17.}\\;&U=\\mathbb R,\\qquad S=\\{8\\}\\\\[4pt]\n\\text{18.}\\;&U=\\mathbb R,\\qquad S=\\mathbb R\\\\[4pt]\n\\text{19.}\\;&U=\\mathbb R,\\qquad S=\\varnothing\\\\[4pt]\n\\text{20.}\\;&\n\\begin{gathered}\nL=4(x-2)+\\frac{x+1}{x-3},\\qquad R=9,\\\\\n\\text{členy ľavej strany: }4(x-2),\\ \\frac{x+1}{x-3},\\\\\n\\text{čitateľ: }x+1,\\qquad \\text{menovateľ: }x-3,\\qquad P:x\\ne3\n\\end{gathered}\\\\[4pt]\n\\text{21.}\\;&\n\\begin{gathered}\n5x-7=0:\\ \\text{lineárna},\\\\\nx^2+4x+1=0:\\ \\text{kvadratická},\\\\\n\\frac1{x-2}=3:\\ \\text{racionálna},\\quad x\\ne2,\\\\\n\\sqrt{x}=x-2:\\ \\text{iracionálna},\\quad x\\ge0\n\\end{gathered}\\\\[4pt]\n\\text{22.}\\;&3x^2-5x+2:\\ \\text{výraz}\\\\[4pt]\n\\text{23.}\\;&3x^2+4x-5\\\\[4pt]\n\\text{24.}\\;&5a-3b\\\\[4pt]\n\\text{25.}\\;&4x^2y(3x-2y)\\\\[4pt]\n\\text{26.}\\;&x^3+2x^2-5x-6\\\\[4pt]\n\\text{27.}\\;&2x^4-3x^3+4x^2-9x-6\\\\[4pt]\n\\text{28.}\\;&a^4-b^4\\\\[4pt]\n\\text{29.}\\;&\n\\begin{gathered}\n(x^2+3x+2)x+3\\ne(x^2+3x+2)(x+3),\\\\\n(x+1)(x+2)(x+3)=x^3+6x^2+11x+6\n\\end{gathered}\\\\[4pt]\n\\text{30.}\\;&-12a^3b^4\\\\[4pt]\n\\text{31.}\\;&10x^3-15x^2+20x\\\\[4pt]\n\\text{32.}\\;&2x^2-5x-12\\\\[4pt]\n\\text{33.}\\;&9x^2-12x+4\\\\[4pt]\n\\text{34.}\\;&3x^3y^2,\\qquad x\\ne0,\\quad y\\ne0\\\\[4pt]\n\\text{35.}\\;&x,\\qquad x>0\\\\[4pt]\n\\text{36.}\\;&\\frac{b^2}{a^3},\\qquad a\\ne0\\\\[4pt]\n\\text{37.}\\;&x^2,\\qquad x\\in\\mathbb R\\\\[4pt]\n\\text{38.}\\;&\n\\begin{gathered}\nP:x\\ge-2,\\quad x\\ne-3,\\quad x\\ne3,\\\\\nD=[-2,3)\\cup(3,\\infty)\n\\end{gathered}\\\\[4pt]\n\\text{39.}\\;&\n\\begin{gathered}\n(x-4)(x+1)=0\\Longleftrightarrow x=4\\lor x=-1,\\\\\nS=\\{-1,4\\},\\qquad x-4=0\\text{ pre }x=4\n\\end{gathered}\\\\[4pt]\n\\text{40.}\\;&U=\\mathbb R,\\qquad S=\\mathbb R\\\\[4pt]\n\\text{41.}\\;&U=\\mathbb R,\\qquad S=\\mathbb R\\\\[4pt]\n\\text{42.}\\;&P:x\\ne2,\\qquad S=\\{-2\\}\\\\[4pt]\n\\text{43.}\\;&\n\\begin{gathered}\nD=[-6,\\infty),\\qquad P:x\\ge0,\\\\\nx\\in\\{-2,3\\},\\qquad x_{\\mathrm{nepravý}}=-2,\\qquad S=\\{3\\}\n\\end{gathered}\\\\[4pt]\n\\text{44.}\\;&\n\\begin{cases}\na\\ne1:&S=\\left\\{\\dfrac{2}{a-1}\\right\\},\\\\\na=1:&S=\\varnothing\n\\end{cases}\\\\[4pt]\n\\text{45.}\\;&2x^3+4x^2-x-12=0\\\\[4pt]\n\\text{46.}\\;&U=\\mathbb R,\\qquad S=\\{5\\}\\\\[4pt]\n\\text{47.}\\;&U=\\mathbb R,\\qquad S=\\{5\\}\\\\[4pt]\n\\text{48.}\\;&\n\\begin{gathered}\n2x+3=2x+3:\\ S=\\mathbb R,\\\\\n2x+3=2x+5:\\ S=\\varnothing\n\\end{gathered}\\\\[4pt]\n\\text{49.}\\;&P:x\\ne1,\\qquad S=\\{2\\}\\\\[4pt]\n\\text{50.}\\;&S=\\{-9,5\\}\\\\[4pt]\n\\text{51.}\\;&\n\\begin{gathered}\nD=\\left[-\\frac32,\\infty\\right),\\qquad P:x\\ge0,\\\\\nx\\in\\{-1,3\\},\\qquad x_{\\mathrm{nepravý}}=-1,\\qquad S=\\{3\\}\n\\end{gathered}\\\\[4pt]\n\\text{52.}\\;&\n\\begin{gathered}\nt=x^2,\\qquad t\\ge0,\\qquad (t-4)(t-9)=0,\\\\\nS=\\{-3,-2,2,3\\}\n\\end{gathered}\\\\[4pt]\n\\text{53.}\\;&(x+3)(x-2)=0,\\qquad S=\\{-3,2\\}\\\\[4pt]\n\\text{54.}\\;&2x-1=\\pm5,\\qquad S=\\{-2,3\\}\\\\[4pt]\n\\text{55.}\\;&x^2+4x-5=(x+2)^2-9\\\\[4pt]\n\\text{56.}\\;&V=(-1,-8),\\qquad D(f)=\\mathbb R,\\qquad H(f)=[-8,\\infty)\\\\[4pt]\n\\text{57.}\\;&S=(-\\infty,2]\\\\[4pt]\n\\text{58.}\\;&S=(-\\infty,2)\\\\[4pt]\n\\text{59.}\\;&S=(-\\infty,-2)\\cup(5,\\infty)\\\\[4pt]\n\\text{60.}\\;&S=(-\\infty,-3)\\cup(1,\\infty)\\\\[4pt]\n\\text{61.}\\;&S=[1,3]\\\\[4pt]\n\\text{62.}\\;&P:x\\ne-1,\\qquad S=(-1,2)\n\\end{aligned}"}]}],"description":"Číselné množiny, algebraické výrazy, rovnice, nerovnice a bezpečné úpravy.","icon":"π"},{"id":"kurz-derivacie-doucko-2","title":"Derivácie krok za krokom","lessons":[{"id":"derivacie-01-funkcia-a-zmena-2","title":"1. Funkcia a derivácia ako opis zmeny","blocks":[{"h2":"Derivácia: Odkiaľ sa táto myšlienka vzala"},{"p":"Predstav si Anglicko v roku 1665. Ulice Cambridge stíchli, univerzita sa pre mor zatvorila a mladý Isaac Newton sa vrátil na rodinný statok vo Woolsthorpe. Na stole má náčrty kriviek, na dvore sleduje tiene a v hlave mu zostáva jedna zdanlivo jednoduchá otázka. Predstav si kameň padajúci z vysokej veže. Počas prvej sekundy prejde určitú vzdialenosť, počas nasledujúcej ešte väčšiu, pretože neustále zrýchľuje. Ako rýchlo sa však pohybuje presne v jednom okamihu? Vydeliť celkovú vzdialenosť časom nestačí, pretože dostaneme iba priemer za celé obdobie. Ak však skúmaný čas skrátime až na jediný okamih, nemáme čím deliť. Znamená to, že okamžitá rýchlosť v skutočnosti neexistuje, alebo nám iba chýba spôsob, ako ju vypočítať? Newton preto začne skúmať, k akej hodnote sa priemerné rýchlosti približujú, keď meraný čas skracuje. Tak sa rodí jeho predstava plynúcich veličín a ich okamžitých zmien, ktoré nazýva fluxie."},{"p":"O niekoľko rokov neskôr pracuje nezávisle Gottfried Wilhelm Leibniz. Kým Newton premýšľa najmä o pohybe, Leibniz vytvára presný jazyk zmien so symbolmi dx, dy a znakom integrálu. Newton prišiel k svojim základným myšlienkam skôr, no dlho ich nezverejnil. Leibniz svoj postup publikoval v roku 1684, a tak sa jeho zrozumiteľný zápis začal rýchlo šíriť medzi európskymi matematikmi. Dvaja myslitelia zatiaľ netušia, že ich spoločný objav čoskoro rozpúta jednu z najostrejších vojen v dejinách matematiky."},{"p":"Iskra preskočí v roku 1699, keď Newtonovi stúpenci naznačia, že Leibniz svoje myšlienky neobjavil sám, ale prevzal ich z Newtonových starších listov. Leibniz sa bráni: Newtonove úplné postupy nikdy nevidel a k diferenciálnemu počtu dospel vlastnou cestou. Spor sa mení na súboj národnej cti. Angličania stoja za Newtonom, učenci na európskom kontinente za Leibnizom. Listy sa plnia obvineniami, vedecké časopisy útokmi a otázka, ako opisovať pohyb a zmenu, ustupuje oveľa osobnejšej otázke: Kto ukradol slávu komu?"},{"p":"Leibniz napokon požiada Kráľovskú spoločnosť, aby spor nestranne vyšetrila. Netuší však, že jej predsedom je samotný Newton. Správa vydaná v roku 1712 prisúdi prvenstvo Newtonovi, pričom Newton vyberie členov vyšetrovacieho výboru a výrazne ovplyvní aj jeho závery. Leibniz zomiera v roku 1716 so zatienenou povesťou, no dejiny napokon vynesú spravodlivejší rozsudok: obaja vytvorili základy matematickej analýzy nezávisle. Newton ukázal, ako chápať meniaci sa svet, Leibniz mu dal jazyk, ktorým o ňom dodnes hovoríme."},{"h2":"Najprv musíme vedieť, čo je funkcia"},{"p":["Na vodorovnej osi máme premennú. Zvyčajne ju voláme ",{"math":"x"},", ale vo fyzike to môže byť napríklad čas ",{"math":"t"},". Dosádzame do nej hodnoty. Zvislá os je funkčná os: ukazuje výsledok, ktorý pre daný vstup vypočíta funkcia."]},{"p":["Napríklad predpis ",{"math":"f(x)=x+1"}," znamená: vezmite vstup, pripočítajte jednotku a výsledok položte na zvislú os. Pre ",{"math":"x=0"}," dostaneme ",{"math":"f(0)=1"},", pre ",{"math":"x=1"}," dostaneme ",{"math":"f(1)=2"},". Tak vzniká priamka."]},{"p":"Funkcia však nemusí byť priamka. Môže to byť parabola, kubická funkcia, hyperbola, logaritmus, exponenciála alebo kombinácia viacerých funkcií. Každá z nich môže opisovať nejaký dej: teplotu počas dňa, dráhu auta, výmenu tepla alebo rast počtu baktérií."},{"h2":"Čo na grafe hľadáme"},{"p":"Predstavte si dennú teplotu. V noci klesá, ráno dosiahne najnižšiu hodnotu, cez deň stúpa, popoludní dosiahne najvyššiu hodnotu a potom zase klesá. Na grafe teda nehľadáme iba konkrétne číslo. Hľadáme úseky, kde funkcia stúpa alebo klesá, a miesta, kde sa jej správanie mení."},{"p":["Keď schádzate dolu kopcom a dostanete sa na úplné dno, na okamih už nejdete nižšie, ale ešte ste nezačali stúpať. Také miesto voláme ",{"b":"stacionárny bod"},". Ak je to dno doliny, ide o lokálne minimum. Ak ide o vrchol, po ktorom funkcia začne klesať, ide o lokálne maximum. Nie každý stacionárny bod však musí byť maximom alebo minimom."]},{"p":"V stacionárnom bode, v ktorom derivácia existuje, je jej hodnota nulová. To neznamená, že hodnota funkcie je nula; znamená to, že graf má vodorovnú dotyčnicu. Samotná nulová derivácia ešte nerozhoduje, či ide o maximum, minimum alebo napríklad stacionárny inflexný bod."},{"h2":"Miesto, kde sa funkcia preruší"},{"p":["Pozrime sa na funkciu ",{"math":"r(x)=\\frac{x+2}{x-6}"},". Skúste dosadiť ",{"math":"x=6"},". V čitateli dostaneme 8, ale v menovateli 0. Delenie nulou je zakázaná matematická operácia, takže v tomto bode nevieme funkcii priradiť hodnotu."]},{"p":["Pre túto funkciu graf tesne pred šestkou klesá k veľmi veľkým záporným hodnotám a tesne za šestkou prichádza z veľmi veľkých kladných hodnôt. V samotnom bode ",{"math":"x=6"}," však hodnota chýba. Funkciu tam musíme prerušiť. Je to bod nespojitosti."]},{"p":"Prečo to spomíname pred derivovaním? Pretože derivácia je nástroj, ktorým sa pozeráme dovnútra funkcie. Pomáha nám opísať jej rast, pokles, stacionárne body a ďalšie vlastnosti. Najprv teda musíme vidieť funkciu ako dej, nie iba ako rad symbolov."},{"h2":"Grafický experiment: denná teplota a jej zmena"},{"p":"Modrý graf predstavuje zjednodušenú teplotu počas dňa. Červený graf je jej derivácia. Posúvajte čas a sledujte naraz výšku modrého bodu aj hodnotu červeného bodu. Pýtajte sa: rastie teplota, klesá, alebo sa práve na okamih zastavila?"},{"graph":{"title":"Teplota počas dňa a jej derivácia","bounds":[0,24,-6,30],"commands":["t=8","f(x)=18+6*sin(pi*(x-8)/12)","g(x)=Derivative(f)","A=(t,f(t))","B=(t,g(t))"],"controls":[["t",0,24,0.25,8]],"tasks":[{"text":"Dokážete nájsť čas, keď je teplota na lokálnom minime? Sledujte, či sa modrý graf prestáva znižovať a či je červená hodnota zmeny takmer nulová.","condition":"t>1.8 && t<2.2 && abs(g(t))<0.05"},{"text":"Kedy sa teplota počas tohto modelového dňa dostane na lokálne maximum? Overte vrchol modrého grafu aj takmer nulovú hodnotu derivácie.","condition":"t>13.8 && t<14.2 && abs(g(t))<0.05"},{"text":"Nájdite čas, keď teplota rastie najrýchlejšie. Sledujte, že modrý graf ešte nie je na maxime, ale červený graf má vysokú kladnú hodnotu.","condition":"t>7.8 && t<8.2 && g(t)>1.5"}],"expected":["t","f","g","A","B"],"colors":{"f":[29,78,216],"g":[220,38,38],"A":[22,163,74],"B":[147,51,234]}}},{"h2":"Stručná sumarizácia"},{"p":"Funkcia priraďuje vstupu výsledok a jej graf môže opisovať reálny dej. Derivácia hovorí, ako sa funkcia mení. Na intervale, kde je derivácia kladná, funkcia rastie; kde je záporná, funkcia klesá. Nulová derivácia označuje stacionárny bod, ale sama osebe ešte neurčuje jeho typ. Pred počítaním je preto užitočné premyslieť si, čo sa na grafe deje."},{"test":"# Funkcia, zmena a stacionárny bod\n\n[ABCD]\nČo opisuje derivácia funkcie?\n- Iba hodnotu funkcie v bode x=0.\n* Spôsob, akým sa funkcia mení.\n- Miesto, kde graf pretína os y.\n- Iba definičný obor funkcie.\n\n[DROPDOWN]\nBod, v ktorom funkcia prestane klesať a začne stúpať, môže byť lokálne {{výber}}.\n- maximum\n* minimum\n- asymptota\n- nespojitosť\n\n[ABCD]\nPrečo funkcia (x+2)/(x-6) nemá hodnotu pri x=6?\n- Pretože čitateľ je kladný.\n- Pretože výsledok musí byť záporný.\n* Pretože by sme delili nulou.\n- Pretože x nesmie byť celé číslo.\n\n[ODPOVEĎ]\nAk je graf v hladkom stacionárnom bode vodorovný, akú hodnotu tam má derivácia?\n= 0 | nula"}]},{"id":"derivacie-02-zmena-na-prikladoch-2","title":"2. Derivácia ako zmena: konštanta, priamka a logaritmus","blocks":[{"h2":"Najjednoduchšia funkcia: stále číslo 3"},{"p":["Môže byť samotné číslo 3 funkciou? Áno. Je to konštantná funkcia, ktorá pre každý vstup vráti tú istú hodnotu. Zapisujeme ju ako ",{"math":"f(x)=3"},". Pre ľubovoľné dva vstupy ",{"math":"x_1,x_2"}," platí, že f(x_1)=f(x_2)=3, takže výstup sa nemení."]},{"p":["Dosadíme ",{"math":"x=1"}," a výsledok je 3. Dosadíme ",{"math":"x=2"}," a výsledok je znovu 3. Na vstupe sme spravili krok o jednotku, ale výstup sa zmenil o nulu. Graf je vodorovná priamka."]},{"p":"Aký je rozdiel medzi dvomi bodmi v tejto funkcii? Napríklad porovnaj body x1 (4) a x2 (5) aký bude ich rozdiel vo funkcii f(x)=3?"},{"math":"(3)'=0"},{"p":["Konštantná funkcia sa nemení, preto je jej derivácia v každom bode je nula. \nNula tu je to presná informácia o grafe: nech sa na osi ",{"math":"x"}," pohneme akokoľvek, výška zostáva rovnaká."]},{"h2":"Lineárna funkcia: vstup o jeden, výstup o jeden"},{"p":["Teraz vezmime ",{"math":"f(x)=x+1"},". Pre ",{"math":"x=0"}," dostaneme 1, pre ",{"math":"x=1"}," dostaneme 2 a pre ",{"math":"x=2"}," dostaneme 3. ",{"b":"Vždy, keď vstup zväčšíme o jednotku, výstup sa zväčší tiež o jednotku."}]},{"math":"(x+1)'=1+0=1"},{"p":["Člen ",{"math":"x"}," má jednotkovú zmenu, preto ",{"math":"(x)'=1"},". Samostatná konštanta 1 sa nemení, preto sa zderivuje na nulu. Výsledkom je konštanta 1: priamka má na každom mieste rovnaký sklon."]},{"h2":"Pozor: derivácia nemusí byť iba číslo"},{"p":["Pri prvých dvoch príkladoch vyšla derivácia 0 alebo 1. To môže vytvoriť nesprávny dojem, že derivácia je vždy jedno číslo. Nie je. Keď sa sklon pôvodného grafu mení z miesta na miesto, výsledkom derivovania je nová funkcia. Čiže ",{"b":"derivácia neplatí iba na vybraný  bod v grafe ale platí na úplne celú funkciu."}]},{"h2":"Logaritmus: stále rastie, ale čoraz menej"},{"p":["Pozrime sa na ",{"math":"f(x)=\\ln x"},". Do tejto funkcie môžeme dosádzať iba kladné hodnoty. Blízko nuly rastie graf veľmi prudko. Medzi väčšími hodnotami stále rastie, ale každý ďalší rovnaký krok vytvorí menší prírastok."]},{"p":["Porovnajte jednotkové kroky. Z ",{"math":"x=1"}," do ",{"math":"x=2"}," graf narastie citeľne. Z 2 do 3 narastie menej. Z 4 do 5 ešte menej. ",{"b":"Derivácia musí túto povahu zachytiť pre každý bod"},": pri malých kladných ",{"math":"x"}," má byť veľká a pri veľkých ",{"math":"x"}," sa má približovať k nule."]},{"math":"(\\ln x)'=\\frac{1}{x}"},{"p":["Funkcia ",{"math":"\\frac{1}{x}"}," určuje sklon dotyčnice ku grafu logaritmu. Pri ",{"math":"x=1"}," má derivácia hodnotu 1, pri ",{"math":"x=2"}," je ",{"math":"\\frac12"}," a pri ",{"math":"x=10"}," iba ",{"math":"\\frac1{10}"},". Logaritmus teda stále rastie, ale jeho sklon sa s rastúcim vstupom zmenšuje."]},{"graph":{"title":"Logaritmus rastie, ale jeho zmena klesá","bounds":[0,10,-3,11],"commands":["a=1","f(x)=ln(x)","g(x) = Derivative(f)","A=(a,f(a))","B=(a,g(a))","T=Tangent(A,f)","Text(\"Derivácia\", (0.3,5))"],"controls":[["a",0.1,9,0.1,1]],"tasks":[{"text":"Nájdite miesto, kde má logaritmus okamžitú zmenu približne 1. Sledujte súčasne sklon dotyčnice aj výšku červeného bodu.","condition":"a>0.95 && a<1.05"},{"text":"Dokážete nájsť miesto, kde logaritmus stále rastie, ale jeho okamžitá zmena je už menšia než 0,2? Sledujte sploštenie modrého grafu a kladnú polohu červeného bodu.","condition":"a>5"},{"text":"Priblížte sa ku kladnej nule bez toho, aby ste ju dosiahli. Čo sa deje so strmosťou logaritmu a s hodnotou jeho derivácie? Nájdite stav s veľmi prudkým rastom.","condition":"a<0.25"}]}},{"h2":"Stručná sumarizácia"},{"p":["Pri derivácii porovnávame zmenu vstupu so zmenou výstupu. Konštanta má deriváciu 0, priamka ",{"math":"x+1"}," má deriváciu 1 a logaritmus má deriváciu ",{"math":"\\frac1x"},". Najdôležitejšia myšlienka: derivácia môže byť nová funkcia, ktorá na každom mieste rozpráva, ako sa pôvodná funkcia práve mení."]},{"test":"# Derivácia ako zmena\n\n[ABCD]\nPrečo je derivácia konštantnej funkcie f(x)=3 rovná nule?\n- Pretože číslo 3 je nepovolené.\n- Pretože x musí byť záporné.\n* Pretože pri zmene vstupu sa výstup vôbec nezmení.\n- Pretože 3 delené x je nula.\n\n[DROPDOWN]\nPri funkcii f(x)=x+2 sa pri zvýšení vstupu o 1 zvýši výstup o {{výber}}.\n- 0\n* 1\n- 2\n- x\n\n[ABCD]\nKtoré tvrdenie o funkcii ln(x) je správne?\n- Klesá a jej derivácia je záporná.\n- Je definovaná aj pre x=0.\n* Rastie, ale pre väčšie x rastie čoraz pomalšie.\n- Má v každom bode rovnaký sklon.\n\n[ODPOVEĎ]\nAká je derivácia funkcie ln(x) pri x=2?\n= 1/2 | 0,5 | 0.5"}]},{"id":"derivacie-03-mocniny-a-konstanty-2","title":"3. Mocniny a polynómy: exponent a konštanty","blocks":[{"p":"Teraz už vieme, čo derivácia znamená. Pri výpočte najprv určíme typ člena, vyberieme správne pravidlo a rozlíšime samostatnú konštantu od konštantného koeficientu pri premennej.","role":"hook"},{"p":["Graf znázorňuje funkciu ",{"math":"f(x) = ax^b + cx^2 + k"}," a zobrazuje deriváciu tejto funkcie. Skúste objaviť riešenie úloh a testu ešte pred vysvetlením."]},{"graph":{"title":"Derivácia polynómu","commands":["a = 0","b = 0","c = 0","k = 0","i = 0","j = 0","f(x) = ax^b + cx^2 + k","Text(ax^b + cx^2 + k,(1, f(1)))","g(x) = Derivative(f)","Text(\"f(x)'\",(-0.5, g(-0.5)))","h(x) = ix^j","Text(ix^j,(0.5, h(0.5)))"],"controls":[["a",-3,6,0.5,2],["b",-3,6,1,6],["c",-5,5,0.5,0],["i",-6,10,1,0],["j",-6,10,1,0],["k",-5,5,0.1,0]],"tasks":[{"text":"Nastav parametre a,b,c,k vo funkcii f(x) = ax^b + cx^2 + k tak aby si získal f(x) = 2x^3","condition":"a==2&&b==3&&c==0&&k==0"},{"text":"Nastav parametre pomocnej funkcie h(x) = ix^j tak aby sa rovnal derivácii funkcie f(x) = 2x^3","condition":"i==6&&j==2"},{"text":"Nastav funkciu f(x) = ax^b + cx^2 + k tak aby sa rovnala funkcii f(x)=1/x.","condition":"a==1&&b==-1&&c==0&&k==0"},{"text":"Nastav parametre pomocnej funkcie h(x) = ix^j tak aby sa rovnal derivácii funkcie f(x) = 2x^-3","condition":"i==-6&&j==-4"}],"preserveStyle":false}},{"test":"# Test\n\n[DROPDOWN]\nDoplňte správnu možnosť: Výraz 1/x môžeme pre x ≠ 0 zapísať ako {{výber}}.\n* x^(-1)\n- -x\n- x\n- x^(1/2)\n\n[ABCD]\nKtorý výraz je ekvivalentný výrazu 2x^(-3), ak x ≠ 0?\n* 2/x^3\n- 2/x^(-3)\n- -2/x^3\n- 1/(2x^3)\n\n[ABCD]\nKtorá z nasledujúcich funkcií je polynóm?\n* f(x)=3x^4-2x^2+5x-7\n- f(x)=1/x+2\n- f(x)=3x^(-4)-2x^2+5x-7\n- f(x)=x^(1/2)+1\n\n[DROPDOWN]\nFunkcia f(x)=4x^5-5x^2+7 je polynóm {{výber}} stupňa.\n* piateho\n- štvrtého\n- druhého\n- siedmeho\n\n[DROPDOWN]\nMocninové pravidlo pre (x^n)'x má tvar={{výber}}.\n* n·x^(n-1)\n- x^(n-1)\n- n·x^n\n- (-n)·x^n\n\n\n[ODPOVEĎ]\nVypočítajte deriváciu funkcie f(x)=1/x a výsledok zapíšte ako zlomok.\n= -1/x^2 | -1/(x^2)\n\n[ABCD]\nAk f(x)=2x^3, ktorá funkcia sa rovná f'(x)?\n* 6x^2\n- 2x^3\n- 3x^2\n- 6x^3\n\n[ABCD]\nAk f(x)=2x^(-3), ktorá funkcia sa rovná derivácii f'(x)?\n* -6x^(-4)\n- 6x^(-2)\n- -3x^(-4)\n- 2x^(-4)\n\n[ABCD]\nAký vplyv má samostatná konštanta k vo funkcii (x)=ax^b+cx^2+k na jej deriváciu?\n* Nemá žiadny vplyv, pretože derivácia konštanty je 0.\n- V derivácii sa nahradí číslom 1.\n- V derivácii zostane bez zmeny.\n- Všetky členy derivácie sa vynásobia konštantou k.\n\n[ODPOVEĎ]\nVypočítajte deriváciu funkcie f(x)=3x^4+2x^2+7.\n= 12x^3+4x | 12*x^3+4*x"},{"h2":"Mocninové pravidlo: exponent zhodíme a znížime"},{"p":"Pre mocninovú funkciu používame v bodoch, kde je daný výraz definovaný, pravidlo"},{"math":"(x^a)'=a x^{a-1}"},{"p":["Pracovný postup je jednoduchý: číslo z exponentu ",{"b":"zhodíme dopredu"},", základ ",{"math":"x"}," opíšeme a exponent znížime o jeden."]},{"p":["Napríklad pri ",{"math":"x^3"}," zhodíme trojku dopredu, ",{"math":"x"}," opíšeme a z exponentu 3 spravíme ",{"math":"3-1=2"},". Kooeficient pred neznámou len opíšeme."]},{"math":"(2x^3)'=2*3x^{3-1}=2*3x^2=6x^2"},{"h2":"Celý príklad po jednotlivých členoch"},{"p":["Zderivujme funkciu ",{"math":"f(x)=x^3+6x-3"},". Pri sčítaní a odčítaní môžeme derivovať každý člen osobitne a znamienka zachováme."]},{"math":"\\begin{aligned}f'(x)&=(x^3)'+(6x)'-(3)'\\\\&=3x^2+6\\cdot1-0\\\\&=3x^2+6\\end{aligned}"},{"p":["Prvý člen sme riešili mocninovým pravidlom. Pri ",{"math":"6x"}," číslo 6 nezmizlo, pretože nie je samostatné: násobí premennú. Šestku opíšeme a zderivujeme ",{"math":"x"},". Keďže ",{"math":"(x)'=1"},", zostane 6."]},{"p":["Až posledný člen ",{"math":"-3"}," je čistá samostatná konštanta bez premennej. Preto sa zderivuje na nulu. Toto je jeden z najčastejších chytákov: ",{"b":"samostatnú konštantu nulujeme, koeficient pri funkcii opisujeme"},"."]},{"h2":"Prečo je derivácia x rovná 1 aj podľa mocninového pravidla"},{"p":["Výraz ",{"math":"x"}," môžeme zapísať ako ",{"math":"x^1"},". Jednotku zhodíme dopredu a exponent znížime:"]},{"math":"(x^1)'=1\\cdot x^{1-1}=x^0=1"},{"p":["Takže pravidlo ",{"math":"(x)'=1"}," je osobitný prípad mocninového pravidla, nie samostatné nesúvisiace pravidlo."]},{"h2":"Konštanta pred funkciou sa opisuje"},{"p":["Zoberme ",{"math":"g(x)=20x^4"},". Číslo 20 je konštantný násobok pri ",{"math":"x^4"},". Pri derivovaní ho preto opíšeme a derivujeme mocninovú časť."]},{"math":"(20x^4)'=20\\cdot4x^3=80x^3"},{"p":["Rovnaký princíp platí všeobecne: ak ",{"math":"c"}," je konštanta, potom ",{"math":"(c\\,f(x))'=c\\,f'(x)"},". Nulovanie konštanty sa používa iba vtedy, keď konštanta stojí ako samostatný sčítanec."]},{"h2":"Rýchly pracovný postup na polynóm"},{"p":[{"b":"1."}," Rozdeľte výraz podľa plusov a mínusov. ",{"b":"2."}," Pri každom člene si všimnite koeficient a exponent. ",{"b":"3."}," Koeficient opíšte. ",{"b":"4."}," Exponent zhoďte dopredu a znížte o jeden. ",{"b":"5."}," Samostatné číslo nahraďte nulou. ",{"b":"6."}," Výsledok upravte."]},{"h2":"Vedený príklad"},{"p":["Zderivujme ",{"math":"h(x)=-4x^5+\\frac12x^2+7x-9"},". Najprv nič nespájame. Každý člen vybavíme rovnakou logikou."]},{"math":"\\begin{aligned}h'(x)&=-4\\cdot5x^4+\\frac12\\cdot2x+7\\cdot1-0\\\\&=-20x^4+x+7\\end{aligned}"},{"p":["Skontrolujte si tri chytáky: mínus pri prvom člene zostal, zlomok ",{"math":"\\frac12"}," sa iba násobil dvojkou a posledná deviatka zmizla, lebo bola samostatná."]},{"h2":"Grafický experiment: koeficient, exponent a derivácia"},{"p":["V grafe je ",{"math":"f(x)=c x^n"}," a červený graf je jej derivácia. Posuvník ",{"math":"n"}," zahŕňa aj nulu a jednotku, aby ste videli hraničné prípady: konštantu a lineárnu funkciu."]},{"graph":{"title":"Čo robí mocninové pravidlo s grafom","bounds":[-4,4,-10,10],"commands":["c=1","n=2","a=1","f(x)=c*x^n","Text(c*x^n,(1,f(1)))","g(x)=Derivative(f)","Text(\"f'\",(-1,g(-1)))","A=(a,f(a))","B=(a,g(a))"],"controls":[["c",-3,3,0.5,1],["n",0,5,1,2],["a",-2,2,0.25,0]],"tasks":[{"text":"Vytvorte konštantnú funkciu, ktorá neleží na osi x. Sledujte, čo sa stane s celým červeným grafom derivácie a prečo sa výstup nemení.","condition":"abs(n)<0.001 && abs(c)>0.4 && abs(g(a))<0.001"},{"text":"Vytvorte lineárnu funkciu so záporným sklonom.","condition":"abs(n-1)<0.001 && c<0 && abs(g(a)-c)<0.001"}],"expected":["c","n","a","f","g","A","B"],"colors":{"f":[29,78,216],"g":[220,38,38],"A":[22,163,74],"B":[147,51,234]}}},{"h2":"Stručná sumarizácia"},{"p":["Pri mocnine zhodíme exponent dopredu a znížime ho o jeden. Pri súčte derivujeme člen po člene. Číslo pri premennej opisujeme, ale samostatnú konštantu nulujeme. Ak si nie ste istí pri ",{"math":"x"},", prepíšte ho ako ",{"math":"x^1"}," a použite rovnaké pravidlo."]},{"test":"# Mocninové pravidlo\n\n[ABCD]\nAká je derivácia x^5?\n- 5x^5\n* 5x^4\n- x^4\n- 4x^5\n\n[ABCD]\nAká je derivácia 6x?\n- 0\n- 1\n* 6\n- 6x\n\n[DROPDOWN]\nV príklade 3x²-7 sa samostatný člen -7 zderivuje na {{výber}}.\n* 0\n- -7\n- 1\n- 7x\n\n[ODPOVEĎ]\nZderivuj funkciu f(x)=4x³.\n= 12x^2 | 12x² | 12*x^2\n\n[ABCD]\nKtorý výsledok je správny pre f(x)=x³+6x-3?\n- 3x²+6x-3\n- 3x²+6x\n* 3x²+6\n- x²+6"}]},{"id":"derivacie-04-exponencialy-a-trigonometria-2","title":"4. Exponenciálne a goniometrické funkcie","blocks":[{"p":"Prehľad vzorcov pomáha iba vtedy, keď správne rozlíšime základ, exponent, argument funkcie a význam výslednej derivácie. Pri goniometrických deriváciách používame argumenty v radiánoch.","role":"hook"},{"h2":"Exponenciálna funkcia"},{"p":["Funkcia ",{"math":"a^x"}," má konštantný základ ",{"math":"a"}," a premennú v exponente. Preto si ju nemýľte s mocninou ",{"math":"x^a"},", kde je premenný základ a konštantný exponent. Pre reálnu exponenciálnu funkciu predpokladáme a>0; pri logaritme so základom a navyše a≠1."]},{"math":"(a^x)'=a^x\\ln a"},{"p":"Ak je pred funkciou konštanta, opíšeme ju. Napríklad"},{"math":"(8\\cdot7^x)'=8\\cdot7^x\\ln7"},{"p":["Osobitné miesto má Eulerovo číslo ",{"math":"e\\approx2{,}718"},". Pri prirodzenom logaritme platí ",{"math":"\\ln e=1"},", preto"]},{"math":"(e^x)'=e^x"},{"p":"Táto funkcia rastie tak, že jej okamžitá zmena má v každom bode rovnakú hodnotu ako samotná funkcia. Preto sa objavuje pri prírodnom raste, úročení, šírení a mnohých procesoch, ktoré sa zrýchľujú podľa vlastnej veľkosti."},{"graph":{"title":"Vlastný graf","bounds":[-3,5,-5,5],"commands":["a = 1","k = 1","f(x) = ka^x","Text(ka^x,(1,f(1)))","g(x) = Derivative(f)","Text(\"Derivacia\",(0.5,g(0.5)))"],"controls":[["a",-1,7,0.1,1],["k",-5,8,0.1,1]],"tasks":[{"text":"Kedy sa funkcia f(x) = ka^x (ak a>0) približne rovná jej vlastnej derivácii?","condition":"a>2.6 && a<2.8"}]}},{"h2":"Sínus a kosínus: kopec a rýchlosť"},{"math":"(\\sin x)'=\\cos x,\\qquad (\\cos x)'=-\\sin x"},{"p":["Predstavte si graf funkcie ",{"math":"y=sin(x)"},"ako profil kopca a vy sa pohybujete po jeho svahu. Derivácia nehovorí, ako vysoko sa nachádzate, ale ako rýchlo sa vaša výška mení pri malom posune dopredu."]},{"p":"Keď stúpate najstrmšie, výška rastie najrýchlejšie a derivácia dosahuje svoje najväčšie kladné hodnoty. Keď sa dostanete na vrchol alebo do údolia, svah je v danom okamihu vodorovný, takže derivácia je nulová. To neznamená, že sa výška prestala meniť navždy, ale iba to, že v tom konkrétnom bode nemáte sklon ani nahor, ani nadol a pohybujete sa akoby po rovine."},{"p":"Za vrcholom sa svah nakláňa nadol. Výška začína klesať, preto je derivácia záporná. V miestach najstrmšieho klesania dosahuje derivácia svoju najmenšiu hodnotu."},{"p":"Pri argumentoch meraných v radiánoch platí"},{"math":"(\\sin x)'=\\cos x,\\qquad (\\cos x)'=-\\sin x"},{"p":"Arkusfunkcie sú inverzné funkcie k príslušným goniometrickým funkciám. Pri arcsin a arccos uvedené derivačné vzorce platia pre |x|<1. Dôležité je správne rozlíšiť jednotlivé vzorce a ich znamienka."},{"h2":"Grafický experiment: sínus hovorí, kosínus vysvetľuje"},{"p":"Modrý graf je sínus a červený graf kosínus, teda jeho derivácia. Posúvajte bod a pozerajte sa na oba grafy naraz. Tak sa vzorec zmení na čitateľný príbeh o kopci."},{"graph":{"title":"Sínus, kosínus a okamžitá zmena","bounds":[-0.5,6.8,-1.5,1.5],"commands":["a = 0","b = 0","f(x) = sin(x+b*1.576)","g(x) = Derivative(f(x))","A = (a, f(a))","B = (a, g(a))","T = Tangent(A, f)","O = (0, 0)","k = Circle(O, 1)","P = (cos(a), sin(a))","r = Segment(O, P)","Text(sin(a) + \",\" + cos(a), P)"],"controls":[["a",0,6.28,0.01,0],["b",-5,5,0.1,0]],"tasks":[{"text":"Nájdite prvý vrchol sínusu. Sledujte, že modrý bod je vysoko, dotyčnica je takmer vodorovná a červená hodnota derivácie je blízko nuly.","condition":"a>1.52 && a<1.62 && abs(g(a))<0.06"},{"text":"Nájdite miesto po vrchole, kde sínus klesá najstrmšie. Sledujte prechod modrého grafu cez os a najnižšiu hodnotu červeného grafu.","condition":"a>3.09 && a<3.19 && g(a)<-0.99"},{"text":"Nájdite minimum sínusu. Overte, že napriek najnižšej hodnote modrého grafu je okamžitá zmena znovu takmer nulová.","condition":"a>4.66 && a<4.76 && abs(g(a))<0.06"}],"expected":["a","f","g","A","B","T"],"colors":{"f":[29,78,216],"g":[220,38,38],"A":[22,163,74],"B":[147,51,234],"T":[245,158,11]}}},{"h2":"Prehľad základných derivačných vzorcov"},{"math":"\\begin{aligned} (c)' &= 0 & (x)' &= 1 & (x^a)' &= ax^{a-1} \\\\[3pt] \\left(\\frac{1}{x}\\right)' &= -\\frac{1}{x^2} & (\\sqrt{x})' &= \\frac{1}{2\\sqrt{x}} & (\\sqrt[n]{x})' &= \\frac{1}{n\\sqrt[n]{x^{n-1}}} \\\\[3pt] (a^x)' &= a^x\\ln a & (e^x)' &= e^x & (\\log_a x)' &= \\frac{1}{x\\ln a} \\\\[3pt] (\\ln x)' &= \\frac{1}{x} & (\\sin x)' &= \\cos x & (\\cos x)' &= -\\sin x \\\\[3pt] (\\tan x)' &= \\frac{1}{\\cos^2 x} & (\\cot x)' &= -\\frac{1}{\\sin^2 x} & (\\sec x)' &= \\sec x\\tan x \\\\[3pt] (\\csc x)' &= -\\csc x\\cot x & (\\arcsin x)' &= \\frac{1}{\\sqrt{1-x^2}} & (\\arccos x)' &= -\\frac{1}{\\sqrt{1-x^2}} \\\\[3pt] (\\arctan x)' &= \\frac{1}{1+x^2} & (\\operatorname{arccot} x)' &= -\\frac{1}{1+x^2} \\\\[6pt] (u+v)' &= u'+v' & (u-v)' &= u'-v' & (cu)' &= cu' \\\\[3pt] (uv)' &= u'v+uv' & \\left(\\frac{u}{v}\\right)' &= \\frac{u'v-uv'}{v^2} & (f(u))' &= f'(u)\\,u' \\\\[6pt] (u^a)' &= a\\,u^{a-1}u' & (a^u)' &= a^u\\ln(a)\\,u' & (e^u)' &= e^u u' \\\\[3pt] (\\ln u)' &= \\frac{u'}{u} & (\\log_a u)' &= \\frac{u'}{u\\ln a} & (\\sqrt{u})' &= \\frac{u'}{2\\sqrt{u}} \\\\[3pt] (\\sin u)' &= \\cos(u)\\,u' & (\\cos u)' &= -\\sin(u)\\,u' & (\\tan u)' &= \\frac{u'}{\\cos^2 u} \\\\[3pt] (\\cot u)' &= -\\frac{u'}{\\sin^2 u} & (\\arcsin u)' &= \\frac{u'}{\\sqrt{1-u^2}} & (\\arccos u)' &= -\\frac{u'}{\\sqrt{1-u^2}} \\\\[3pt] (\\arctan u)' &= \\frac{u'}{1+u^2} & (\\operatorname{arccot} u)' &= -\\frac{u'}{1+u^2} \\\\[6pt] (\\sinh x)' &= \\cosh x & (\\cosh x)' &= \\sinh x & (\\tanh x)' &= \\frac{1}{\\cosh^2 x} \\\\[3pt] (\\coth x)' &= -\\frac{1}{\\sinh^2 x} \\end{aligned}"},{"h2":"Stručná sumarizácia"},{"p":["Rozlišujte ",{"math":"x^a"}," a ",{"math":"a^x"},". Exponenciála ",{"math":"e^x"}," je výnimočná tým, že sa derivovaním nemení. Pri sínuse je deriváciou kosínus: na vrchole a dne je zmena nulová, pri najstrmšom raste kladná a pri najstrmšom poklese záporná. Vzorce tak opisujú správanie grafu."]},{"test":"# Exponenciálne a goniometrické derivácie\n\n[ABCD]\nKtorý výsledok je správny?\n- (e^x)'=x e^(x-1)\n* (e^x)'=e^x\n- (e^x)'=ln(x)\n- (e^x)'=1/x\n\n[DROPDOWN]\nDerivácia funkcie sin(x) je {{výber}}.\n- -sin(x)\n* cos(x)\n- 1/cos²(x)\n- sin²(x)\n\n[ABCD]\nČo platí na hladkom vrchole sínusoidy?\n- Sínus je nulový a derivácia je maximálna.\n* Derivácia je nulová, pretože graf má vodorovnú dotyčnicu.\n- Derivácia neexistuje.\n- Kosínus je vždy kladný.\n\n[ODPOVEĎ]\nZderivuj funkciu 3e^x.\n= 3e^x | 3*e^x | 3eˣ\n\n[ABCD]\nKtorý výraz je deriváciou a^x?\n- xa^(x-1)\n- a^(x-1)\n* a^x ln(a)\n- 1/(a^x)"}]},{"id":"derivacie-05-retazove-pravidlo-2","title":"5. Zložená funkcia a reťazové pravidlo","blocks":[{"p":["Samotný prehľad jednoduchých vzorcov nestačí. Poznáme napríklad ",{"math":"(\\sin x)'=\\cos x"},". Na skúške však málokedy dostanete iba čisté ",{"math":"\\sin x"},". Vo vnútri býva ďalšia funkcia."],"role":"hook"},{"h2":"Vonkajšia a vnútorná funkcia"},{"p":["Pri zloženej funkcii rozlišujeme vonkajšiu funkciu a jej argument. Sínus je v tomto príklade vonkajšia funkcia. Pri ",{"math":"\\sin(x^2+6x-3)"}," je vonkajšia funkcia sínus a vnútorná funkcia je ",{"math":"u(x)=x^2+6x-3"},"."]},{"p":"Keď derivujeme celý objekt, najprv zachováme tvar vonkajšej funkcie podľa vzorca. Potom však musíme zderivovať aj to, čo je vo vnútri. To je reťazové pravidlo."},{"math":"\\bigl(F(u(x))\\bigr)'=F'(u(x))\\,u'(x)"},{"h2":"Skrytá jednotka pri jednoduchej funkcii"},{"p":["Prečo v jednoduchom vzorci nevidíme vnútornú deriváciu? Pretože pri ",{"math":"\\sin x"}," je vnútorná funkcia iba ",{"math":"u(x)=x"}," a jej derivácia je 1."]},{"math":"(\\sin x)'=\\cos x\\cdot1=\\cos x"},{"p":"Tá jednotka je tam stále, iba sa nepíše, lebo výsledok nemení. Pri zložitej funkcii už vnútorná derivácia nemusí byť 1, a preto ju nesmieme vynechať."},{"h2":"Postup pri reťazovom pravidle"},{"p":[{"b":"1."}," Nájdite vonkajšiu funkciu. ",{"b":"2."}," Jej jednoduchý vzorec prepíšte tak, že namiesto ",{"math":"x"}," ponecháte celý vnútorný výraz. ",{"b":"3."}," Za výsledok napíšte krát. ",{"b":"4."}," Zderivujte vnútorný výraz. ",{"b":"5."}," Ak je vo vnútri ďalšia zložená funkcia, postup zopakujte."]},{"math":"\\underbrace{ F\\Bigl( \\underbrace{ u\\bigl( \\underbrace{v(x)}_{\\text{vnútorná}} \\bigr) }_{\\text{stredná funkcia}} \\Bigr) }_{\\text{vonkajšia funkcia}}"},{"math":"f(x)=\\sin\\left(\\left[\\ln\\left(x^2+1\\right)\\right]^3\\right)\n\\begin{aligned} v(x)&=x^2+1, &&\\text{1. vnútorná funkcia},\\\\ u(v)&=\\ln(v), &&\\text{2. logaritmická funkcia},\\\\ P(u)&=u^3, &&\\text{3. mocninová funkcia},\\\\ F(P)&=\\sin(P), &&\\text{4. vonkajšia funkcia}. \\end{aligned}"},{"h2":"Príklad: sínus polynómu"},{"p":"Máme"},{"math":"f(x)=\\sin(x^2+6x-3)"},{"p":["Vonkajšia funkcia je sínus, takže ju zderivujeme na kosínus. Do kosínusu neopíšeme iba ",{"math":"x"},", ale celý pôvodný argument. Potom pripojíme deriváciu vnútra."]},{"math":"\\begin{aligned}f'(x)&=\\cos(x^2+6x-3)\\cdot(x^2+6x-3)'\\\\&=\\cos(x^2+6x-3)\\cdot(2x+6)\\end{aligned}"},{"p":["Typická nesprávna odpoveď je iba ",{"math":"\\cos(x^2+6x-3)"},". Tá by bola správna len vtedy, keby derivácia vnútra bola 1. Tu je však vnútorná derivácia ",{"math":"2x+6"},", takže musí zostať vo výsledku."]},{"h2":"Všeobecné tvary zložených funkcií"},{"p":["V každom riadku sa opakuje rovnaký vzor: zderivujeme vonkajšiu funkciu, celý vnútorný výraz ponecháme na jeho miestach a nakoniec násobíme ",{"math":"u'(x)"},"."]},{"math":"\\begin{aligned}(u^a)'&=a u^{a-1}u'\\\\(a^u)'&=a^u\\ln(a)\\,u'\\\\(e^u)'&=e^u u'\\\\(\\log_a u)'&=\\frac{u'}{u\\ln a}\\\\(\\ln|u|)'&=\\frac{u'}{u}\\\\(\\sin u)'&=\\cos(u)u'\\\\(\\cos u)'&=-\\sin(u)u'\\\\(\\tan u)'&=\\frac{u'}{\\cos^2(u)}\\\\(\\cot u)'&=-\\frac{u'}{\\sin^2(u)}\\end{aligned}"},{"math":"\\begin{aligned}(\\arcsin u)'&=\\frac{u'}{\\sqrt{1-u^2}}\\\\(\\arccos u)'&=-\\frac{u'}{\\sqrt{1-u^2}}\\\\(\\arctan u)'&=\\frac{u'}{1+u^2}\\\\(\\operatorname{arccot}u)'&=-\\frac{u'}{1+u^2}\\end{aligned}"},{"h2":"Dva ďalšie príklady rovnakou metódou"},{"p":["Pri ",{"math":"g(x)=e^{3x^2}"}," je vonkajšia funkcia exponenciála so základom ",{"math":"e"}," a vnútorná funkcia je ",{"math":"3x^2"},"."]},{"math":"g'(x)=e^{3x^2}\\cdot(3x^2)'=e^{3x^2}\\cdot6x"},{"p":["Pri ",{"math":"h(x)=\\ln|5x-1|"}," vonkajší vzorec vytvorí zlomok s pôvodným vnútrom v menovateli a deriváciou vnútra v čitateli. Funkcia aj jej derivácia sú definované pre x ≠ 1/5."]},{"math":"h'(x)=\\frac{(5x-1)'}{5x-1}=\\frac{5}{5x-1}"},{"h2":"Keď je vrstiev viac, postup sa cyklí"},{"p":["Pri funkcii ",{"math":"\\tan(\\sin(x^2))"}," máme tri vrstvy. Najprv derivujeme tangens, potom sínus a napokon ",{"math":"x^2"},". Každá vrstva pridá svoj faktor."]},{"math":"\\begin{aligned}\\bigl(\\tan(\\sin(x^2))\\bigr)'&=\\frac{1}{\\cos^2(\\sin(x^2))}\\cdot(\\sin(x^2))'\\\\&=\\frac{1}{\\cos^2(\\sin(x^2))}\\cdot\\cos(x^2)\\cdot2x\\end{aligned}"},{"p":"Nestrácajte sa tým, že sa pokúsite urobiť všetko naraz. Vždy sa pýtajte: Čo je teraz vonkajší obal? Čo je v jeho vnútri? A potom choďte o jednu vrstvu hlbšie."},{"h2":"Grafický experiment: čo pokazí vynechaná vnútorná derivácia"},{"p":["Modrý graf je ",{"math":"f(x)=\\sin(x^2+6x-3)"},". Červený graf je správna derivácia a oranžový graf je častá nesprávna odpoveď bez faktora ",{"math":"2x+6"},". Posúvajte bod a sledujte, že nesprávny graf niekedy náhodou trafí správnu hodnotu, ale všeobecne neopisuje sklon modrého grafu."]},{"graph":{"title":"Správna a zabudnutá vnútorná derivácia","bounds":[-7,1,-8,8],"commands":["p=-3","u(x)=x^2+6*x-3","f(x)=sin(u(x))","d(x)=cos(u(x))*(2*x+6)","w(x)=cos(u(x))","A=(p,f(p))","D=(p,d(p))","W=(p,w(p))","T=Tangent(A,f)","dif=abs(d(p)-w(p))"],"controls":[["p",-6.5,0.5,0.05,-3]],"tasks":[{"text":"Nájdite miesto, kde je správna derivácia nulová preto, že vnútorná derivácia 2x+6 je nulová. Sledujte vodorovnú dotyčnicu modrého grafu a porovnajte ju s oranžovou nesprávnou hodnotou.","condition":"p>-3.03 && p<-2.97 && abs(d(p))<0.05 && abs(w(p))>0.2"},{"text":"Dokážete nájsť miesto, kde sa nesprávna a správna derivácia náhodou takmer zhodujú? Zistite, akú hodnotu má vtedy faktor 2x+6 a prečo zhoda neplatí všeobecne.","condition":"p>-2.53 && p<-2.47 && dif<0.08"},{"text":"Nájdite miesto, kde sa správna a nesprávna derivácia výrazne líšia. Sledujte, ktorá z nich súhlasí so sklonom dotyčnice k modrému grafu.","condition":"dif>2.5"}],"expected":["p","u","f","d","w","A","D","W","T","dif"],"colors":{"f":[29,78,216],"d":[220,38,38],"w":[245,158,11],"A":[22,163,74],"D":[220,38,38],"W":[245,158,11],"T":[147,51,234]},"toolbar":true}},{"h2":"Záverečný pracovný checklist"},{"p":["Pred odovzdaním derivácie si položte päť otázok. ",{"b":"Je to súčet?"}," Derivujte člen po člene. ",{"b":"Je tam samostatná konštanta?"}," Tá ide na nulu. ",{"b":"Je tam koeficient pri funkcii?"}," Ten opíšte. ",{"b":"Je argument zložitejší než čisté x?"}," Pridajte vnútornú deriváciu. ",{"b":"Je vo vnútri ďalšia vrstva?"}," Pokračujte reťazovým pravidlom."]},{"h2":"Stručná sumarizácia"},{"p":["Pri jednoduchej funkcii je vnútornou funkciou ",{"math":"x"}," a jej derivácia 1 sa nepíše. Pri zloženej funkcii musí byť vnútorná derivácia vo výsledku. Postup je vždy rovnaký: zderivovať vonkajší obal, ponechať celý vnútorný výraz, vynásobiť deriváciou vnútra a podľa potreby pokračovať do ďalšej vrstvy."]},{"test":"# Reťazové pravidlo\n\n[ABCD]\nČo je vnútorná funkcia vo výraze sin(x²+6x-3)?\n- sin\n- cos\n* x²+6x-3\n- 2x+6\n\n[ABCD]\nKtorý výsledok je správny pre f(x)=sin(x²+6x-3)?\n- cos(x²+6x-3)\n- cos(2x+6)\n* cos(x²+6x-3)(2x+6)\n- sin(x²+6x-3)(2x+6)\n\n[DROPDOWN]\nPri jednoduchej funkcii sin(x) sa vnútorná derivácia rovná {{výber}}, preto sa bežne nepíše.\n- 0\n* 1\n- x\n- cos(x)\n\n[ODPOVEĎ]\nZderivuj funkciu e^(4x).\n= 4e^(4x) | 4*e^(4x)\n\n[ABCD]\nPrečo sa v derivácii 7x člen 7 nenuluje?\n- Pretože 7 je prvočíslo.\n* Pretože 7 je koeficient násobiaci funkciu x, nie samostatný sčítanec.\n- Pretože derivácia x je nula.\n- Pretože konštanty sa nikdy nederivujú.\n\n[ODPOVEĎ]\nZderivuj funkciu ln|3x-2|.\n= 3/(3x-2) | \\frac{3}{3x-2} | 3:(3x-2)\n\n[ABCD]\nPri funkcii tan(sin(x²)) sa reťazové pravidlo použije:\n- Ani raz.\n- Iba na x².\n* Opakovane, pretože funkcia má viac vnorených vrstiev.\n- Až po dosadení konkrétneho čísla."}]},{"id":"derivacie-06-retazove-pravidlo-vrstvy","title":"6. Reťazové pravidlo vo viacerých vrstvách","blocks":[{"p":"Pri zložitejších príkladoch je najdôležitejšie určiť poradie vrstiev. Začíname vonkajšou funkciou a postupujeme dovnútra, až kým sa nedostaneme k jednoduchej derivácii.","role":"hook"},{"h2":"Ako rozpoznať vrstvy"},{"p":"Každá funkcia má argument. Ak je argumentom ďalšia funkcia, použijeme reťazové pravidlo opakovane. Každá vrstva pridá do výsledku jeden derivačný faktor."},{"math":"\\bigl(F(G(H(x)))\\bigr)'=F'(G(H(x)))\\,G'(H(x))\\,H'(x)"},{"math":"f(x)=\\sin\\left(\\left[\\ln\\left(x^2+1\\right)\\right]^3\\right)\n\\begin{aligned} v(x)&=x^2+1, &&\\text{1. vnútorná funkcia},\\\\ u(v)&=\\ln(v), &&\\text{2. logaritmická funkcia},\\\\ P(u)&=u^3, &&\\text{3. mocninová funkcia},\\\\ F(P)&=\\sin(P), &&\\text{4. vonkajšia funkcia}. \\end{aligned}"},{"h2":"Príklad 1: kosínus s polynómom a logaritmom"},{"p":["Derivujme ",{"math":"f(x)=\\cos(6x^3-\\ln x+8)"},". Vnútorný logaritmus vyžaduje x>0. Vonkajšia funkcia je kosínus a jej argument opíšeme bez zmeny."]},{"math":"\\begin{aligned}f'(x)&=-\\sin(6x^3-\\ln x+8)\\,(6x^3-\\ln x+8)'\\\\&=-\\sin(6x^3-\\ln x+8)\\left(18x^2-\\frac1x\\right)\\end{aligned}"},{"p":"Mínus pred sínusom pochádza z derivácie kosínusu. Člen 18x² − 1/x je derivácia celého vnútorného súčtu; samostatná osmička sa zderivuje na nulu."},{"h2":"Príklad 2: arkustangens mocniny"},{"p":["Pri funkcii ",{"math":"g(x)=5\\arctan(x^2)"}," je číslo 5 konštantný koeficient. Argumentom arkustangensu je x², nie samotné x."]},{"math":"\\begin{aligned}g'(x)&=5\\cdot\\frac{(x^2)'}{1+(x^2)^2}\\\\&=5\\cdot\\frac{2x}{1+x^4}=\\frac{10x}{1+x^4}\\end{aligned}"},{"p":"Výraz (x²)² v menovateli je x⁴. Nesmie sa nahradiť iba x², pretože vo vzorci sa umocňuje celý argument arkustangensu."},{"h2":"Príklad 3: tri vnorené funkcie"},{"p":["Vo funkcii ",{"math":"h(x)=\\arcsin\\!\\bigl(\\log_5(\\cos(3x+6))\\bigr)"}," sú postupne vrstvy arcsin, logaritmus so základom 5, kosínus a lineárna funkcia 3x+6."]},{"math":"\\begin{aligned}h'(x)&=\\frac{1}{\\sqrt{1-\\left[\\log_5(\\cos(3x+6))\\right]^2}}\\\\&\\quad\\cdot\\frac{1}{\\cos(3x+6)\\ln5}\\cdot\\bigl[-\\sin(3x+6)\\bigr]\\cdot3\\end{aligned}"},{"p":"Derivácia existuje iba tam, kde je cos(3x+6)>0 a zároveň hodnota logaritmu leží striktne medzi −1 a 1. Výsledok nemusíme za každú cenu zlučovať do jedného zlomku; rozložený súčin jasne ukazuje jednotlivé vrstvy."},{"h2":"Kontrola postupu"},{"p":"Najprv označte vonkajšiu funkciu. Potom opíšte celý jej argument, pridajte jeho deriváciu a rovnaký postup opakujte dovnútra. Na konci skontrolujte znamienka, exponenty, definičný obor a to, či ste nezabudli deriváciu najvnútornejšej funkcie."},{"h2":"Stručná sumarizácia"},{"p":"Pri každej ďalšej vrstve vzniká ďalší faktor. Celé argumenty sa pri derivovaní vonkajšej funkcie opisujú a menia sa až v samostatnom faktore vnútornej derivácie."},{"test":"# Viacvrstvové reťazové pravidlo\n\n[ABCD]\nKtorá funkcia je vonkajšia vo výraze cos(6x³-ln(x)+8)?\n* cos\n- ln\n- 6x³\n- x\n\n[ABCD]\nAká je derivácia vnútorného výrazu 6x³-ln(x)+8?\n- 18x²+1/x\n* 18x²-1/x\n- 6x²-1/x\n- 18x³-1\n\n[DROPDOWN]\nV menovateli derivácie arctan(x²) sa nachádza 1+{{výber}}.\n- x²\n* x⁴\n- 2x\n- 4x\n\n[ODPOVEĎ]\nZderivuj funkciu 5arctan(x²).\n= 10x/(1+x^4) | 10x/(1+x⁴) | \\frac{10x}{1+x^4}\n\n[ABCD]\nPrečo sa pri viacvrstvovej funkcii objaví viac faktorov?\n- Pretože sa všetky exponenty sčítajú.\n- Pretože sa derivuje iba najvnútornejšia funkcia.\n* Pretože reťazové pravidlo sa použije na každú vnorenú vrstvu.\n- Pretože každá derivácia musí obsahovať logaritmus."}]},{"id":"derivacie-07-mocniny-odmocniny-zapis","title":"7. Mocniny, odmocniny a jednoznačný zápis","blocks":[{"p":"Pri mocninách a odmocninách môže jediná zátvorka zmeniť význam celého výrazu. Pred derivovaním preto najprv prepíšeme zadanie do jednoznačného tvaru a skontrolujeme jeho definičný obor.","role":"hook"},{"h2":"Na čo sa vzťahuje exponent"},{"p":["Zápis ",{"math":"(\\ln x)^2"}," znamená druhú mocninu hodnoty logaritmu. Zápis ",{"math":"\\ln(x^2)"}," znamená logaritmus argumentu x². Nie sú to rovnaké funkcie a majú odlišné derivácie aj definičné obory."]},{"math":"\\bigl((\\ln x)^2\\bigr)'=\\frac{2\\ln x}{x},\\qquad \\bigl(\\ln(x^2)\\bigr)'=\\frac{2}{x}\\quad(x\\ne0)"},{"p":"Zátvorky jednoznačne ukazujú, či umocňujeme výsledok funkcie alebo jej vnútorný argument. Pri nejasnom zápise ich vždy doplňte ešte pred výpočtom."},{"h2":"Odmocninu prepíšeme ako mocninu"},{"p":"Ak je základ kladný, môžeme odmocninu pohodlne prepísať pomocou zlomkového exponentu. Tým sa dostaneme k mocninovému a reťazovému pravidlu."},{"math":"\\sqrt[n]{u^m}=u^{m/n}\\qquad(u>0)"},{"h2":"Opravený príklad so štvrtou odmocninou"},{"p":["Uvažujme funkciu ",{"math":"f(x)=\\sqrt[4]{[\\ln(\\cos x+5)]^3}"},". Keďže cos x+5 je vždy medzi 4 a 6, logaritmus je kladný a prepis na zlomkovú mocninu je bezpečný."]},{"math":"f(x)=[\\ln(\\cos x+5)]^{3/4}"},{"math":"\\begin{aligned}f'(x)&=\\frac34[\\ln(\\cos x+5)]^{-1/4}\\cdot\\frac{-\\sin x}{\\cos x+5}\\end{aligned}"},{"p":"Najprv sa derivuje vonkajšia mocnina 3/4, potom logaritmus a napokon výraz cos x+5. Každá vrstva pridá vlastný faktor."},{"h2":"Premenná v menovateli"},{"p":["Pri výraze ",{"math":"\\frac{3}{x^4}"}," presunieme mocninu do čitateľa so záporným exponentom. Tento krok nemení definičný obor: stále musí platiť x≠0."]},{"math":"\\frac{3}{x^4}=3x^{-4},\\qquad \\left(\\frac{3}{x^4}\\right)'=-12x^{-5}=-\\frac{12}{x^5}"},{"h2":"Najprv skontrolujte, či výraz obsahuje premennú"},{"p":["Výraz zložený iba z čísel a konštánt, napríklad ",{"math":"\\sqrt[3]{\\pi^2+5}"},", je vzhľadom na x konštantný. Jeho derivácia podľa x je preto nula, hoci samotný zápis vyzerá zložito."]},{"math":"\\left(\\sqrt[3]{\\pi^2+5}\\right)'=0"},{"h2":"Premenná nemusí byť x"},{"p":["Ak derivujeme podľa t, potom t plní úlohu premennej a ostatné písmená sa považujú za konštanty, pokiaľ zadanie neurčí inak. Napríklad pri konštantnom a platí ",{"math":"\\frac{d}{dt}(at^3)=3at^2"},"."]},{"h2":"Stručná sumarizácia"},{"p":"Doplňte zátvorky, odmocninu prepíšte na mocninu iba pri zachovaní definičných podmienok, výraz v menovateli môžete zapísať so záporným exponentom a pred výpočtom vždy overte, podľa ktorej premennej derivujete."},{"test":"# Mocniny, odmocniny a zápis\n\n[ABCD]\nČo znamená zápis (ln(x))²?\n* Druhú mocninu hodnoty ln(x).\n- Logaritmus z x².\n- Druhú deriváciu logaritmu.\n- Logaritmus so základom 2.\n\n[ABCD]\nAko prepíšeme 3/x⁴ pomocou záporného exponentu?\n- 3x⁴\n* 3x^(-4)\n- x^(-12)\n- -3x⁴\n\n[ODPOVEĎ]\nZderivuj funkciu 3/x⁴.\n= -12/x^5 | -12/x⁵ | -12x^(-5) | -12x⁻⁵\n\n[DROPDOWN]\nAk výraz neobsahuje premennú, podľa ktorej derivujeme, jeho derivácia je {{výber}}.\n* 0\n- 1\n- samotný výraz\n- nedefinovaná\n\n[ABCD]\nPrečo sú pri mocninách funkcií dôležité zátvorky?\n- Menia každé plus na mínus.\n- Vždy odstránia definičný obor.\n* Určujú, na ktorý výraz sa exponent vzťahuje.\n- Nahrádzajú reťazové pravidlo."}]},{"id":"derivacie-08-sucin-a-podiel-2","title":"8. Derivácia súčinu a podielu funkcií","blocks":[{"p":"Pri súčte derivujeme člen po člene, ale pri násobení a delení dvoch funkcií to nestačí. Potrebujeme pravidlo pre súčin alebo podiel a až potom derivujeme vnútorné časti.","role":"hook"},{"h2":"Pravidlo pre súčin"},{"math":"(u\\,v)'=u'v+uv'"},{"p":"Vytvoríme dva sčítance. V prvom zderivujeme prvú funkciu a druhú opíšeme. V druhom prvú opíšeme a zderivujeme druhú. Poradie faktorov možno vďaka komutatívnosti násobenia zameniť, ale oba sčítance musia zostať."},{"h2":"Príklad so zloženou exponenciálou"},{"p":["Derivujme ",{"math":"f(x)=(x^2+1)e^{3x}"},". Prvou funkciou je x²+1 a druhou e^(3x)."]},{"math":"\\begin{aligned}f'(x)&=(x^2+1)'e^{3x}+(x^2+1)(e^{3x})'\\\\&=2x\\,e^{3x}+(x^2+1)\\,3e^{3x}\\end{aligned}"},{"p":"V druhom sčítanci sa pri exponenciále použilo aj reťazové pravidlo, pretože derivácia exponentu 3x je 3."},{"h2":"Konštantný faktor nepotrebuje pravidlo pre súčin"},{"p":["Ak je jeden faktor konštanta, stačí ju opísať: ",{"math":"(5u)'=5u'"},". Pravidlo pre súčin by dalo rovnaký výsledok, ale zbytočne by vytvorilo člen s deriváciou konštanty, teda s nulou."]},{"h2":"Pravidlo pre podiel"},{"math":"\\left(\\frac{u}{v}\\right)'=\\frac{u'v-uv'}{v^2},\\qquad v\\ne0"},{"p":"V čitateli zachováme poradie: derivácia čitateľa krát menovateľ mínus čitateľ krát derivácia menovateľa. V menovateli je druhá mocnina pôvodného menovateľa."},{"h2":"Zložitejší príklad"},{"p":["Označme ",{"math":"N(x)=\\log_7(e^{3x}+\\cos x)"}," a ",{"math":"D(x)=\\arcsin(x^2)"},". Najprv vypočítame ich derivácie samostatne."]},{"math":"N'(x)=\\frac{3e^{3x}-\\sin x}{(e^{3x}+\\cos x)\\ln7}"},{"math":"D'(x)=\\frac{2x}{\\sqrt{1-x^4}}"},{"p":["Pre funkciu ",{"math":"q(x)=\\frac{N(x)}{D(x)}"}," potom použijeme pravidlo pre podiel."]},{"math":"\\begin{aligned}q'(x)=\\frac{\\displaystyle \\frac{3e^{3x}-\\sin x}{(e^{3x}+\\cos x)\\ln7}\\,\\arcsin(x^2)-\\log_7(e^{3x}+\\cos x)\\,\\frac{2x}{\\sqrt{1-x^4}}}{[\\arcsin(x^2)]^2}\\end{aligned}"},{"p":"Derivácia je v uvedenom reálnom tvare definovaná pre −1<x<1 a x≠0. Koncové body vylučuje derivácia arcsin(x²) a bod x=0 vylučuje pôvodný menovateľ arcsin(x²)."},{"h2":"Pracovný postup bez straty zátvoriek"},{"p":"Najprv označte celé funkcie u a v. Napíšte prázdnu štruktúru pravidla pre súčin alebo podiel, doplňte nederivované výrazy a až potom počítajte u′ a v′. Zátvorky ponechajte dovtedy, kým nie je jasné, ktoré časti patria k sebe."},{"h2":"Najčastejšie chyby"},{"p":"Nesprávne je (uv)′=u′v′ aj (u/v)′=u′/v′. Pri podiele sa často zabudne mínus alebo druhá mocnina menovateľa. Pri zložených faktoroch sa navyše musí použiť reťazové pravidlo vo vnútri u′ alebo v′."},{"h2":"Stručná sumarizácia"},{"p":"Súčin vytvára súčet dvoch členov, podiel vytvára rozdiel v čitateli a druhú mocninu menovateľa. Samotné faktory môžu byť zložené funkcie, preto sa pravidlá pre súčin, podiel a reťazové pravidlo často kombinujú."},{"test":"# Súčin a podiel funkcií\n\n[ABCD]\nKtorý vzorec je správny pre deriváciu súčinu uv?\n- u'v'\n* u'v+uv'\n- u'v-uv'\n- u/v\n\n[ABCD]\nČo sa nachádza v menovateli derivácie podielu u/v?\n- u²\n* v²\n- u'v'\n- v'\n\n[ODPOVEĎ]\nZderivuj funkciu (x²+1)e^(3x).\n= 2x*e^(3x)+3(x^2+1)e^(3x) | 2xe^(3x)+3(x²+1)e^(3x)\n\n[DROPDOWN]\nV čitateli pravidla pre podiel je medzi členmi znamienko {{výber}}.\n- plus\n* mínus\n- krát\n- delené\n\n[ABCD]\nPrečo sa pri derivovaní e^(3x) objaví faktor 3?\n- Pretože e sa rovná 3.\n- Pretože používame pravidlo pre podiel.\n* Pretože podľa reťazového pravidla derivujeme aj exponent 3x.\n- Pretože každá exponenciála má deriváciu 3."}]},{"id":"lekcia-opakovanie","title":"Opakovanie","blocks":[{"math":"\\begin{aligned} 1.\\quad &f'(x)=0 \\\\[8pt] 2.\\quad &f'(x)=1 \\\\[8pt] 3.\\quad &f'(x)=5x^4 \\\\[8pt] 4.\\quad &f'(x)=-\\frac{12}{x^5} \\\\[8pt] 5.\\quad &f'(x)=7^x\\ln7 \\\\[8pt] 6.\\quad &f'(x)=0 \\\\[8pt] 7.\\quad &f'(x)=0 \\\\[8pt] 8.\\quad &f'(x)=0 \\\\[8pt] 9.\\quad &f'(x)=0 \\\\[8pt] 10.\\quad &f'(x)=10x\\cos\\left(5x^2\\right) \\\\[8pt] 11.\\quad &f'(x)=-\\sin\\left(6x^3-\\ln x+8\\right) \\left(18x^2-\\frac{1}{x}\\right) \\\\[8pt] 12.\\quad &f'(x)=\\frac{10x}{1+x^4} \\\\[8pt] 13.\\quad &f'(x)=\\frac{4x^3+15x^2}{x^4+5x^3} \\\\[8pt] 14.\\quad &f'(x)=-\\frac{20}{x\\ln^2\\left(x^4\\right)} \\\\[8pt] 15.\\quad &f'(x)=-\\frac{42x^6+8} {\\left(6x^7+8x-4\\right) \\sin^2\\left(\\ln\\left(6x^7+8x-4\\right)\\right)} \\\\[8pt] 16.\\quad &f'(x)=\\frac{2x} {7\\left(\\arcsin\\left(x^2\\right)\\right)^{\\frac67}\\sqrt{1-x^4}} \\\\[8pt] 17.\\quad &f'(x)=-\\frac{3\\sin(x+5)} {4\\cos(x+5)\\left(\\ln\\left(\\cos(x+5)\\right)\\right)^{\\frac14}} \\\\[8pt] 18.\\quad &f'(x)=-\\frac{3\\sin(3x+6)} {\\cos(3x+6)\\ln5 \\sqrt{1-\\left(\\log_5\\left(\\cos(3x+6)\\right)\\right)^2}} \\\\[8pt] 19.\\quad &f'(x)=\\frac{\\sin x\\cos(\\cos x)} {\\sin^2\\left(\\sin(\\cos x)\\right)} \\\\[8pt] 20.\\quad &f'(x)=\\frac{54x^2\\left(6x^3+\\ln(2\\pi)\\right)^2} {\\sqrt{1-\\left(6x^3+\\ln(2\\pi)\\right)^6}} \\\\[8pt] 21.\\quad &f'(x)=3e^{3\\sin x}\\cos^5x -4e^{3\\sin x}\\cos^3x\\sin x +\\frac{1}{2\\sqrt{x}(1+x)} \\\\[8pt] 22.\\quad &f'(x)=\\frac{2x\\ln2(2x+3)-2x^2\\ln2}{(2x+3)^2} -\\frac{12x^3-2}{3x^4-2x+7} \\\\[8pt] 23.\\quad &f'(x)=3e^{3x}(\\cos x)^8 -8e^{3x}(\\cos x)^7\\sin x +\\frac{1}{(x-1)^2\\sqrt{\\frac{x+1}{x-1}}} \\\\[8pt] 24.\\quad &f'(x)=-\\frac{4x^3+15x^2}{x^4+5x^3} \\\\[8pt] 25.\\quad &f'(x)=x^4\\ln x\\cos x+x^3\\sin x +4x^3\\ln x\\sin x \\\\[8pt] 26.\\quad &f'(x)=e^{3x^2} \\left[ \\left(2\\cos(2x)+6x\\sin(2x)\\right)\\ln\\left(5x^6\\right) +\\frac{6\\sin(2x)}{x} \\right] \\\\[8pt] 27.\\quad &f'(x)=\\frac{3\\arccos\\left(x^2\\right)}{x\\ln7} -\\frac{2x\\log_7\\left(x^3\\right)}{\\sqrt{1-x^4}} \\\\[8pt] 28.\\quad &f'(x)=\\frac{5}{x}\\arccos\\left(3x^7+2\\right) -\\frac{21x^6\\ln\\left(3x^5\\right)} {\\sqrt{1-\\left(3x^7+2\\right)^2}} \\\\[8pt] 29.\\quad &f'(x)=-\\frac{3\\ln^2x}{x\\sin^2(\\ln x)} +\\frac{6\\ln x\\operatorname{cotg}(\\ln x)}{x} \\\\[8pt] 30.\\quad &f'(x)=e^{5x+3} \\left[ \\frac{6x+8}{\\cos^2\\left(3x^2+8x-4\\right)} +5\\operatorname{tg}\\left(3x^2+8x-4\\right) \\right] \\\\[8pt] 31.\\quad &f'(x)= \\frac{ \\frac{3e^{3x}-\\sin x}{\\left(e^{3x}+\\cos x\\right)\\ln7} \\arcsin\\left(x^2\\right) -\\log_7\\left(e^{3x}+\\cos x\\right)\\frac{2x}{\\sqrt{1-x^4}} } {\\left(\\arcsin\\left(x^2\\right)\\right)^2} \\\\[8pt] 32.\\quad &f'(x)=e^{-(3x^5+4)} \\left[ \\frac{2x}{\\cos^2\\left(x^2\\right)} -15x^4\\operatorname{tg}\\left(x^2\\right) \\right] \\\\[8pt] 33.\\quad &f'(x)= \\frac{ 6xe^{\\sin\\left(3x^2\\right)} \\cos\\left(3x^2\\right) \\operatorname{arccotg}\\left(5x^4+7x-3\\right) + e^{\\sin\\left(3x^2\\right)} \\frac{20x^3+7}{1+\\left(5x^4+7x-3\\right)^2} } {\\operatorname{arccotg}^2\\left(5x^4+7x-3\\right)} \\\\[8pt] 34.\\quad &f'(x)= \\frac{ -5\\sin(5x)\\operatorname{tg}\\left(2x^6\\right) -\\cos(5x)\\frac{12x^5}{\\cos^2\\left(2x^6\\right)} } {\\operatorname{tg}^2\\left(2x^6\\right)} \\cdot7^{x^3} \\\\ &\\qquad+ \\frac{\\cos(5x)}{\\operatorname{tg}\\left(2x^6\\right)} \\cdot7^{x^3}\\ln7\\cdot3x^2 \\\\[8pt] 35.\\quad &f'(x)=\\left(3-x^2\\right)^{\\operatorname{tg}x} \\left[ \\frac{\\ln\\left(3-x^2\\right)}{\\cos^2x} -\\frac{2x\\operatorname{tg}x}{3-x^2} \\right] \\\\[8pt] 36.\\quad &f'(x)=(\\sin5x)^{e^{3x^6}}e^{3x^6} \\left[ 18x^5\\ln(\\sin5x) +\\frac{5\\cos5x}{\\sin5x} \\right] \\\\[8pt] 37.\\quad &f'(x)=(\\sin x)^{3\\ln x} \\left[ \\frac{3}{x}\\ln(\\sin x) +3\\ln x\\frac{\\cos x}{\\sin x} \\right] \\end{aligned}"},{"math":"\\begin{aligned} 1.\\quad &f(x)=5 \\\\[8pt] 2.\\quad &f(x)=x \\\\[8pt] 3.\\quad &f(x)=x^5 \\\\[8pt] 4.\\quad &f(x)=\\frac{3}{x^4} \\\\[8pt] 5.\\quad &f(x)=7^x \\\\[8pt] 6.\\quad &f(x)=\\sin\\left(\\frac{\\pi}{3}\\right) \\\\[8pt] 7.\\quad &f(x)=\\arcsin\\left(6\\pi^2-4\\cos\\left(8\\pi^2\\right)\\right) \\\\[8pt] 8.\\quad &f(x)=\\operatorname{arctg}^3\\left(\\sin^2(3\\pi-8)\\right) \\\\[8pt] 9.\\quad &f(x)=\\sqrt[5]{\\operatorname{arctg}^4\\left(\\sin^2\\pi-3\\right)} \\\\[8pt] 10.\\quad &f(x)=\\sin\\left(5x^2\\right) \\\\[8pt] 11.\\quad &f(x)=\\cos\\left(6x^3-\\ln x+8\\right) \\\\[8pt] 12.\\quad &f(x)=5\\operatorname{arctg}\\left(x^2\\right) \\\\[8pt] 13.\\quad &f(x)=\\ln\\left(x^4+5x^3\\right) \\\\[8pt] 14.\\quad &f(x)=\\frac{5}{\\ln\\left(x^4\\right)} \\\\[8pt] 15.\\quad &f(x)=\\operatorname{cotg}\\left(\\ln\\left(6x^7+8x-4\\right)\\right) \\\\[8pt] 16.\\quad &f(x)=\\sqrt[7]{\\arcsin\\left(x^2\\right)} \\\\[8pt] 17.\\quad &f(x)=\\sqrt[4]{\\ln^3\\left(\\cos(x+5)\\right)} \\\\[8pt] 18.\\quad &f(x)=\\arcsin\\left(\\log_5\\left(\\cos(3x+6)\\right)\\right) \\\\[8pt] 19.\\quad &f(x)=\\operatorname{cotg}\\left(\\sin(\\cos x)\\right) \\\\[8pt] 20.\\quad &f(x)=\\arcsin\\left(\\left(6x^3+\\ln(2\\pi)\\right)^3\\right) \\\\[8pt] 21.\\quad &f(x)=e^{3\\sin x}(\\cos x)^4+\\operatorname{arctg}\\sqrt{x} \\\\[8pt] 22.\\quad &f(x)=\\frac{x^2\\ln2}{2x+3}-\\ln\\left(3x^4-2x+7\\right) \\\\[8pt] 23.\\quad &f(x)=e^{3x}(\\cos x)^8-\\sqrt{\\frac{x+1}{x-1}} \\\\[8pt] 24.\\quad &f(x)=\\sin\\left(\\frac{\\pi}{3}\\right)-\\ln\\left(x^4+5x^3\\right) \\\\[8pt] 25.\\quad &f(x)=\\sin x\\cdot\\ln x\\cdot x^4 \\\\[8pt] 26.\\quad &f(x)=\\sin(2x)e^{3x^2}\\ln\\left(5x^6\\right) \\\\[8pt] 27.\\quad &f(x)=\\log_7\\left(x^3\\right)\\arccos\\left(x^2\\right) \\\\[8pt] 28.\\quad &f(x)=\\ln\\left(3x^5\\right)\\arccos\\left(3x^7+2\\right) \\\\[8pt] 29.\\quad &f(x)=3\\operatorname{cotg}(\\ln x)\\ln^2x \\\\[8pt] 30.\\quad &f(x)=\\operatorname{tg}\\left(3x^2+8x-4\\right)e^{5x+3} \\\\[8pt] 31.\\quad &f(x)=\\frac{\\log_7\\left(e^{3x}+\\cos x\\right)} {\\arcsin\\left(x^2\\right)} \\\\[8pt] 32.\\quad &f(x)=\\frac{\\operatorname{tg}\\left(x^2\\right)}{e^{3x^5+4}} \\\\[8pt] 33.\\quad &f(x)=\\frac{e^{\\sin\\left(3x^2\\right)}} {\\operatorname{arccotg}\\left(5x^4+7x-3\\right)} \\\\[8pt] 34.\\quad &f(x)=\\frac{\\cos(5x)} {\\operatorname{tg}\\left(2x^6\\right)}\\cdot7^{x^3} \\\\[8pt] 35.\\quad &f(x)=\\left(3-x^2\\right)^{\\operatorname{tg}x} \\\\[8pt] 36.\\quad &f(x)=(\\sin 5x)^{e^{3x^6}} \\\\[8pt] 37.\\quad &f(x)=(\\sin x)^{3\\ln x} \\end{aligned}"},{"test":"# Krátky test\n\n[ABCD]\nKtoré tvrdenie je správne?\n* Toto je správna odpoveď.\n- Toto je nesprávna odpoveď.\n- Ani táto odpoveď nie je správna.\n- Táto možnosť je tiež nesprávna.\n\n[DROPDOWN]\nDoplňte správnu možnosť: {{výber}} patrí do zadania.\n* správna odpoveď\n- prvá nesprávna odpoveď\n- druhá nesprávna odpoveď\n\n[ODPOVEĎ]\nNapíšte číselnú alebo textovú odpoveď.\n= správna odpoveď | alternatíva"}]},{"id":"lekcia-trening","title":"Tréning","blocks":[{"review":true}]}],"description":"Kurz vysvetľuje deriváciu od významu zmeny a sklonu grafu cez mocninové, exponenciálne a goniometrické funkcie až po reťazové pravidlo, mocniny, odmocniny, súčin a podiel funkcií. Dôraz je na správne rozpoznanie štruktúry výrazu, definičných podmienok a na kontrolu jednotlivých krokov.","icon":"∫"}],"active":"lekcia-trening"};
